object Main {
  val MOD = 1000000007
  def solve(): Unit = {
    val sc = new InputReader(System.in)
    val N = sc.nextInt()
    val d = Array.ofDim[Int](N, N)
    for {
      i <- 0 until N
      j <- 0 until N
    } d(i)(j) = sc.nextInt()

    def calc: Option[Long] = {
      var ok = true
      var cut: Long = 0
      for {
        k <- 0 until N
        i <- 0 until N - 1
        j <- i until N
      } {
        if (k != i && k != j) {
          if (d(i)(k) + d(k)(j) == d(i)(j)) {
            cut += d(i)(j)
          } else {
            ok &= d(i)(k) + d(k)(j) > d(i)(j)
          }
        }
      }

      var sum: Long = 0
      for {
        i <- 0 until N - 1
        j <- i until N
      } sum += d(i)(j)

      if (ok) Some(sum - cut) else None
    }

    val ans = (calc getOrElse -1).toString

    println(ans)
  }


  def main(args: Array[String]): Unit = {
    solve()
  }


  class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = null

    def next: String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next.toInt
    def nextLong(): Long = next.toLong
    def nextChar(): Char = next.charAt(0)
  }

  class UnionFind(n: Int) {
    private val par = Array.iterate(0, n)(_ + 1)
    private val rank = Array.ofDim[Int](n)

    def find(x: Int): Int = {
      if (par(x) == x) x
      else {
        par(x) = find(par(x))
        par(x)
      }
    }

    def unite(x: Int, y: Int): Unit = {
      val x1 = find(x)
      val y1 = find(y)
      if (x1 != y1) {
        if (rank(x1) < rank(y)) {
          par(x1) = y1
        } else {
          par(y1) = x1
          if (rank(x1) == rank(y1)) rank(x1) += 1
        }
      }
    }
  }
}

