bool flag = false;

void floyd(){
    for(int k = 1; k <= n; k++){
        for(int i = 1; i <= n; i++){
            for(int j = 1; j <= n; j++){
                a[i][j] = min(a[i][j], a[i][k] + a[k][j]);
            }
        }
    }
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            if(i == j) continue;
            if(a[i][j] != temp[i][j]) flag = true;
        }
    }
}

void solve(){
    memset(cnt, 0, sizeof(cnt));
    for(int k = 1; k <= n; k++){
        for(int i = 1; i <= n; i++){
            for(int j = 1; j <= n; j++){
                if(i == j) continue;
                if(a[i][j] <  a[i][k] + a[k][j]) cnt[i][j]++;
            }
        }
    }
    LL ans = 0;
    for(int i = 1; i <= n; i++){
        for(int j = i + 1; j <= n; j++){
            if(cnt[i][j] == n) ans += a[i][j];
        }
    }
    printf("%lld\n", ans);
}


