using namespace std;

typedef long long int Int;

Int city[300][300];
Int dist[300][300];
bool check[300][300];

bool exist(int start,int end,int n)
{
    bool flag = true;
    for(int i = 0;i < n;i++) {
	if(start == i || i == end)
	    continue;
	if(dist[start][i]+dist[i][end] == city[start][end])
	    flag = false;
    }

    return flag;
}

int main(void)
{
    Int n;
    cin>>n;

    for(int i = 0;i < n;i++) {
	for(int j = 0;j < n;j++) {
	    Int temp;
	    cin>>temp;

	    city[i][j] = temp;
	}
    }

    for(int i = 0;i < n;i++) {
	for(int j = 0;j < n;j++) {
	    check[i][j] = false;
	    if(i != j)
		dist[i][j] = 2e9;
	    else
		dist[i][j] = 0;
	}
    }

    for(int i = 0;i < n;i++) {
	for(int s = 0;s < n;s++) {
	    for(int e = 0;e < n;e++) {
		Int mini = dist[s][e];
		Int maxi = city[s][i]+city[i][e];
		if(mini < maxi)
		{
		    dist[s][e] = mini;
		} else {
		    dist[s][e] = maxi;
		}
	    }
	}
    }

    Int ans = 0;
    bool flag = false;
    for(int i = 0;i < n;i++) {
	for(int j = 0;j < n;j++) {
	    if(dist[i][j] == city[i][j])
	    {
		if(check[i][j])
		    continue;
		if(!exist(i,j,n))
		    continue;
		check[i][j] = check[j][i] = true;
		ans += dist[i][j];
	    }
	    else
		flag = true;
	}
    }

    if(flag)
	cout<<-1<<endl;
    else
	cout<<ans<<endl;

    return 0;
}

