const int N = 305;
const LL INF = (1LL<<50);

struct Edge
{
	LL u, v, w, sel;
	bool operator < (const Edge& r) const
	{
		return w < r.w;
	}
} e[N * N];
int n, tot;
LL a[N][N], dist[N][N];

bool check(int m)
{
	if (m >= tot)  return false;
	rep(i, 1, n + 1) rep(j, 1, n + 1)  dist[i][j] = (i == j ? 0 : INF);
	rep(i, 0, tot)  e[i].sel = 0;
	rep(i, 0, m + 1)
	{
		LL u = e[i].u, v = e[i].v, w = e[i].w;
		rep(j, 1, n + 1)
			if (dist[j][u] + w < dist[j][v] || dist[j][v] + w < dist[j][u])
			{
				e[i].sel = 1;
				break;
			}
		rep(j, 1, n + 1)
			if (w + dist[u][j] < dist[v][j] || w + dist[v][j] < dist[u][j])
			{
				e[i].sel = 1;
				break;
			}
		if (e[i].sel)
		{
			rep(i, 1, n + 1)
				rep(j, i + 1, n + 1)
				{
					if (dist[i][u] + w + dist[v][j] < dist[i][j])  dist[i][j] = dist[j][i] = dist[i][u] + w + dist[v][j];
					if (dist[i][v] + w + dist[u][j] < dist[i][j])  dist[i][j] = dist[j][i] = dist[i][v] + w + dist[u][j];
				}
		}
	}
	rep(i, 1, n + 1)
		rep(j, i + 1, n + 1)
			if (dist[i][j] != a[i][j])  return false;
	return true;
}

int main()
{
	#ifdef M1saki
		setI;
	#endif
//	ios::sync_with_stdio(false);
	scanf("%d", &n);
	rep(i, 1, n + 1) rep(j, 1, n + 1) scanf("%lld", &a[i][j]);
	tot = 0;
	rep(i, 1, n + 1)
		rep(j, i + 1, n + 1)
			e[tot++] = Edge{i, j, a[i][j], 0};
	sort(e, e + tot);
	int l = 0, r = tot;
	while (l < r)
	{
		int mid = l + r >> 1;
		if (check(mid))  r = mid;
		else l = mid + 1;
	}
	if (l >= tot)  return 0 * printf("-1\n");
	LL ans = 0;
	check(l);
	rep(i, 0, l + 1) if (e[i].sel) ans += e[i].w;
	printf("%lld\n", ans);

	return 0;
}

