	cin>>N;
	array<array<ll,300>,300> A;
	REP(i,N){
		REP(j,N){
			cin>>A[i][j];
			B[i][j] = 1;
		}
	}

	warshallFloyd(A,N);

	REP(i,N){
		REP(j,N){
			douro += A[i][j] * B[i][j];
		}
	}

	if(!isA){
		cout<<-1<<endl;
	}
	else{
		cout<<douro / 2 <<endl;
	}

	return 0;
}

