/* Dijkstra O(NlogM)*/

struct Dijkstra{

  typedef ll Type;

  int V;
  vector<vector<pair<int,Type> > > G;
  vector<int> cost;

  Dijkstra(int n):
    V(n),G(n,vector<pair<int,Type> >()){}

  void add_edge(int u, int v, Type c){
    G[u].push_back({v,c});
  }

  Type solve(int s, int g = -1){
    cost.assign(V,-1);
    priority_queue<pair<Type,int> > pq;
    Type max_cost = 0;

    pq.push({0,s});

    while(pq.size()){
      Type now_cost = pq.top().first;
      int now = pq.top().second;
      pq.pop();

      if(cost[now] >= 0) continue;

      cost[now] = -now_cost;
      max_cost = max(max_cost, -now_cost);

      if(now == g) return -now_cost;

      for(int i=0;i<(int)G[now].size();i++){
        pq.push({now_cost-G[now][i].second, G[now][i].first});
      }
    }

    return INF;
  }

};

int main(){
  int n;
  int a[SIZE][SIZE];
  pair<int,pair<int,int> > dist_list[SIZE*SIZE];
  scanf("%d",&n);

  int t = 0;

  for(int i=0;i<n;i++){
    for(int j=0;j<n;j++){
      scanf("%d",a[i]+j);

      if(i > j){
        dist_list[t++] = {a[i][j],{i,j}};
      }
    }
  }

  sort(dist_list,dist_list+t);

  ll ans = 0;

  Dijkstra dijk(n);

  for(int i=0;i<t;i++){
    int p = dist_list[i].second.first;
    int q = dist_list[i].second.second;
    int d = dist_list[i].first;

    ll dist_p_q = dijk.solve(p,q);

    if(dist_p_q < d){
      puts("-1");
      return 0;
    }

    if(dist_p_q == INF || dist_p_q != d){
      dijk.add_edge(p,q,d);
      dijk.add_edge(q,p,d);
      ans += d;
    }
  }


  printf("%lld\n",ans);

  return 0;
}

