long long find_min_total_dist(int N, const vvll & dist){
    vvll ans = dist;
    for (int k = 0; k < N; ++k){
        for (int i = 0; i < N; ++i){
            if (i == k) continue;
            for (int j = 0; j < N; ++j){
                if (j == k) continue;
                if (dist[i][j] > dist[i][k] + dist[k][j]) return -1;
                if (dist[i][j] == dist[i][k] + dist[k][j]){
                    ans[i][j] = 0;
                }
            }
        }
    }
    long long total_dist = 0;
    for (int i = 1; i < N; ++i){
        for (int j = 0; j < i; ++j){
            total_dist += ans[i][j];
        }
    }
    return total_dist;
}


