constexpr int inf = 1e9+7;

struct edge {
  int t, w;
  edge(int t, int w) : t(t), w(w) {}
};

int in[301][301], n;
long long dist[301];
vector<tuple<int,int,int>> eg;
vector<edge> g[301];

int foo(int f, int t) {
  for(int i=0;i<n;i++) dist[i] = inf;
  dist[f] = 0;
  priority_queue<pair<int,int>> pq;
  pq.emplace(0,f);
  while(!pq.empty()) {
    int w, c;
    tie(w,c) = pq.top();
    pq.pop();
    w=-w;
    if(w > dist[c]) continue;
    for(auto & e : g[c]) {
      int ww = w + e.w;
      if(ww >= dist[e.t]) continue;
      dist[e.t] = ww;
      pq.emplace(-ww,e.t);
    }
  }
  return dist[t];
}

