          puts("-1");
          return 0;
        }
      }
  for(int i=0;i<n;i++)
    for(int j=i+1;j<n;j++)
      eg.emplace_back(in[i][j],i,j);
  sort(eg.begin(), eg.end());

  long long ans = 0;
  for(auto & e : eg) {
    int w,a,b;
    tie(w,a,b) = e;
    int d = foo(a,b);
