void dijkstra(int src)
{
  priority_queue<pair<ll,int> > pq;
  rep(i,1,n+1) dist[i]=inf;
  dist[src]=0;
  pq.push(mp(0,src));
  while(!pq.empty())
    {
      auto x1=pq.top();
      pq.pop();
      int u=x1.se; ll we=-x1.fi;
      if(we>dist[u]) continue;
      for(int idx:v[u])
	{
	  int v1=(x[idx]^y[idx]^u);
	  if(dist[u]+w[idx]<dist[v1])
	    {
	      dist[v1]=dist[u]+w[idx];
	      pq.push(mp(-dist[v1],v1));
	    }
	}
    }
  rep(i,1,n+1) d[src][i]=dist[i];
}
