#define int ll

void solve() {
	int N; cin >> N;
	vector<int> leftDP(N + 1);
	vector<int> rightDP(N + 1);
	vector<int> A(N * 3); for (auto &a : A) cin >> a;
	priority_queue<int, vector<int>, greater<int>> que;
	int sum = 0;
	REP(i, N) sum += A[i];
	REP(i, N) que.push(A[i]);
	leftDP[0] = sum;
	FOR(i, N + 1, 2 * N + 1) {
		que.push(A[i]);
		int top = que.top(); que.pop();
		leftDP[i - N] = leftDP[i - 1 - N] - top + A[i - 1];
	}

	vector<int> IA = A;
	reverse(ALL(IA));
	for (auto &a : IA) a *= -1;
	que = decltype(que)();
	sum = 0;
	REP(i, N) sum += IA[i];
	REP(i, N) que.push(IA[i]);
	rightDP[0] = sum;
	FOR(i, N + 1, 2 * N + 1) {
		que.push(IA[i]);
		int top = que.top(); que.pop();
		rightDP[i - N] = rightDP[i - 1 - N] - top + IA[i - 1];
	}
	int ma = leftDP[0] + rightDP[N];
	REP(i, N+1) {
		ma = max(leftDP[i] + rightDP[N - i], ma);
	}
	cout << ma << endl;
}

