			A[i].push_back(in());
			cost[i][j] = INF;
			if (i == j) cost[i][j] = 0;
		}
	}
	pair<int,pair<int,int>> e[n * (n - 1) / 2];
	bool used[n*(n-1)/2];
	int po = 0;
	REP (i,n) {
		REP (j,n) if (i < j) {e[po].F = A[i][j];e[po].S = {i,j};po++;}
	}
	sort(e,e+n*(n-1)/2);
	int ans = e[0].F;
	cost[e[0].S.F][e[0].S.S] = e[0].F;
	cost[e[0].S.S][e[0].S.F] = e[0].F;
	//i -> j
	REP (i,n*(n-1)/2) {
		used[i]=false;
		int co = e[i].F;
		int from = e[i].S.F;
		int to = e[i].S.S;
		if (co > cost[from][to]) {cout << -1 << endl;return 0;}
		REP (j,n) {//j -> from -> to
			if (cost[j][to] > cost[j][from] + co) {
				if (!used[i]) {ans += co;used[i]=true;}
				cost[j][to] = cost[j][from] + co;
				cost[to][j] = cost[j][to];
			}
			if (cost[j][from] > cost[j][to] + co) {
				if (!used[i]) {ans += co;used[i]=true;}
				cost[j][from] = cost[j][to] + co;
				cost[from][j] = cost[j][from];
			}
		}
	}
	cout << ans << endl;
}

