int n;
int a[N][N];

vector < pair <int, int> > g[N];

ll d[N];
int timer;
int was[N];

struct edge {
  int v, u, cost;
  edge(int v, int u, int cost) : v(v), u(u), cost(cost) {}
  bool operator < (const edge &x) {
    return cost < x.cost;
  }
};

bool bad[N][N];

void go(int st) {
  rep(i, 1, n) d[i] = linf;
  d[st] = 0;
  ++timer;
  rep(i, 1, n) {
    int v = -1;
    rep(j, 1, n) {
      if (was[j] != timer) {
        if (v == -1) v = j;
        else if (d[j] < d[v]) v = j;
      }
    }
    if (v == -1 || d[v] == linf) break;
    was[v] = timer;
    for (auto to : g[v]) {
      if (!bad[v][to.f] && d[to.f] > d[v] + to.s) {
        d[to.f] = d[v] + to.s;
      }
    }
  }
}
bool check(int v, int u) {
  bad[v][u] = bad[u][v] = 1;
  rep(i, 1, n) {
    go(i);
    rep(j, 1, n) {
      if (d[j] != a[i][j]) {
        bad[v][u] = bad[u][v] = 0;
        return 0;
      }
    }
  }
  return 1;
}
void solve() {
  n = get_int();
  rep(i, 1, n) {
    rep(j, 1, n) {
      a[i][j] = get_int();
      if (i != j) g[i].pb({j, a[i][j]});
    }
  }
  rep(i, 1, n) {
    go(i);
    rep(j, 1, n)
      if (a[i][j] != d[j]) cout << -1, ioi
  }
  ll ans = 0;
  vector <edge> kr;
  rep(i, 1, n) {
    rep(j, 1, n)
      if (i < j) {
        kr.pb(edge(i, j, a[i][j]));
        ans += a[i][j];
      }
  }
  sort(all(kr));
  reverse(all(kr));
  for (auto it : kr)
    if (check(it.v, it.u)) {
      ans -= it.cost;
      if (clock() / (double)CLOCKS_PER_SEC > 1.9) break;
    }
  cout << ans;
}
