int n;
int A[N][N];
vector<pair<int, pair<int, int> > > dists;
vector<pair<int, int> > V[N];
long long dist[N];
bool vis[N];

void DFS(int w) {
    vis[w] = true;
    for (auto p : V[w]) {
        int u = p.first;
        int kr = p.second;
        if (!vis[u]) {
            dist[u] = dist[w] + kr;
            DFS(u);
        }
    }
}

long long calcDist(int a, int b) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
        vis[i] = false;
    }
    dist[a] = 0;
    DFS(a);
    return dist[b];
}

long long ans;
void addEdge(int a, int b, int dist) {
    V[a].push_back({b, dist});
    V[b].push_back({a, dist});
    ans += dist;
}

int main() {

    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            scanf("%d", &A[i][j]);
            dists.push_back({A[i][j], {i, j}});
        }
    }

    sort(dists.begin(), dists.end());
    for (auto p : dists) {
        int dist = p.first;
        int a = p.second.first;
        int b = p.second.second;
        long long d = calcDist(a, b);
