  REP(i,N){
    REP(j,N){
      cin >> A[i][j];
      if(A[i][j] == 0) A[i][j] = INF;
      G[i][j] = INF;
      if(i < j){
        es[ct++] = {i, j, A[i][j]};
      }
    }
  }
  sort(es, es + ct, compare);
  ll ans = 0;

  REP(i,ct){
    Edge e = es[i];
    if(not uni.Same(es[i].u, es[i].v) or G[e.u][e.v] > A[e.u][e.v]){
      uni.Unite(es[i].u, es[i].v);
      ans += es[i].cost;
      G[e.u][e.v] = G[e.v][e.u] = e.cost;
    }
    REP(k,N){
      REP(i,N){
        REP(j,N){
          G[i][j] = min(G[i][j], G[i][k] + G[k][j]);
        }
      }
    }
  }
  REP(i,N){
    REP(j,N){
      if(i == j) continue;
      if(G[i][j] != A[i][j]){
        cout << -1 << endl;
        return 0;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

