template <int NMAX>
class Kruskal {
public:
  struct Edge {
    int v;
    int u;
    ll cost;
  };

private:

  int N;
  vector<Edge> edges;
  UnionFind<NMAX> uf;

  void sortEdges() {
    sort(begin(edges), end(edges),
         [](const Edge& lhs, const Edge& rhs) {
           return lhs.cost < rhs.cost;
	 });
  }

public:

  Dijkstra<NMAX> dijkstra;

  explicit Kruskal(int _N)
    : N(_N), dijkstra(_N) {
  }

  void addEdge(int v, int u, ll cost) {
    edges.emplace_back(Edge{v, u, cost});
  }


  ll spanningTree() {
    ll ret = 0;

    sortEdges();
    uf.init(N);

    for (auto& e : edges) {
      // check
      if (uf.same(e.u, e.v)) {
        // e.u to e.v
	dijkstra.run(e.u);
	if (e.cost == dijkstra.d[e.v]) {
          continue;
	} else if (e.cost > dijkstra.d[e.v]) {
          return -1;
	}
	// fall through
      }

      uf.unite(e.u, e.v);
      ret += e.cost;

      //used.push_back(e);
      dijkstra.add_edge(e.v, e.u, e.cost);
      dijkstra.add_edge(e.u, e.v, e.cost);
    }

    return ret;
  }

};

