    }
    bool f=true;
    for(int h=1;h<= n;h++) {
        for(int i=1;i<=n;i++) {
            for(int j=1;j<=n;j++) {
                if(dis[i][h]+dis[h][j]<dis[i][j]) {
                    f = false;
                }
            }
        }
    }
    if(!f) {
        puts("-1");
        return 0;
    }
    LL ans=0;
