const ll MAX = 101010;
ll par[MAX];
ll rnk[MAX];

void init(ll n) {
	for (ll i = 0; i < n; i++) {
		par[i] = i;
		rnk[i] = 0;
	}
}

ll find(ll x) {
	if (par[x] == x)
		return x;
	else
		return par[x] = find(par[x]);
}

void unite(ll x, ll y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;

	if (rnk[x] < rnk[y])
		par[x] = y;
	else {
		par[y] = x;
		if (rnk[x] == rnk[y])
			rnk[x]++;
	}
}

bool same(ll x, ll y) {
	return find(x) == find(y);
}

struct edge {
	ll u, v, cost;
	edge() {}
	edge(ll u, ll v, ll cost) : u(u), v(v), cost(cost) {}
};
ostream& operator<<(ostream& os, const edge& e) {
	os << "{" << e.u << ", " << e.v << ", " << e.cost << "}";
	return os;
}


bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}

ll kruskal(vector<edge> es, ll V) {
	ll E = es.size();
	sort(all(es), comp);
	init(V);
	ll res = 0;
	for (ll i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}


int V;
vector<vector<ll>> G;
vector<vector<ll>> d;

void warshall_floyd() {
	for (int k = 0; k < V; k++)
		for (int i = 0; i < V; i++)
			for (int j = 0; j < V; j++)
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> V;
	G.resize(V, vector<ll>(V));
	cin >> G;
	d = G;

	warshall_floyd();

	for (int i = 0; i < V; i++) {
		for (int j = 0; j < V; j++) {
			if (G[i][j] != d[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	ll ans = 0;
	// 辺 (i, j) を残すかどうか
	for (int i = 0; i < V - 1; i++) {
		for (int j = i + 1; j < V; j++) {
			ll cost = d[i][j];
			// k を経由した経路で cost と等しいものが存在するなら辺 (i, j) は必要ない
			bool equal = false;
			for (int k = 0; k < V; k++) {
				if (k == i || k == j)
					continue;
				if (cost == d[i][k] + d[k][j]) {
					equal = true;
					break;
				}
			}
			if (!equal)
				ans += cost;
		}
	}

	cout << ans << endl;

	return 0;
}

