		cout << "-1\n";
		return 0;
	}
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			if (flag[i][j]) {
				M += edge[i][j];
			}
		}
	}
	cout << M << endl;
	return 0;
}

