  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (a[i][j] != dist[i][j]) flag = false;
    }
  }

  ll ans = 0;
  if (flag) {
    for (int i = 0; i < N; i++) {
      for (int j = i + 1; j < N; j++) {
        ans += a[i][j];
      }
    }
    // 必要ない辺を除いていく
    for (int i = 0; i < N; i++) { // 始点
      for (int j = i + 1; j < N; j++) { // 終点
        for (int k = 0; k < N; k++) { // 中継点
          if (i == k || j == k) continue;
          if (a[i][j] == a[i][k] + a[k][j]) ans -= a[i][j];
        }
      }
    }
  }

  // 解答
  cout << (flag ? ans : -1) << endl;

  return 0;
}

