const int MAX_V=300+1;
LL A[MAX_V][MAX_V];
int V;
// 18:00-18:45 pause
// 20:40-
const LL Inf=1e17;

vector<pair<LL,int>> G[MAX_V];
LL D[MAX_V];
LL dist(int s, int d) {
  REPE(i,V) D[i]=Inf;
  set<pair<LL,int>> Q;
  D[s]=0; Q.emplace(0,s);
  while(SZ(Q)) {
    LL d; int u;
    auto it=Q.begin();
    tie(d,u)=*it; Q.erase(it);
    FORR(p,G[u]) {
      LL w=p.first; int v=p.second;
      LL d2=d+w;
      if(d2<D[v]) {
        auto it2=Q.find({D[v],v});
        if(it2!=Q.end()) Q.erase(it2);
        Q.emplace(d2,v);
        D[v]=d2;
      }
    }
  }
  return D[d];
}

LL solve(set<tuple<LL,int,int>> S) {
  LL res=0;
  FORR(t,S) {
    LL w; int u,v;
    tie(w,u,v)=t;
    LL d=dist(u,v);
    if(d<w) return -1;
    if(d==w) continue;

    G[u].emplace_back(w,v);
    G[v].emplace_back(w,u);
    res+=w;
  }
  return res;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  cin>>V;
  set<tuple<LL,int,int>> S;
  REP(i,V)REP(j,V) cin>>A[i][j];

  REP(j,V)REP(i,j) {
    LL d=A[i][j];
    S.emplace(d,i,j);
  }
  cout<<solve(S)<<endl;

  return 0;
}

