using namespace std;

int64_t distance(vector<vector<int64_t>> const &mat, vector<vector<int64_t>> const &minmat, int64_t a, int64_t b)
{
    priority_queue<pair<int64_t, int64_t>, vector<pair<int64_t, int64_t>>, std::greater<pair<int64_t, int64_t>>> q;
    vector<int64_t> mindist;
    mindist.resize(mat.size(), numeric_limits<int64_t>::max());

    q.push({0, a});
    while (!q.empty())
    {
        auto t = q.top();
        q.pop();
        if (t.second == b)
            continue;
        for (int64_t i = 0; i < mat.size(); i++)
        {
            if (mat[t.second][i] != -1 && mat[t.second][i] + t.first < mindist[i])
            {
                if (minmat[i][b] != numeric_limits<int64_t>::max())
                {
                    mindist[b] = min(mindist[b], minmat[i][b] + mat[t.second][i] + t.first);
                    continue;
                }
                mindist[i] = mat[t.second][i] + t.first;
                q.push({mindist[i], i});
            }
        }
    }

    return mindist[b];
}

int main()
{
    int64_t n;
    cin >> n;
    vector<vector<int64_t>> mat(n);
    vector<vector<int64_t>> minmat(n);

    vector<vector<bool>> kakutei(n);
    for (auto &row : kakutei)
        row.resize(n, false);

    for (auto &x : mat)
        x.resize(n, -1);
    for (auto &x : minmat)
        x.resize(n, std::numeric_limits<int64_t>::max());

    using dist_t = pair<int64_t, pair<int64_t, int64_t>>;
    priority_queue<dist_t, vector<dist_t>, std::greater<dist_t>> dist;
    for (int64_t i = 0; i < n; i++)
    {
        for (int64_t j = 0; j < n; j++)
        {
            int64_t temp;
            cin >> temp;
            if (j < i)
                dist.push({temp, {i, j}});
        }
    }

    int64_t ans = 0;
    while (!dist.empty())
    {
        auto t = dist.top();
        dist.pop();
        auto dis_ab = distance(mat, minmat, t.second.first, t.second.second);
        if (dis_ab == std::numeric_limits<int64_t>::max() || dis_ab > t.first)
        {
            mat[t.second.first][t.second.second] = mat[t.second.second][t.second.first] = t.first;
            minmat[t.second.first][t.second.second] = minmat[t.second.second][t.second.first] = t.first;
            ans += t.first;
        }
        else
        {
            if (dis_ab < t.first)
            {
                ans = -1;
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

