		v32 d;
		v32 pp;
		dijkstra(i,d,pp);
		int dist = d[j];
		// O(n^3logn)

		if(dist == a[i][j]) continue;
		if(dist < a[i][j]){
			p = 0;
			break;
		}
		if(dist == INF){
			adj[i].pb(mp(j,a[i][j]));
			adj[j].pb(mp(i,a[i][j]));
			ans += a[i][j];
		}
		else{
			adj[i].pb(mp(j,a[i][j]));
			adj[j].pb(mp(i,a[i][j]));
			ans += a[i][j];
		}
	}

	if(!p){
		cout<<"-1"<<ln;
	}
	else{
		cout<<ans<<ln;
	}

	return 0;
}

