  vector<M> edges(n);
  REP(i,n)FOR(j,i+1,n){edges[i][j]=a[i][j];edges[j][i]=a[i][j];}
  ll sum=0;
  REP(i,n)FOR(j,i+1,n){
    vector<M> edge = edges;
    edge[i].erase(j);
    edge[j].erase(i);
