priority_queue<pair<ll,int> > Q;

void bfs(int s) {
	ms(vis,false);
	ms(D,-1);
	D[s] = 0;
	Q.push({0,s});
	while(!Q.empty()) {
		int v =  Q.top().s;
		Q.pop();
		if(vis[v]) continue;
		vis[v] = true;
		FOR(u,0,N) if(G[v][u] != 0) {
			if(D[u] == -1 || D[v] + G[v][u] < D[u]) {
				D[u] = D[v] + G[v][u];
				Q.push({-D[u],u});
			} 
		}
	}
}

