	for(int i=1;i<=n;i++) 
	for(int j=1;j<=n;j++) {
		scanf("%d",&a[i][j]);
		b[i][j]=a[i][j];
	}
	solve();
	if(!able) cout << "-1\n" ;
	else cout<< res << "\n";
	return 0;
}

