	  if(dist[u]+w[idx]<dist[v1])
	    {
	      dist[v1]=dist[u]+w[idx];
	      pq.push(mp(-dist[v1],v1));
	    }
	}
    }
  rep(i,1,n+1) d[src][i]=dist[i];
}
