		ll u = cur_edge.second.first;
		ll v = cur_edge.second.second;
		ll w = cur_edge.first;
		if(dist[u][v] < w){
			cout << "-1\n";
			return 0;
		}
		if(dist[u][v] == w)continue;
		dist[u][v] = dist[v][u] = w;
		for(int i=0;i<n;i++){
			dist[v][i] = dist[i][v] = min(dist[i][v] , dist[i][u] + w);
			dist[u][i] = dist[i][u] = min(dist[i][u] , dist[i][v] + w);
		}
		// cout << u << ' ' << v << ' ' << w << endl;
		ans += w;
	}
	cout << ans << endl;
}

