class UnionFind {
private:
    vector<int> union_size, rank;

public:
    vector<int> par;
    UnionFind(int n) : union_size(vector<int>(n)), rank(vector<int>(n)), par(vector<int>(n)) { init(n); }

    void init(int n)
    {
        for (int i=0; i<n; i++) {
            par[i] = i;
            rank[i] = 0;
            union_size[i] = 1;
        }
    }

    // 木の根を求める
    int find(int x)
    {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合する
    void merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y) return;

        union_size[x] += union_size[y];
        union_size[y] = union_size[x];

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じ集合に属するか判定する
    bool is_same(int x, int y) { return find(x) == find(y); }
    // x が含まれる集合の要素数を返す
    int get_union_size(int x) { return union_size[find(x)]; }
};

int main()
{
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<vector<int>> A(N, vector<int>(N));
    typedef pair<int, PII> P;
    priority_queue<P, vector<P>, greater<P>> Q;

    rep(i, N) rep(j, N) {
        cin >> A[i][j];
        if (i < j) {
            Q.emplace(A[i][j], PII(i, j));
        }
    }

    UnionFind uf(N);
    vector<vector<ll>> cost(N, vector<ll>(N, INFLL));
    ll ans = 0, additional = 0;

    int min_cost = Q.top().first;

    while (Q.size()) {
        P p = Q.top(); Q.pop();
        int u = p.second.first, v = p.second.second;
        if (!uf.is_same(u, v) || p.first <= 2*min_cost) {
            uf.merge(u, v);
            cost[u][v] = cost[v][u] = p.first;
            ans += p.first;
#ifdef DEBUG
            cerr << "add_edge: (" << u << ", " << v << "), " << p.first << endl;
#endif
        }
    }

    rep(k, N) rep(i, N) rep(j, N) {
        cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j]);
    }

    for (int i=0; i<N; i++) {
        for (int j=i+1; j<N; j++) {
            if (A[i][j] > cost[i][j]) {
                cout << -1 << endl;
                return 0;
            } else {
                ans += A[i][j] - cost[i][j];
            }
        }
    }
    cout << ans << endl;
}

