int main(void){
    cin>>n;
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            cin>>A[i][j];
            if(i<j){
                q.push(Q(A[i][j], P(i, j)));
                p.push(Q(A[i][j], P(i, j)));
            }
        }
    }
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            d[i][j]=1e18;
        }
        d[i][i]=0;
    }
    int z=0;
    s.insert(0);
    while(s.size()<n&&!q.empty()&&z<1e8){
        bool f=true;
        vector<Q> v;
        while(f&&z<1e8){
            z++;
            Q e=q.top();
            q.pop();
            int a=e.second.first, b=e.second.second;
            if(s.find(a)==s.end()){
                if(s.find(b)==s.end()){
                    v.push_back(e);
                }else{
                    s.insert(a);
                    ans+=e.first;
                    f=false;
                    d[a][b]=d[b][a]=e.first;
                }
            }else if(s.find(b)==s.end()){
                s.insert(b);
                ans+=e.first;
                f=false;
                d[a][b]=d[b][a]=e.first;
            }
        }
        for(int i=0;i<v.size();i++){
            q.push(v[i]);
        }

    }
    for(int k=0;k<n;k++){
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++){
                d[i][j]=min(d[i][j], d[i][k]+d[k][j]);
            }
        }
    }

    while(!p.empty()){
        Q e=p.top();
        p.pop();
        int a=e.second.first, b=e.second.second;
        if(d[a][b]>A[a][b]){
            d[a][b]=A[a][b];
            ans+=A[a][b];
            for(int k=0;k<n;k++){
                for(int i=0;i<n;i++){
                    for(int j=0;j<n;j++){
                        d[i][j]=min(d[i][j], d[i][k]+d[k][j]);
                    }
                }
            }
        }else if(d[a][b]<A[a][b]){
            cout<<-1<<endl;
            return 0;
        }
    }

    cout<<ans<<endl;
    return 0;
}

