using namespace std;
typedef long long ll;
const int MAXN = 305;
struct { int v, next; ll w; } e[MAXN * MAXN];
int head[MAXN], cnt_edge;
inline void add_edge(int u, int v, ll w) {
    e[cnt_edge] = { v, head[u], w };
    head[u] = cnt_edge++;
}
int n;
struct Item {
    ll val;
    int u, v;
    bool operator > (const Item &item) const {
        return val > item.val;
    }
};
ll dis[MAXN];
bool inque[MAXN];
void spfa(int s) {
    queue<int> que;
    dis[s] = 0;
    inque[s] = true;
    que.push(s);
    while(!que.empty()) {
        int u = que.front(); que.pop();
        inque[u] = false;
        for(int i = head[u]; i != -1; i = e[i].next) {
            if(dis[e[i].v] > dis[u] + e[i].w) {
                dis[e[i].v] = dis[u] + e[i].w;
                if(!inque[e[i].v]) {
                    inque[e[i].v] = true;
                    que.push(e[i].v);
                }
            }
        }
    }
}
priority_queue<Item, vector<Item>, greater<Item>> que;
int main() {
    memset(head, 0xff, sizeof(head));
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) {
        ll val; scanf("%lld", &val);
        if(i < j) {
            que.push((Item){val, i, j});
        }
    }
    ll ans = 0;
    while(!que.empty()) {
        Item item = que.top(); que.pop();
        memset(dis, 0x3f, sizeof(dis));
        spfa(item.u);
        if(dis[item.v] < item.val) {
            printf("-1\n");
            return 0;
        }
        else if(dis[item.v] > item.val) {
            add_edge(item.u, item.v, item.val);
            add_edge(item.v, item.u, item.val);
            ans += item.val;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

