void ins(int x,int y,LL d)
{
  len++; edge[len].x=x; edge[len].y=y; edge[len].d=d; edge[len].next=first[x]; first[x]=len;
}
struct P
{
  int x,y; LL d;
  P(){}
  P(int _x,int _y,LL _d){x=_x; y=_y; d=_d;}
  friend bool operator <(P x,P y){return x.d>y.d;} 
};
priority_queue<pair<LL,int> >Q; LL D[Maxn][Maxn]; bool V[Maxn]; int N; LL A[Maxn][Maxn];
priority_queue<P> Q1;
void SPFA(int p)
{
  int ST=p; for(int i=1;i<=N;i++) V[p]=1,D[p][i]=0x3f3f3f3f3f3f3f3f; D[p][p]=0;
  while(!Q.empty()) Q.pop(); Q.push(make_pair(0,p));
  while(!Q.empty())
  {
    pair<LL,int> x=Q.top(); Q.pop();
    if(x.first>D[p][x.second]) continue;
    for(int k=first[x.second];k!=-1;k=edge[k].next)
    {
      int y=edge[k].y;
      if(D[p][y]>D[p][x.second]+edge[k].d)
      {
        D[p][y]=D[p][x.second]+edge[k].d;
        Q.push(make_pair(D[p][y],y));
      }
    }
  }
}
