typedef long long ll;
const int N = 300;
int n;
int v[N][N];
ll cost[N];
vector<int> p[N];
ll e[N][N];
void Dijkstra(int u) {
	for (int i = 0; i < n; ++i) {
		cost[i] = 1e18;
		p[i].clear();
	}
	cost[u] = 0;
	for (int i = 0; i<n; ++i) {
		int u = -1;
		ll mn = 1e18;
		for(int i=0;i<n;++i)
			if (cost[i] < mn && cost[i] != -1) {
				mn = cost[i];
				u = i;
			}
		for (int v = 0; v<n; ++v) {
			if (!e[u][v] || cost[v] == -1)
				continue;
			if(cost[v]>cost[u]+e[u][v]){
				cost[v] = cost[u] + e[u][v];
				p[v].clear();
				p[v].push_back(u);
			}else if (cost[v] == cost[u] + e[u][v])
				p[v].push_back(u);
		}
		cost[u] = -1;
	}
	for (int i = 0; i < n; ++i)
		if (p[i].size() > 1 && e[i][u])
			e[i][u] = e[u][i] = 0;
}
int main()
{
	scanf("%d", &n);
	for(int i=0;i<n;++i)
		for (int j = 0; j < n; ++j) {
			scanf("%d", &v[i][j]);
			e[i][j] = v[i][j];
		}
	for (int i = 0; i < n; ++i)
		Dijkstra(i);
	ll res = 0;
	for (int i = 0; i < n; ++i)
		for (int j = i + 1; j < n; ++j) {
			res += e[i][j];
		}
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j)
			if (!e[i][j] && i != j)
				e[i][j] = 1e18;
	for (int k = 0; k < n; ++k)
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				e[i][j] = min(e[i][j], e[i][k] + e[k][j]);
	for(int i=0;i<n;++i)
		for(int j=0;j<n;++j)
			if (e[i][j] != v[i][j]) {
				res = -1;
				i = j = n;
			}
	cout << res << endl;
	return 0;
}

