using namespace std;
typedef long long LL;
typedef pair<int, int> pii;
typedef pair<LL, int> pli;
const int MAXN = 345;
LL dis[MAXN];
bool visit[MAXN];
vector<pii> G[MAXN];
struct node{
       int x, y;
       LL cost;
       node (int a, int b, LL c) : x(a), y(b), cost(c) {}
       bool operator < (const node &a) const {
            return cost < a.cost;
       }
};

int check(int x, int y, LL cost) {
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    pq.push(make_pair(0, x));
    memset(visit, 0, sizeof(visit));
    while (!pq.empty()) {
          auto tp = pq.top();
          pq.pop();
          int cur = tp.second;
          LL cost = tp.first;
          if (visit[cur]) continue;
          dis[cur] = cost;
          visit[cur] = 1;
          for (auto &i : G[cur]) {
              pq.push(make_pair(cost + i.first, i.second));
          }
    }
    if (visit[y] && dis[y] < cost) return 0;
    else if (!visit[y] || dis[y] > cost) {
         G[x].push_back(make_pair(cost, y));
         G[y].push_back(make_pair(cost, x));
         return 2;
    }
    return 1;
}

int main() {
    int N;
    scanf("%d", &N);
    vector<node> cand;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            LL tmp;
            scanf("%lld", &tmp);
            if (i >= j) continue;
            cand.push_back(node(i, j, tmp));
        }
    }
    sort(cand.begin(), cand.end());
    bool OK = true;
    LL sum = 0;
    for (auto i : cand) {
        int chk = check(i.x, i.y, i.cost);
        if (!chk) OK = false;
        else if (chk == 2) sum += i.cost;
    }
    if (!OK) sum = -1;
    printf("%lld\n", sum);
    return 0;
}

