ll d[305][305];

int main() {
    int n;
    scanf("%d", &n);
    vector <road> v;
    for (int i = 1; i <= n; i ++)
        for (int j = 1; j <= n; j ++) {
            scanf("%d", &a[i][j]);
            if (i < j)
                v.push_back((road) {i, j, a[i][j]});
        }
    memset(d, 0x3f, sizeof d);
    for (int i = 1; i <= n; i ++)
        d[i][i] = 0;
    sort(v.begin(), v.end());
    ll res = 0;
    for (auto & r : v) {
        if (d[r.u][r.v] < r.len) continue;
        if (d[r.u][r.v] > r.len) res += r.len;
