ll cnt = 1;
inline void addedge(ll f, ll t, ll v){
	edge[++cnt].next = head[f];
	edge[cnt].f = f;
	edge[cnt].t = t;
	edge[cnt].dis = v;
	head[f] = cnt;
}
ll cost = 0;
inline void adde(ll f, ll t, ll v){
	addedge(f, t, v);
	addedge(t, f, v);
	cost += v;
}

struct Nod{
	ll pos, dis;
	inline bool operator < (const Nod &mr) const {return dis > mr.dis;}
};

ll dis[maxn];
inline ll dijkstra(ll S, ll T){
	priority_queue <Nod> q;
	for (ll i = 1; i <= n; i++) dis[i] = INF;
	dis[S] = 0;
	q.push((Nod){S, dis[S]});
	while (!q.empty()){
		Nod cur = q.top(); q.pop();
		if (cur.pos == T) return cur.dis;
		if (cur.dis > dis[cur.pos]) continue;
		for (ll i = head[cur.pos]; i; i = edge[i].next){
			if (dis[edge[i].t] > cur.dis + edge[i].dis)
				q.push((Nod){edge[i].t, dis[edge[i].t] = cur.dis + edge[i].dis});
		}
	}
	return INF;
}
