    smaller_queue<pair<ll, pll> > que;
    rep(i, n) REP(j, i + 1, n) que.push(MP(a[i][j], MP(i, j)));
    ll ans = 0;
    ll d[n][n];
    rep(i, n) rep(j, n) d[i][j] = (i == j ? 0 : LINF);
    UnionFind uf(301);
    bool valid = true;
    while (!que.empty()) {
        ll now_dist = que.top().first;
        pll p = que.top().second;
        ll x = p.first, y = p.second;
        if (!uf.same(x, y) || now_dist < d[x][y]) {
            ans += now_dist;
            d[x][y] = now_dist;
            d[y][x] = now_dist;
            uf.unite(x, y);

            rep(i, n) {
                if (uf.same(x, i)) {
                    d[y][i] = min(d[y][i], d[x][i] + now_dist);
                    d[i][y] = d[y][i];
                    d[x][i] = min(d[x][i], d[y][i] + now_dist);
                    d[i][x] = d[x][i];
                }
            }
        } else if (now_dist > d[x][y]) {
            valid = false;
        }
        que.pop();
    }

    rep(i, n) rep(j, n) if (a[i][j] != d[i][j]) valid = false;
    cout << (valid ? ans : -1) << endl;
    return 0;
}

