struct P{
  ll d,to1,to2;
};

int main(){
  ll N,oo=1e10; cin>>N;
  vector<vector<ll>> A(N+10, vector<ll>(N+10,0)),B(N+10,vector<ll>(N+10,oo));
  vector<P> Z(0,{0,0,0});
  for(ll i=0; i<N; i++) for(ll j=0; j<N; j++) cin>>A[i][j];
  for(ll i=0; i<N; i++) B[i][i]=0;
  for(ll i=0; i<N; i++) for(ll j=i+1; j<N; j++) Z.push_back({A[i][j],i,j});
  sort(Z.begin(), Z.end(), [](auto& x, auto& y){return x.d < y.d;});  
  UnionFind tree(N);
  ll cnt=0,i=-1,ans=0,zsz=Z.size();
  while(cnt<N-1 && ++i<zsz){
    P v=Z[i];
    if(tree.issame(v.to1,v.to2)) continue;
    cnt++;
    ans+=v.d;
    tree.unite(v.to1,v.to2);
    //Bに最短直通だけコピー
    B[v.to1][v.to2]=v.d;
    B[v.to2][v.to1]=v.d;
  }
  for(ll k=0; k<N; k++){
    for(ll i=0; i<N; i++){
      for(ll j=0; j<N; j++){
        B[i][j]=min(B[i][j],B[i][k]+B[k][j]);
      }
    }
  }
  for(ll i=0; i<N; i++){
    for(ll j=0; j<N; j++){
      if(A[i][j]!=B[i][j]){
        cout<<-1<<endl;
        return 0;
      }
    }
  }
  cout<<ans<<endl;
}

