using namespace std;
using ll=long long;
using vll=vector<ll>;
using vvll=vector<vll>;

const long long inf=1000000000*300LL;


struct qm_t
{
	int p;
	ll d;
	bool operator<(const qm_t&rhs) const
	{
		return d>rhs.d;
	}
};


class q_t
{
	priority_queue<qm_t> q;
public:
	void push(int p, ll d)
	{
		q.push((qm_t){p, d});
	}
	bool pop(int&p, ll&d)
	{
		if(q.empty()) return false;
		p=q.top().p;
		d=q.top().d;
		q.pop();
		return true;
	}
};


bool min_u(ll&m, ll v)
{
	if(m>v)
	{
		m=v;
		return true;
	}
	return false;
}


ll calc(vvll&a, int s, int e)
{
	int n=a.size();
	vll dp(n, inf);
	int p=s;
	ll d=0;
	q_t q;

	dp[p]=d;
	q.push(p, d);
	while(q.pop(p, d))
	{
		if(p==e) return d;

		for(int i=0;i<n;i++)
		{
			if(min_u(dp[i], dp[p]+a[p][i]))
			{
				q.push(i, dp[i]);
			}
		}
	}
/*
	printf("s=%d e=%d d=%lld : ", s, e, d);
	for(auto dpe:dp) printf("%lld ", dpe); printf("\n");
*/
	return inf;
}


struct x_t
{
	int s, e;
	ll d;
	bool operator<(const x_t&rhs) const
	{
		if(d!=rhs.d) return d>rhs.d;
		if(s!=rhs.s) return s>rhs.s;
		return e>rhs.e;
	}
};


ll solve(vvll&a)
{
	int n=a.size();
	ll ret=0;
	set<x_t> s;

	for(int i=0;i<n;i++)
	{
		for(int j=0;j<i;j++)
		{
			s.insert((x_t){i, j, a[i][j]});
		}
	}
	for(auto it=s.begin();it!=s.end();++it)
	{
		ll d=it->d;
		int i=it->s;
		int j=it->e;
		a[i][j]=a[j][i]=inf;
		ll d2=calc(a, i, j);
//printf("i=%d j=%d d=%lld d2=%lld\n", i, j, d, d2);
		if(d2<d)
		{
//			printf("ERROR : i=%d j=%d d=%lld d2=%lld\n", i, j, d, d2);
			return -1;
		}
		if(d2>d)
		{
			a[i][j]=a[j][i]=d;
			ret+=a[i][j];
		}
	}
	return ret;
}


int main(void)
{
	int n;

	while(scanf("%d", &n)==1)
	{
		vvll a(n);

		for(int i=0;i<n;i++)
		{
			a[i].resize(n);
			for(int j=0;j<n;j++)
			{
				scanf("%lld", &a[i][j]);
			}
		}
		printf("%lld\n", solve(a));
/*
