int main(){
	int n;
	int numComplete=0;
	long long ans=0;
	std::vector<road> roadList;
	std::vector<std::vector<bool>> isMinimum;
	std::vector<std::vector<long long>> aList;
	std::vector<std::vector<long long>> minDist;

	std::cin>>n;

	aList.resize(n);
	for(int i=0; i<n; i++)
		aList[i].resize(n);

	for(int i=0; i<n; i++)
		for(int j=0; j<n; j++)
			std::cin>>aList[j][i];

	for(int i=0; i<n; i++)
		for(int j=i+1; j<n; j++)
			roadList.push_back({i, j, aList[i][j]});

	std::stable_sort(roadList.begin(), roadList.end(), [](const road &x, const road &y){return x.dist< y.dist;});

	minDist.resize(n);
	for(int i=0; i<n; i++)
		minDist[i].resize(n, -1);

	isMinimum.resize(n);
	for(int i=0; i<n; i++)
		isMinimum[i].resize(n, false);

	for(int i=0; i<roadList.size(); i++){
		if(numComplete>= roadList.size())
			break;

		minDist[roadList[i].src][roadList[i].dst]= roadList[i].dist;
		if(!isMinimum[roadList[i].src][roadList[i].dst]){
			isMinimum[roadList[i].src][roadList[i].dst]=true;
			numComplete++;
		}
		ans+= roadList[i].dist;

		for(int j=0; j<n; j++){
			long long prevDist;
			prevDist= minDist[std::min(roadList[i].src, j)][std::max(roadList[i].src, j)];

			if(prevDist>= 0){
				int tmpSrc= std::min(roadList[i].dst, j);
				int tmpDst= std::max(roadList[i].dst, j);

				if(prevDist + roadList[i].dist < aList[tmpSrc][tmpDst]){
					std::cout<<-1<<std::endl;
					return 0;
				}

				if(prevDist + roadList[i].dist == aList[tmpSrc][tmpDst]
					&& !isMinimum[tmpSrc][tmpDst]){
					isMinimum[tmpSrc][tmpDst]=true;
					numComplete++;
				}

				minDist[tmpSrc][tmpDst]= std::min(prevDist + roadList[i].dist, minDist[tmpSrc][tmpDst]);

			}

			prevDist= minDist[std::min(roadList[i].dst, j)][std::max(roadList[i].dst, j)];

			if(prevDist>= 0){
				int tmpSrc= std::min(roadList[i].src, j);
				int tmpDst= std::max(roadList[i].src, j);

				if(prevDist + roadList[i].dist < aList[tmpSrc][tmpDst]){
					std::cout<<-1<<std::endl;
					return 0;
				}

				if(prevDist + roadList[i].dist == aList[tmpSrc][tmpDst]
					&& !isMinimum[tmpSrc][tmpDst]){
					isMinimum[tmpSrc][tmpDst]=true;
					numComplete++;
				}

				minDist[tmpSrc][tmpDst]= std::min(prevDist + roadList[i].dist, minDist[tmpSrc][tmpDst]);
			}
		}
	}

	std::cout<<ans<<std::endl;

	return 0;
}

