long long look_up(int i, int j) {

    for (int k = 1; k <= n; ++k) {
        if (dist[i][k] + dist[k][j] == dist[i][j] && i != k && j != k) {
            return look_up(i, k) - dist[k][j];
        }
    }

    return dist[i][j];
}

