int dijkstra(std::vector<std::unordered_map<int, ll>>& edges, int start, int goal)
{
    if (start == goal) return 0;
    std::vector<ll> next_nodes(edges.size(), LLONG_MAX);
    std::vector<char> finished(edges.size(), false);
    next_nodes[0] = start;
    finished[start] = true;

    while (true){
        int next_node = (std::min_element(next_nodes.begin(), next_nodes.end()) - next_nodes.begin());
        const ll temp_cost = next_nodes[next_node];
        // printf("%d %lld\n", next_node, temp_cost);
        if (temp_cost == LLONG_MAX) break;
        if (next_node == goal) return temp_cost;
        finished[next_node] = true;
        for (auto& node : edges[next_node]){
            if (finished[node.first]) continue;
            const ll next_cost = temp_cost + node.second;
            if (next_cost < next_nodes[node.first]) next_nodes[node.first] = next_cost;
        }
        next_nodes[next_node] = LLONG_MAX;
    }
    return -1;
}

