		cin >> A[i][j];
		B[i][j] = A[i][j];
		v.emplace_back(A[i][j], pii(i,j) );
	}

	sort(all(v));

	rep(k,N) rep(i,N) rep(j,N){
		chmin(B[i][j], B[i][k] + B[k][j]);
	}
	bool f=true;
	rep(i,N) rep(j,N){
		if( A[i][j] != B[i][j] ) f = false;
	}
	if(!f){
		cout << -1 << endl;
		return 0;
	}

	ll C[305][305];
	Fill(C, INF);
	rep(i,305) C[i][i] = 0;
	UnionFind uf(305);
	for(auto p: v){
		int len = p.X;
		int i = p.Y.X;
