struct info {
	int n1, n2, co;
	bool operator<(const info &i)const {
		if (co != i.co)return co < i.co;
		if (n1 != i.n1)return n1 < i.n1;
		return n2 < i.n2;
	}
};
int root(int p) {
	if (par[p] == p)return par[p];
	return par[p] = root(par[p]);
}
void uni(int a, int b) {
	a = root(a), b = root(b);
	par[a] = b;
}
bool sameuni(int a, int b) {
	a = root(a); b = root(b);
	return (a == b);
}
int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			scanf("%d", &a[i][j]);
			dp[i][j] = (ll)1e9 * (n + 1);
		}
	}
	vector<info> v;
	for (int i = 0; i < n; i++) {
		dp[i][i] = 0;
		par[i] = i;
		for (int j = i + 1; j < n; j++) {
			v.push_back({ i, j, a[i][j] });
		}
	}
	sort(v.begin(), v.end());
	for (int i = 0; i < v.size(); i++) {
		int p = v[i].n1, q = v[i].n2;
		if (sameuni(p, q)) {
			ll mn = (ll)1e9*(n + 1);
			for (int k = 0; k < n; k++) {
				if (!sameuni(p, k))continue;
				mn = min(mn, dp[p][k] + dp[k][q]);
