				puts("-1"); return 0;
			}
		}
		else {
			uni(p, q);
			dp[p][q] = dp[q][p] = v[i].co;
		}
	}
	ll ans = 0;
	for (int i = 0; i < n; i++) {
		for (int j = i + 1; j < n; j++) {
			if (dp[i][j] <= 1e9)ans += dp[i][j];
		}
	}
	cout << ans;
}

