vi v[N];
bool mark[N*N];
int finda(int x)
{
  if(p[x]==x) return x;
  return p[x]=finda(p[x]);
}
int n;
void dijkstra(int src)
{
  priority_queue<pair<ll,int> > pq;
  rep(i,1,n+1) dist[i]=inf;
  dist[src]=0;
  pq.push(mp(0,src));
  while(!pq.empty())
    {
      auto x1=pq.top();
      pq.pop();
      int u=x1.se; ll we=-x1.fi;
      if(we>dist[u]) continue;
      for(int idx:v[u])
	{
	  int v1=(x[idx]^y[idx]^u);
	  if(dist[u]+w[idx]<dist[v1])
	    {
	      dist[v1]=dist[u]+w[idx];
	      pq.push(mp(-dist[v1],v1));
	    }
	}
    }
  rep(i,1,n+1) d[src][i]=dist[i];
}
bool check()
{
  rep(i,1,n+1)
    rep(j,1,n+1) if(d[i][j]!=pre[i][j]) return true;
  return false;
}
bool check2()
{
  rep(i,1,n+1) rep(j,1,n+1) if(a[i][j]!=d[i][j]) return false;
  return true;
}
