  if(!ok)
    {
      cout<<-1<<endl;
      return 0;
    }
  int cnt=0;
  rep(i,1,n+1)
    {
      rep(j,i+1,n+1)
	{
	  x[++cnt]=i; y[cnt]=j;
	  w[cnt]=a[i][j];
	  ind[cnt]=cnt;
	}
    }
  sort(ind+1,ind+cnt+1,[](int i,int j){return w[i]<w[j];});
  ll ans=0;
  rep(i,1,n+1) p[i]=i;
  rep(i,1,cnt+1)
    {
      int x1=x[ind[i]],y1=y[ind[i]];
      x1=finda(x1),y1=finda(y1);
      if(x1==y1) continue;
      p[y1]=x1;
      ans+=w[ind[i]];
      mark[ind[i]]=true;
      v[x[ind[i]]].pb(ind[i]);
      v[y[ind[i]]].pb(ind[i]);
    }
  rep(i,1,n+1) dijkstra(i);
