const int MAXN = 305;
struct { int v, w, next; } e[MAXN * MAXN];
int head[MAXN], cnt_edge;
inline void add_edge(int u, int v, int w) {
    e[cnt_edge] = { v, w, head[u] };
    head[u] = cnt_edge++;
}
ll dis[MAXN][MAXN];
int n;
struct Item {
    ll val;
    int u, v;
    bool operator > (const Item &item) const {
        return val > item.val;
    }
};
priority_queue<Item, vector<Item>, greater<Item>> que;
queue<int> que_;
bool inque[MAXN];
void spfa(int s) {
    que_.push(s);
    inque[s] = true;
    while(!que_.empty()) {
        int u = que_.front(); que_.pop();
        inque[u] = false;
        for(int i = head[u]; i != -1; i = e[i].next) {
            if(dis[s][e[i].v] > dis[s][u] + e[i].w) {
                dis[s][e[i].v] = dis[s][u] + e[i].w;
                if(!inque[e[i].v]) {
                    que_.push(e[i].v);
                    inque[e[i].v] = true;
                }
            }
        }
    }
}
