    for(int j=0;j<n;j++) to[i][j] = from[i][j];
}

typedef pair<int,int> P;
typedef pair<int,P> PP;
vector<PP> edge;

int solve(){
  int tmp[N][N];cp(D,tmp);WF(tmp);
  if(!same(D,tmp)) return -1;

  for(int i=0;i<n;i++)
    for(int j=i+1;j<n;j++) edge.push_back(PP(D[i][j],P(i,j)));
  sort(edge.begin(),edge.end());

  int res = 0;

  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++) ans[i][j] = (i!=j)*INF;

  for(PP e:edge){
    int a = e.second.first;
    int b = e.second.second;
    int c = e.first;

    for(int i=0;i<n;i++) Min(ans[a][b], ans[a][i]+ans[i][b]);
    if(ans[a][b] < c) return -1;
    ans[a][b] = ans[b][a] = c;
    if(ans[a][b] != c) res += c;
    for(int i=0;i<n;i++) Min(ans[i][a],Min(ans[a][i] ,ans[a][b]+ans[b][i]));
    for(int i=0;i<n;i++) Min(ans[i][b],Min(ans[b][i] ,ans[b][a]+ans[a][i]));
  }

  WF(ans);
  if(!same(ans,D)) return -1;
  return res;
}

signed main(){
  cin>>n;
  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++)cin>>D[i][j];

  cout<<solve()<<endl;
  return 0;
}

