    rep(i, n) rep(j, n) {
        input(g[i][j]);
        memo.pb(mt(g[i][j], i, j));
    }
    sort(all(memo));
    vector<vector<P>> ret(n);
    priority_queue<tuple<ll, ll>, vector<tuple<ll, ll>>, greater<tuple<ll, ll>>> q;
    ll counter = 0;
    rep(_, memo.size()) {
        counter++; 
        ll cost, i, j; tie(cost, i, j) = memo[_];
        // iからjの最短経路を求めます
        q.push(mt(0, i));
        while (!q.empty()) {
            ll c, v; tie(c, v) = q.top(), q.pop();
            if(dist[i][v]<=c)continue;
            dist[i][v] = c;
            if (v == j) break;
            for (auto x : ret[v]) if (c + x.se < dist[i][x.fi]) {
                q.push(mt(c + x.se, x.fi));
            }
