        if (dist[i][j] < g[i][j]) {
            cout << -1 << endl;
            return 0;
        } else if (dist[i][j] == g[i][j]) {
        } else {
            ret[i].pb(P(j, g[i][j]));
            ret[j].pb(P(i, g[i][j]));
            q.push(mt(g[i][j], j));
        }
    }

    long long ans = 0;
    rep(i, n) for (auto x : ret[i]) {
        ans += x.se;
    }
    cout << ans / 2 << endl;
