class Data{

public:
	ll dist;
	int from, to;
	Data(ll dist, int from, int to) {
		this->dist = dist;
		this->from = from;
		this->to = to;
	}

	bool operator < (const Data &d) const{
		return dist < d.dist;
	}
	bool operator >(const Data &d) const{
		return dist > d.dist;
	}
};

int N;
ll D[300][300];

int main() {
	cin >> N;
	priority_queue<Data, vector<Data>, greater<Data>> pq;

	rep(i, N)
		rep(j, N){
			ll d; cin >> d;
			if(i < j) {
				pq.push(Data(d, i, j));
				D[i][j] = d;
				D[j][i] = d;
			}
		}

	ll ret = 0;
	while(!pq.empty()){
		Data d = pq.top(); pq.pop();
		int flg = 1;
		rep(i, N) if(i != d.from && i != d.to) {
			if(D[d.from][i] + D[i][d.to] == d.dist) flg = min(flg, 0);
			if(D[d.from][i] + D[i][d.to] < d.dist) flg = min(flg, -1);
		}
		if(flg == 1) ret += d.dist;
		if(flg == -1) {
			cout << -1 << endl;
			return 0;
		}
	}

	cout << ret << endl;
}

