#define maxn 300
const int mod = 1000000000 + 7;
const long long inf = 1ll * 1000000000 * 300;

int n, m, k;
int a[maxn][maxn], f[maxn];
vector<pair<int, pair<int,int>>> e;
long long w[maxn][maxn];

int get(int x){
    if(f[x]==x) return x;
    f[x] = get(f[x]);
    return f[x];
}

void solve(){
    cin >> n;
    e.clear();
    rep(i,n)rep(j,n){
        cin >> a[i][j];
        if(i < j) e.push_back(mp(a[i][j], mp(i,j)));
        w[i][j] = (i==j)? 0: inf;
    }
    rep(i,n) f[i] = i;

    long long ans = 0;

    sort(e.begin(), e.end());
    bool ok = 1;
    for(auto p: e){
        int u = p.second.first;
        int v = p.second.second;
        if(w[u][v] == p.first){
            continue;
        }
        if(w[u][v] > p.first){
            ans += p.first;
            w[u][v] = w[v][u] = p.first;
            rep(i,n)rep(j,n){
                w[i][j] = min(w[i][j], w[i][u] + w[u][v] + w[v][j]);
                w[i][j] = min(w[i][j], w[i][v] + w[v][u] + w[u][j]);
            }
        }
        if(w[u][v] < p.first){
            ok = 0;
        }
    }

//    rep(i,n)rep(j,n)rep(k,n){
//        w[i][j] = min(w[i][k] + w[k][j], w[i][j]);
//    }

    rep(i,n)rep(j,n){
        ok &= (w[i][j] == a[i][j]);
    }

    cout << (ok? ans: -1);

}

int main(int argc, const char * argv[]) {
    std::ios::sync_with_stdio(false);
    solve();
    return 0;
}

