typedef complex<double> base;
void fft(vector<base> & a, bool invert) {
	lo n = (lo)a.size();
	for (lo i = 1, j = 0; i<n; ++i) {
		lo bit = n >> 1;
		for (; j >= bit; bit >>= 1)j -= bit;
		j += bit;
		if (i < j) swap(a[i], a[j]);
	}
	for (lo len = 2; len <= n; len <<= 1) {
		double ang = 2 * PI / len * (invert ? -1 : 1);
		base wlen(cos(ang), sin(ang));
		for (lo i = 0; i<n; i += len) {
			base w(1);
			for (lo j = 0; j<len / 2; ++j) {
				base u = a[i + j], v = a[i + j + len / 2] * w;
				a[i + j] = u + v;
				a[i + j + len / 2] = u - v;
				w *= wlen;
			}
		}
	}
	if (invert)for (lo i = 0; i<n; ++i)a[i] /= n;
}

vl mult(vl a,vl  b) {
	//cout << a.size() << "%" << b.size() << endl;
	vector<base> fa(a.begin(), a.end()), fb(b.begin(), b.end());
	size_t n = 1;
	while (n < max(a.size(), b.size()))  n <<= 1;
	n <<= 1;
	//cout << a.size() << " " << b.size() << endl;
	fa.resize(n), fb.resize(n);
	fft(fa, false), fft(fb, false);
	for (size_t i = 0; i<n; ++i)fa[i] *= fb[i];
	fft(fa, true);
	vl res;
	res.resize(n);
	for (size_t i = 0; i<n; ++i)res[i] = int(fa[i].real() + 0.5);
	return res;
}
vl power(vl base ,lo exp){
	vl res(1024,0);
	res[0]=1;
    while(exp>0){
       if(exp%2==1)res=mult(res,base);
       while(res.size()>(1<<20))res.pop_back();
       base=mult(base,base);
       while(base.size()>(1<<20))base.pop_back();
       exp/=2;
    }
    while(res.size()>(1<<20))res.pop_back();
    return res;
}

