bool used[110000];
struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

struct Edge {
	ll a, b, cost;
	bool operator<(const Edge& o) const {
		return cost < o.cost;
	}
};

vector<Edge> es;  // 隣接リスト a, b, cost

ll kruskal() {
	sort(es.begin(), es.end());
	UnionFind uf(210000);
	ll min_cost = 0;
	REP(ei, es.size()) {
		Edge& e = es[ei];
		if (!uf.findSet(e.a, e.b)) {
			min_cost += e.cost;
			uf.unionSet(e.a, e.b);
			used[ei] = true;
		}
	}
	return min_cost;
}

