    for(ll i = 0; i < n; i++){
        for(ll j = 0; j < n; j++){
            cin >> cost[i][j];
            if(i > j) que.push({cost[i][j], {i, j}});
        }
    }

    vector<vector<ll>> dist(n, vector<ll>(n, INF));
    vector<vector<pair<ll,ll>>> hen(n);
    for(int i = 0; i < n; i++)dist[i][i] = 0;
    ll ans = 0;

