#define INF (1LL << 60)
using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;

struct edge {
  ll d, u, v;
public:
  bool operator<(const edge &e) const { return d < e.d; }
};

ll N, A;
vector<edge> D;
vector<pll> E[300];

ll dist(ll s, ll g) {
  ll visited[300];
  REP(i, 0, N) visited[i] = false;
  priority_queue<pll, vector<pll>, greater<pll> > q;
  q.push(pll(0, s));

  while(!q.empty()) {
    ll p = q.top().first;
    ll u = q.top().second;
    q.pop();

    if(u == g) return p;
    if(visited[u]) continue;
    visited[u] = true;

    REP(i, 0, E[u].size()) {
      ll d = E[u][i].first;
      ll v = E[u][i].second;
      q.push(pll(p + d, v));
    }
  }

  return INF;
}

int main(void) {
  cin >> N;
  REP(i, 0, N) REP(j, 0, N) {
    cin >> A;
    if(j > i) D.push_back((edge) { A, i, j });
  }

  sort(D.begin(), D.end());

  ll ans = 0;
  REP(i, 0, D.size()) {
    ll d = dist(D[i].u, D[i].v);
    if(d < D[i].d) {
      ans = -1;
      break;
    }
    if(D[i].d < d) {
      E[D[i].u].push_back(pll(D[i].d, D[i].v));
      E[D[i].v].push_back(pll(D[i].d, D[i].u));
      ans += D[i].d;
    }
  }
  cout << ans << endl;
}

