int N;
LL minL[305][305];
bool decided[305][305] = {};
const LL INF = 1000000001;

struct Load{
	int s, g;
	int cost;
	void Set(int _s,int _g,int _c) {
		s = _s;
		g = _g;
		cost = _c;
	}
	bool operator < (const Load& _l) const{ return cost < _l.cost; };
	bool operator > (const Load& _l) const { return cost > _l.cost; };
}nolma[45000];
struct Node {
	int minL;
	int num;
	bool operator < (const Node& _l) const { return minL < _l.minL; };
	bool operator > (const Node& _l) const { return minL > _l.minL; };
}nodes[305];
priority_queue<Node> PQ;

LL ans = 0;

int M=0;

void Update() {
	for (int i = 1; i <= N; i++) {

		for (int j = 1; j <= N; j++) {
			nodes[j].minL = minL[i][j];
			if (minL[i][j] != INF) {
				PQ.push(nodes[j]);
			}
		}
		while (!PQ.empty()) {
			Node now = PQ.top(); PQ.pop();
			if (minL[i][now.num] < now.minL) continue;

			for (int j = 1; j <= N; j++) {
				if (!decided[i][j]) {
					if (minL[i][j] > minL[i][now.num] + minL[now.num][j]) {
						minL[i][j] = minL[j][i] = minL[i][now.num] + minL[now.num][j];
						nodes[j].num = j;
						nodes[j].minL = minL[i][j];
						PQ.push(nodes[i]);
					}
				}
			}
		}


	}
}

int main() {
	scanf("%d",&N);
	for (int i = 1; i <= N;i++) {
		nodes[i].num = i;
		for (int j = 1; j <= N; j++) {
			int c;
			scanf("%d", &c);
			minL[j][i] = minL[i][j] = INF;
			if (i<j) {
				nolma[M].Set(i, j, c);
				M++;
			}
		}
	}
	sort(nolma, nolma+N*(N - 1)/2);

	for (int i = 0; i < N*(N - 1) / 2;i++) {
		int s = nolma[i].s,g=nolma[i].g,c=nolma[i].cost;

		if (minL[s][g]<c) {
			ans = -1;
			break;
		}
		else {
			decided[s][g] = decided[g][s] = true;
			if (minL[s][g] > c) {
				minL[s][g] = minL[g][s] = c;
				Update();
				ans += c;

			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

