    cin.tie(0);
    cin >> n;
    ll a[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
        }
    }

    vector<edge> vec;
    for (int i = 0; i < n-1; i++) {
        for (int j = i+1; j < n; j++) {
            edge e = {i, j, a[i][j]};
            vec.push_back(e);
        }
    }

    sort(vec.begin(), vec.end(), compareTwoEdge);

    ll ans = 0LL;
    for (int i = 0; i < vec.size(); i++) {
        edge e = vec[i];
        dijkstra(e.from);
        if (d[e.to] > e.cost) {
            G[e.from].push_back(e);
            edge e2 = {e.to, e.from, e.cost};
            G[e.to].push_back(e2);
            ans += e.cost;
        } else if (d[e.to] < e.cost) {
            ans = -1LL;
            break;
        }
    }

    cout << ans << "\n";
    return 0;
}

