    ll ans = 0;
    for(int i=1;i<=n;i++){
        for(int j=i+1;j<=n;j++){
            pq.emplace(a[i][j], pii(i,j));
            ans += a[i][j];
        }
    }
    int flag = 0;
    while(!pq.empty()){
        auto p = pq.top();
        pq.pop();
        int x = p.second.first;
