#include<bits/stdc++.h>
#define X first
#define Y second
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
const int N = 305;
const ll inf = 1e18;

int n, a[N][N];
ll ans, dis[N], adj[N][N];

vector<pair<int,pii> > edg;

priority_queue<pll> pq;

ll dist (int A, int B) {
	for(int i=1;i<=n;i++) {
		dis[i] = inf;
	}
	dis[A] = 0;
	pq.push({0, A});
	while(!pq.empty()) {
		ll C = pq.top().Y, D = -pq.top().X;
		pq.pop();
		if(dis[C] != D) continue;
		if(C == B) return D;
		for(int i=1;i<=n;i++) {
			if(dis[i] > D + adj[C][i]) {
				dis[i] = D + adj[C][i];
				pq.push({-dis[i], i});
			}
		}
	}
	return inf;
}

int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++) {
		for(int j=1;j<=n;j++) {
			scanf("%d",&a[i][j]);
			if(i < j) edg.push_back({a[i][j], {i,j}});
			adj[i][j] = inf;
		}
	}
	sort(edg.begin(), edg.end());
	for(auto &T : edg) {
		ll D = dist(T.Y.X, T.Y.Y);
		if(D < T.X) {
			puts("-1");
			return 0;
		}
		else if(D > T.X) {
			ans += T.X;
			adj[T.Y.X][T.Y.Y] = T.X;
			adj[T.Y.Y][T.Y.X] = T.X;
		}
	}
	printf("%lld\n",ans);
}

#include <bits/stdc++.h>

#define MAX_N 300

using namespace std;

typedef pair<int, int> P;

int N;
int A[MAX_N][MAX_N];

long long solve()
{
    long long answer = 0;
    P b[MAX_N];
    for (int u = 0; u < N; u++) {
        for (int i = 0; i < N; i++) {
            b[i] = P(A[u][i], i);
        }
        sort(b, b + N);
        // b[0] == (0, i);
        for (int i = 1; i < N; i++) {
            int v = b[i].second;
            if (v > u) {
                continue;
            }
            bool needRoad = true; // need a road between city u and v with length A[u][v].
            for (int j = 1; j < i; j++) {
                int w = b[j].second;
                int determinant = A[u][w] + A[w][v] - A[u][v];
                if (determinant < 0) {
                    return -1;
                }
                if (determinant == 0) {
                    needRoad = false;
                    break;
                }
            }
            if (needRoad) {
                answer += A[u][v];
            }
        }
    }
    return answer;
}

int main(void)
{
    cin >> N;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> A[i][j];
        }
    }
    cout << solve() << endl;
    return 0;
}

