template<class T>
using Edges = vector<Edge<T>>;

template<class T>
using WeightedGraph = vector<Edges<T>>;

using UnWeightedGraph = vector<vector<int>>;

template<class T>
using DistMatrix = vector<vector<T>>;

struct GraphAdapter {
    template<class T>
    static UnWeightedGraph to_unweighted_graph(const WeightedGraph<T> &origin) {
        int V = origin.size();
        UnWeightedGraph graph(V);
        for (int i = 0; i < V; i++) for (auto &e: origin[i]) graph[i].push_back((int) e);
        return graph;
    }

    static WeightedGraph<int> to_weighted_graph(const UnWeightedGraph &origin) {
        int V = origin.size();
        WeightedGraph<int> graph(V);
        for (int i = 0; i < V; i++) for (auto to: origin[i]) graph[i].push_back({i, to, 1});
        return graph;
    }

    template<class T>
    static DistMatrix<T> to_dist_matrix(const WeightedGraph<T> &origin, T INF) {
        int V = origin.size();
        DistMatrix<T> matrix(V, vector<T>(V, INF));
        for (int i = 0; i < V; i++) for (auto &e:origin[i]) matrix[i][e.to] = e.cost;
        for (int i = 0; i < V; i++) matrix[i][i] = 0;
        return matrix;
    }
};

template<class T>
class WarshallFloyd {
    int N;
    DistMatrix<T> matrix;
    T INF;

public:
    WarshallFloyd(const DistMatrix<T> matrix, const T INF) : matrix(matrix), N(matrix.size()), INF(INF) {
        build();
    }

    void build() {
        for (int i = 0; i < N; i++) matrix[i][i] = 0;
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (matrix[i][k] == INF || matrix[k][j] == INF)continue;
                    matrix[i][j] = min(matrix[i][j], matrix[i][k] + matrix[k][j]);
                }
            }
        }
    }

    DistMatrix<T> get_matrix() const {
        return matrix;
    }

    bool has_minus_cycle() const {
        bool is_minus = false;
        for (int i = 0; i < N; i++) if (matrix[i][i] < 0) is_minus = true;
        return is_minus;
    }

    void show() const {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                printf("%4lld ", matrix[i][j]);
            }
            cout << endl;
        }
        cout << endl;
    }
};

template<typename T>
class Dijkstra {
    using Pr = pair<T, int>;
private:
    int V;
    const WeightedGraph<T> &graph;
    const T INF = numeric_limits<T>::max();
    vector<T> dist;
    vector<int> prev;

public:

    Dijkstra(const WeightedGraph<T> &graph, int s) : graph(graph) {
        V = graph.size();
        dijkstra(s);
    }

    void dijkstra(int s) {
        priority_queue<Pr, vector<Pr>, greater<>> Q;
        dist = vector<T>(V, INF);
        prev = vector<int>(V, -1);
        Q.push(make_pair(0, s));
        dist[s] = 0;
        while (!Q.empty()) {
            auto p = Q.top();
            Q.pop();
            T now = p.first;
            int v = p.second;
            if (dist[v] < now)continue;
            for (auto e: graph[v]) {
                int to = e.to;
                T cost = e.cost;
                if (dist[to] > dist[v] + cost) {
                    dist[to] = dist[v] + cost;
                    prev[to] = v;
                    Q.push(make_pair(dist[to], to));
                }
            }
        }
    }

    vector<T> get_dist() const {
        return dist;
    }

    vector<int> get_prev() const {
        return prev;
    }

};

