int main() {

    int N;
    cin >> N;

    DistMatrix<LL> matrix(N, vector<LL>(N));
    cin >> matrix;

    WarshallFloyd<LL> warshallFloyd(matrix, 1e16);
    auto ret = warshallFloyd.get_matrix();

    if (matrix != ret) {
        cout << -1 << endl;
        return 0;
    }

    vector<edge> edges;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i < j) {
                edges.push_back(make_tuple(ret[i][j], i, j));
            }
        }
    }
    sort(edges.begin(), edges.end());

    WeightedGraph<LL> G(N);
    LL ans = 0;
    for (auto e:edges) {
        auto cost = get<0>(e);
        int f = get<1>(e);
        int to = get<2>(e);
        Dijkstra<LL> dijkstra(G, f);
        LL toCost = dijkstra.get_dist()[to];
        if (toCost > cost) {
            ans += cost;
            G[f].push_back({f, to, cost});
            G[to].push_back({to, f, cost});
        }
    }

    cout << ans << endl;

    return 0;
}

