int ufFind(int u)
{
	if (parent[u] < 0)
		return u;
	return parent[u] = ufFind(parent[u]);
}

bool ufUnion(int u, int v)
{
	u = ufFind(u);
	v = ufFind(v);
	if (u == v)
		return false;
	parent[u] = v;
	return true;
}


