using namespace std;
#define ll long long
ll p[301];
struct query{
	ll dis,v1,v2;
	query(ll d,ll V,ll V2){
		dis = d;
		v1 = V;
		v2 = V2;
	}
};
bool cmp(query a,query b) {return a.dis < b.dis;}
vector<query> v;
ll find(ll x) {return p[x] = (p[x] == x ? x : find(p[x]));}
void merge(ll x,ll y){
	ll xroot = find(x);
	ll yroot = find(y);
	p[xroot] = yroot;
}
ll cnt,n;
ll adj[301][301],dist[301][301],matrix[301][301],dist2[301][301];
void init(){
	for(int i = 1; i <= 300; ++i){
		p[i] = i;
		for(int j = 1; j <= 300; ++j){
			adj[i][j] = INT_MAX;
			dist2[i][j] = (i == j ? 0 : INT_MAX);
		}
	}
}
bool check(){
	int i,j,k;
    for(i = 1; i <= n; i++)
        for(j = 1; j <= n; j++){
        	dist[i][j] = adj[i][j];
		}

    for(k = 1; k <= n; k++){
        for (i = 1; i <= n; i++){
            for (j = 1; j <= n; j++){
                if(dist[i][k] + dist[k][j] < dist[i][j]) 
					dist[i][j] = dist[i][k] + dist[k][j];
            }
        }
    }
    for(i = 1; i <= n; ++i){
    	for(j = 1; j <= n; ++j){
    		if(dist[i][j] != matrix[i][j]){
    			return false;
			}
		}
	}
	return true;
}
void solve(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n;
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= n; ++j){
			ll x; cin >> x;
			matrix[i][j] = x;
			if(i == j) adj[i][j] = 0;
			v.push_back(query(x,i,j));
		}
	}
	sort(v.begin(),v.end(),cmp);
	for(int i = 0; i < (int) v.size(); ++i){
		ll v1 = v[i].v1;
		ll v2 = v[i].v2;
		ll dis = v[i].dis;
		ll root = find(v1);
		ll root2 = find(v2);
		if(dis != dist2[v1][v2]){
			merge(v1,v2);
			adj[v2][v1] = adj[v1][v2] = dis;
			dist2[v1][v2] = dist2[v2][v1] = dis;
			cnt += dis;
			for(int j = 1; j <= 300; ++j){
				dist2[v1][j] = min(dist2[v1][j],dist2[v2][j] + dis);
				dist2[j][v1] = min(dist2[j][v1],dist2[j][v2] + dis);
				dist2[v2][j] = min(dist2[v2][j],dist2[v1][j] + dis);
				dist2[j][v2] = min(dist2[j][v2],dist2[j][v1] + dis);
			}
		}else if(root != root2){
			merge(root,root2);
			cnt += dis;
			adj[v2][v1] = adj[v1][v2] = dis;
			dist2[v1][v2] = dist2[v2][v1] = dis;
			for(int j = 1; j <= 300; ++j){
				dist2[v1][j] = min(dist2[v1][j],dist2[v2][j] + dis);
				dist2[j][v1] = min(dist2[j][v1],dist2[j][v2] + dis);
				dist2[v2][j] = min(dist2[v2][j],dist2[v1][j] + dis);
				dist2[j][v2] = min(dist2[j][v2],dist2[j][v1] + dis);
			}
		}
	}
	if(!check()) cout << -1 << endl;
	else cout << cnt << endl;
}
int main(){
	init();
	solve();
}

