void input() {
    cin >> N;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
        cin >> A[i][j];
    }
}

bool exist_graph() {
    for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++)
        if (A[i][j] != G[i][j])
            return false;
    return true;
}

void solve() {
    for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++) {
        G[i][j] = i != j ? A[i][j] : 0;
        exist_path[i][j] = i != j;
    }
    // warshall-floyd
    for (ll g = 0; g < N; g++) {
        for (ll s = 0; s < N; s++) {
            if (s == g) continue;
            for (ll t = s + 1; t < N; t++) {
                if (s == t or t == g) continue;
                ll till = G[s][t], will = G[s][g] + G[g][t];
                if (will == till) {
                    exist_path[s][t] = false;
                    exist_path[t][s] = false;
                }
                ll val = min(till, will);
                G[s][t] = val;
                G[t][s] = val;
            }
        }
    }
    if (not exist_graph()) {
        cout << -1 << endl;
        return;
    }

    ll ans = 0;
    for (ll i = 0; i < N; i++) {
        for (ll j = i + 1; j < N; j++) {
            if (exist_path[i][j]) ans += A[i][j];
        }
    }
    cout << ans << endl;
}

