constexpr int N_MAX=300;
int N;

struct Edge {
  int u,v;
  ll cost;

  Edge(int u_, int v_, ll cost_)
    : u(u_), v(v_), cost(cost_)
  {}
};

vector<Edge> edges;

vvll A(N_MAX, vll(N_MAX));
vvll M(N_MAX, vll(N_MAX));

int main(int argc, char** argv) {
  cin >> N;

  for (int i=0; i<N; i++) {
    for (int j=0; j<N; j++) {
      cin >> A[i][j];
      M[i][j] = A[i][j];

      if (i>j) {
        edges.emplace_back(i, j, A[i][j]);
      }
    }
  }

  // Warshall-Froid
  for (int k=0; k<N; k++) {
    for (int i=0; i<N; i++) {
      for (int j=0; j<N; j++) {
        M[i][j] = min({M[i][j], M[i][k]+M[k][j]});
      }
    }
  }

  sort(begin(edges), end(edges),
       [](const Edge& lhs, const Edge& rhs) {
         return lhs.cost < rhs.cost;
       });

  ll ret = 0;

  for (auto e : edges) {
    int i = e.u;
    int j = e.v;

    assert(e.cost == A[i][j]);

    if (M[i][j] < A[i][j]) {
      cout << -1 << endl;
      return 0;
    }

    assert(M[i][j] == A[i][j]);

    // minimum path that does not use {i,j}
    ll walkaround = INF;
    for (int k=0; k<N; k++) {
      if (k==i || k ==j) {
        continue;
      }
      walkaround = min({walkaround, M[i][k] + M[k][j]});
    }

    if (walkaround > M[i][j]) {
      // required
      ret += M[i][j];
    }
  }


  // cerr << "*** ret " << ret << endl;
  // cerr << "***M***\n";
  // for (int i=0; i<N; i++) {
  //   for (int j=0; j<N; j++) {
  //     cerr << M[i][j] << " ";
  //   }
  //   cerr << endl;
  // }

  cout << ret << endl;

  return 0;
}

