void Dijkstra(Graph graph, int start, vi &cost, int V) {
	vi prev(V);
	pqlP Q;

	fill(cost.begin(), cost.end(), INF);
	cost[start] = 0;

	Q.push(mp(0, start));	// (cost, index)

	while (!Q.empty()) {
		P pos = Q.top();
		Q.pop();
		rep(i, graph[pos.second].size()) {
			if (cost[graph[pos.second][i].to] > cost[pos.second] + graph[pos.second][i].cost) {
				cost[graph[pos.second][i].to] = cost[pos.second] + graph[pos.second][i].cost;
				Q.push(mp(cost[graph[pos.second][i].to], graph[pos.second][i].to));
				prev[graph[pos.second][i].to] = pos.second;
			}
		}
	}
}

bool WarshallFloyd(vvll &graph, int V) {
	rep(k, V)rep(i, V)rep(j, V) {
		// i->(k)->j
		if (graph[i][k] != INFL && graph[k][j] != INFL) {
			graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j]);
		}
	}
	rep(i, V) {
		if (graph[i][i] < 0) return false;
	}
	return true;
}

