    rep(i, n) rep(j, n) cin >> a[i][j];

    vector<pair<ll, pll> > v;
    rep(i, n) REP(j, i + 1, n) v.push_back(MP(a[i][j], MP(i, j)));
    sort(v.begin(), v.end());
    ll ans = 0;
    dijkstra<ll, ll> ds;
    for (auto pp : v) {
        ll now_dist = pp.first;
        pll p = pp.second;
        ll From = p.first, To = p.second;
        ds.calc(p.first);
        if (ds.d[p.second] == LINF || now_dist < ds.d[p.second]) {
            ans += now_dist;
            ds.E[From].push_back({To, now_dist});
            ds.E[To].push_back({From, now_dist});
        }
    }
    ll dist[n][n];
    rep(i, n) rep(j, n) dist[i][j] = (i == j ? 0 : LINF);

    rep(i, n) {
        for (auto e : ds.E[i]) {
            ll j = e.to;
            ll c = e.cost;
            dist[i][j] = dist[j][i] = c;
        }
    }

    rep(i, n) rep(j, n) rep(k, n) dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
    bool valid = true;
    rep(i, n) rep(j, n) if (a[i][j] != dist[i][j]) valid = false;
    cout << (valid ? ans : -1) << endl;
    return 0;
}

