bool operator < (Edge a,Edge b) {
    return  a.d<b.d;
}

int n,m;
int a[maxn][maxn],b[maxn][maxn];
int cnt;
LL res;
bool able;

void solve() {
	able=1;	

	for(int k=1;k<=n;k++)
	for(int i=1;i<=n;i++)
	for(int j=1;j<=n;j++) {
		b[i][j]=min(b[i][j],b[i][k]+b[k][j]);
	}

	for(int i=1;i<=n;i++)
	for(int j=1;j<=n;j++) 
	if(a[i][j]!=b[i][j]) {
		able=0;
		return;	
	}

	for(int i=1;i<=n;i++)
	for(int j=i+1;j<=n;j++) 
		q[++m]=Edge(i,j,a[i][j]);

	for(int i=1;i<=n;i++)
	for(int j=1;j<=n;j++)
		b[i][j]=inf;
	for(int i=1;i<=n;i++) b[i][i]=0;
	cnt=n*(n-1);
	sort(q+1,q+m+1);

	return;
	for(int i=1;i<=m;i++) if(b[q[i].u][q[i].v]>q[i].d) {
		res+=q[i].d;
		//printf("Test %d %d %d\n",q[i].u,q[i].v,q[i].d);
		b[q[i].u][q[i].v]=b[q[i].v][q[i].u]=q[i].d;
		cnt-=2;
		for(int j=1;j<=m;j++)
		for(int k=1;k<=m;k++) 
		if(j!=q[i].v && k!=q[i].u && b[j][k]>a[j][k] && b[j][q[i].u]!=inf 
		  &&b[q[i].v][k]!=inf && a[j][k]-b[q[i].u][q[i].v]==b[j][q[i].u]+b[q[i].v][k]) {
			b[j][k]=b[k][j]=a[j][k];
			cnt-=2;
			if(!cnt) return;
		}
	}
}

int main() {
	scanf("%d",&n);
	for(int i=1;i<=n;i++) 
	for(int j=1;j<=n;j++) {
		scanf("%d",&a[i][j]);
		b[i][j]=a[i][j];
	}
	solve();
	if(!able) cout << "-1\n" ;
	else cout<< res << "\n";
	return 0;
}

