                    a.push_back(make_pair(i,j));//如果有一樣路程的路，把他放進a，等等刪掉 
            }
    ans = 0;
    for(size_t i =0;i<a.size();i++)//* vector要用size_t 因為vector的函釋回傳值是unsing int ( = size_t 
