using namespace std;
const int MAXN = 305;
struct Edge {
    int v, w;
};
vector<Edge> adj[MAXN];
int n;
struct Item {
    int val;
    int u, v;
};
bool cmp(const Item &a, const Item &b) {
    return a.val < b.val;
}
int dis[MAXN];
bool inque[MAXN];
void spfa(int s) {
    queue<int> que;
    dis[s] = 0;
    inque[s] = true;
    que.push(s);
    while(!que.empty()) {
        int u = que.front(); que.pop();
        inque[u] = false;
        for(int i = 0; i < adj[u].size(); i++) {
            if(dis[adj[u][i].v] > dis[u] + adj[u][i].w) {
                dis[adj[u][i].v] = dis[u] + adj[u][i].w;
                if(!inque[adj[u][i].v]) {
                    inque[adj[u][i].v] = true;
                    que.push(adj[u][i].v);
                }
            }
        }
    }
}
Item item[MAXN * MAXN];
int cnt_item;
int main() {
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) {
            int val; scanf("%d", &val);
            if(i < j) {
                item[cnt_item++] = (Item){val, i, j};
            }
        }
    sort(item, item + cnt_item, cmp);
    long long ans = 0;
    for(int i = 0; i < cnt_item; i++) {
        memset(dis, 0x3f, sizeof(dis));
        spfa(item[i].u);
        if(dis[item[i].v] < item[i].val) {
            printf("-1\n");
            return 0;
        }
        else if(dis[item[i].v] > item[i].val) {
            adj[item[i].u].push_back({item[i].v, item[i].val});
            //adj[item[i].v].push_back({item[i].u, item[i].val});
            ans += item[i].val;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

