const int MAX_V = 100000;

struct edge{int from; int to; ll cost;};
vector<edge> G[MAX_V];
ll d[MAX_V];

void add_edge(int from, int to, ll cost) {
    edge e = {from, to, cost};
    G[from].push_back(e);
}

void dijkstra(int s) {
    struct q_v{
        int id;
        ll d;
        bool operator< (const q_v &t) const {
            return t.d < d;
        }
    };
    bool end[MAX_V] = {};
    for (int i = 0; i < MAX_V; i++) d[i] = INF;
    d[s] = 0;
    priority_queue<q_v> q;
    q.push(q_v{s, 0});
    while (!q.empty()) {
        int v = q.top().id;
        q.pop();
        if (end[v]) continue;
        end[v] = true;
        for (edge e : G[v]) {
            if (!end[e.to]) {
                d[e.to] = min(d[e.to], d[v] + e.cost);
                q.push(q_v{e.to, d[e.to]});
            }
        }
    }
}

ll N;
ll ans = 0;

void solve() {
    cin >> N;
    ll A[N][N] = {};
    rep(i,N) rep(j,N) cin >> A[i][j];
    vector<pair<ll,pair<int,int>>> E; // l, from, to
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            pair<ll,pair<int,int>> p(A[i][j], pair<int,int>(i,j));
            E.push_back(p);
        }
    }
    sort(E.begin(), E.end());
    rep(i,E.size()) {
        ll cost = E[i].first;
        int from = E[i].second.first;
        int to = E[i].second.second;
        dijkstra(from);
        if (cost < d[to]) {
            add_edge(from, to, cost);
            add_edge(to, from, cost);
            ans += cost;
        } else if (cost > d[to]) {
            cout << -1 << endl;
            return;
        }
    }
    cout << ans << endl;
}

