    priority_queue<T, vector<T>, greater<T>> que;
    for(ll i = 0; i < n; i++){
        for(ll j = 0; j < n; j++){
            cin >> cost[i][j];
            if(i > j) que.push({cost[i][j], {i, j}});
        }
    }
    Union_Find uni(n);
    vector<vector<ll>> dist(n, vector<ll>(n, INF));
    vector<vector<pair<ll,ll>>> hen(n);
    for(ll i = 0; i < n; i++)dist[i][i] = 0;
    ll ans = 0;

    while(que.size()){
        ll co = que.top().first;
        auto ver = que.top().second;
        que.pop();
        if(co > dist[ver.first][ver.second] || co > dist[ver.second][ver.first]){
            cout << -1 << endl;
            return 0;
        }

        if(co == dist[ver.first][ver.second])continue;
        dist[ver.first][ver.second] = co;
        dist[ver.second][ver.first] = co;
        hen[ver.first].push_back({ver.second, co});
        hen[ver.second].push_back({ver.first, co});

        if(uni.root(ver.second) != uni.root(ver.first) && (uni.size(ver.first) != 1 || uni.size(ver.first != 1))){
            uni.unit(ver.first, ver.second);
            for(int k = 0; k < n; k++){
                for(int i = 0; i < n; i++){
                    for(int j = 0; j < n; j++)dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }else{
            dijkstra(n, ver.first, hen, dist);
            dijkstra(n, ver.second, hen, dist);
        }
        ans += co;

    }
    cout << ans << endl;

}

