using namespace std;
using ll = long long;
using ull = size_t;

ll N;
ll A[300][300];
ll G[300][300];
vector<pair<ll, ll>> graph[300];

void input() {
    cin >> N;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
        cin >> A[i][j];
        graph[i].push_back({j, A[i][j]});
    }
}

bool minlen_dfs(ll start, ll city, ll cost) {
    bool clear = true;
    for (auto path : graph[city]) {
        ll target = path.first;
        ll next_cost = cost + path.second;
        if (next_cost < A[start][target]) {
            return false;
        }
        if (next_cost < G[start][target]) {
            G[start][target] = next_cost;
            clear &= minlen_dfs(start, target, next_cost);
        }
    }
    return clear;
}

bool build_map() {
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++)
        G[i][j] = i != j ? numeric_limits<ll>::max() : 0;
    for (ll s = 0; s < N; s++) {
        if (not minlen_dfs(s, s, 0))
            return false;
    }
    return true;
}

void solve() {
    if (not build_map()) {
        cout << -1 << endl;
        return;
    }

    struct Path {
        ll f, t, c;
    };
    vector<Path> paths;
    for (ll i = 0; i < N; i++) {
        for (auto path : graph[i])
            paths.push_back({i, path.first, path.second});
    }
    sort(paths.begin(), paths.end(), [](auto l, auto r) {return l.c < r.c;});
    for (auto path : paths) {
        pair<ll, ll> find_target{path.t, path.c};
        auto cpathit = find(graph[path.f].begin(), graph[path.f].end(), find_target);
        auto cpath = *cpathit;
        graph[path.f].erase(cpathit);
        if (not build_map()) {
            graph[path.f].push_back(cpath);
        }
        for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++)
            if (A[i][j] != G[i][j]) {
                graph[path.f].push_back(cpath);
                break;
            }
    }
    ll ans = 0;
    for (ll i = 0; i < N; i++) for (auto path : graph[i])
        ans += path.second;
    cout << ans / 2 << endl;
}

int main() {
    input();

    solve();

    return 0;
}

