using namespace std;

int64_t distance(vector<vector<int64_t>> const &mat, int64_t a, int64_t b)
{
    priority_queue<pair<int64_t, int64_t>, vector<pair<int64_t, int64_t>>, std::greater<pair<int64_t, int64_t>>> q;
    vector<int64_t> mindist;
    mindist.resize(mat.size(), numeric_limits<int64_t>::max());

    q.push({0, a});
    while (!q.empty())
    {
        auto t = q.top();
        q.pop();
        if (t.second == b)
            continue;
        for (int64_t i = 0; i < mat.size(); i++)
        {
            if (mat[t.second][i] != -1 && mat[t.second][i] + t.first < mindist[i])
            {
                mindist[i] = mat[t.second][i] + t.first;
                q.push({mindist[i], i});
            }
        }
    }

    return mindist[b];
}

int main()
{
    int64_t n;
