    vector<vector<int64_t>> mat(n);
    for (auto &x : mat)
        x.resize(n, -1);

    using dist_t = pair<int64_t, pair<int64_t, int64_t>>;
    priority_queue<dist_t, vector<dist_t>, std::greater<dist_t>> dist;
