template <int NMAX>
class UnionFind {
private:
  int par[NMAX];  // 親
  int rank[NMAX]; // 木の深さ

  int find(int x) {
      if (par[x] == x) {
  	return x;
      } else {
  	return par[x] = find(par[x]);
      }
  }

public:
  void init(int n) {
    for (int i=0; i<n; i++) {
	par[i] = i;
	rank[i] = 0;
    }
  }

  void unite(int x, int y) {
      x = find(x);
      y = find(y);
      if (x==y) return;

      if (rank[x] < rank[y]) {
  	par[x] = y;
      } else {
  	par[y] = x;
  	if (rank[x] == rank[y]) rank[x]++;
      }
  }

  bool same(int x, int y) {
      return find(x) == find(y);
  }
};



// O(|E| log|V|) ???
template <int NMAX>
class Kruskal {
public:
  struct Edge {
    int v;
    int u;
    ll cost;
  };

private:

  int N;
  vector<Edge> edges;
  UnionFind<NMAX> uf;

  void sortEdges() {
    sort(begin(edges), end(edges),
         [](const Edge& lhs, const Edge& rhs) {
           return lhs.cost < rhs.cost;
	 });
  }

public:

  vector<Edge> used;
  vector<int> d;
  vector<vector<pair<int, ll> > > G;

  // set d[start] = 0 in advance
  void dfs(int v) {
    for (auto uc : G[v]) {
      int u = uc.first;
      ll cost = uc.second;

      if (d[u] >= INF || d[u] > d[v] + cost) {
        d[u] = d[v] + cost;
	dfs(u);
      }
    }
  }

  explicit Kruskal(int _N)
    : N(_N), d(_N, INF), G(_N) {
  }

  void addEdge(int v, int u, ll cost) {
    edges.emplace_back(Edge{v, u, cost});
  }


  ll spanningTree() {
    ll ret = 0;

    sortEdges();
    uf.init(N);

    for (auto& e : edges) {
      // check
      if (uf.same(e.u, e.v)) {
        // e.u to e.v
        fill(begin(d), end(d), INF);
        d[e.u] = 0;
        dfs(e.u);
	if (e.cost == d[e.v]) {
          continue;
	} else if (e.cost > d[e.v]) {
          return -1;
	}
	// fall through
      }

      uf.unite(e.u, e.v);
      ret += e.cost;

      used.push_back(e);
      G[e.u].emplace_back(e.v, e.cost);
      G[e.v].emplace_back(e.u, e.cost);
    }

    return ret;
  }

};

