typedef long long LL;
const int Maxn=310;
struct node{int x,y,next; LL d;}edge[Maxn*Maxn*2]; int len,first[Maxn*Maxn*2];
void ins(int x,int y,LL d)
{
  len++; edge[len].x=x; edge[len].y=y; edge[len].d=d; edge[len].next=first[x]; first[x]=len;
}
struct P
{
  int x,y; LL d;
  P(){}
  P(int _x,int _y,LL _d){x=_x; y=_y; d=_d;}
  friend bool operator <(P x,P y){return x.d>y.d;} 
};
queue<int>Q; LL D[Maxn][Maxn]; bool V[Maxn]; int N; LL A[Maxn][Maxn];
priority_queue<P> Q1;
void SPFA(int p)
{
  int ST=p; for(int i=1;i<=N;i++) V[p]=1,D[p][i]=0x3f3f3f3f3f3f3f3f; D[p][p]=0;
  while(!Q.empty()) Q.pop(); Q.push(p);
  while(!Q.empty())
  {
    int x=Q.front();
    for(int k=first[x];k!=-1;k=edge[k].next)
    {
      int y=edge[k].y;
      if(D[p][y]>D[p][x]+edge[k].d)
      {
        D[p][y]=D[p][x]+edge[k].d;
        if(!V[y]){V[y]=1; Q.push(y);}
      }
    }
    V[x]=0; Q.pop();
  }
}
int main()
{
  len=0; memset(first,-1,sizeof(first));
  scanf("%d",&N); for(int i=1;i<=N;i++) for(int j=1;j<=N;j++) scanf("%lld",&A[i][j]);
  while(!Q1.empty()) Q1.pop();
  for(int i=1;i<=N;i++) for(int j=i+1;j<=N;j++) Q1.push(P(i,j,A[i][j])); LL ans=0;
  memset(D,126,sizeof(D));
  for(int i=1;i<=N;i++) D[i][i]=0;
  while(!Q1.empty())
  {
    P x=Q1.top(); Q1.pop();
    if(D[x.x][x.y]>x.d)
    {
      ins(x.x,x.y,x.d);
      ins(x.y,x.x,x.d);
      for(int i=1;i<=N;i++) SPFA(i); ans+=x.d;
    }
    else if(D[x.x][x.y]==x.d) continue;
    else if(D[x.x][x.y]<x.d){ans=-1; break;}
  }
  return printf("%lld\n",ans),0;
}

