const int MAXN=305;
int n,m;
int tmp[MAXN][MAXN];
long long ans;
long long G[MAXN][MAXN];

struct line{
	int u,v,w;
	line(int u=0,int v=0,int w=0):u(u),v(v),w(w){}
	friend bool operator< (const line &a,const line &b){
		return a.w<b.w;
	}
}ed[MAXN*MAXN];

inline bool jud(line &e){
	for(int i=1;i<=n;++i){
		for(int j=1;j<=n;++j){
			if(i==j) continue;
			G[i][j]=min(G[i][j],G[i][e.u]+e.w+G[e.v][j]);
			G[j][i]=G[i][j];
			G[i][j]=min(G[i][j],G[i][e.v]+e.w+G[e.u][j]);
			G[j][i]=G[i][j];
			if(G[i][j]<tmp[i][j]) return false;
		}
	}
	return true;
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;++i){
		for(int j=1;j<=n;++j)
			scanf("%d",&tmp[i][j]);
	}
	for(int i=1;i<n;++i){
		for(int j=i+1;j<=n;++j)
			ed[++m]=line(i,j,tmp[i][j]);
	}
	sort(ed+1,ed+m+1);
	for(int i=1;i<=n;++i){
		for(int j=1;j<=n;++j)
			G[i][j]=1e12;
	}
	for(int i=1;i<=n;++i) G[i][i]=0;
	for(int i=1;i<=m;++i){
		if(G[ed[i].u][ed[i].v]==ed[i].w) continue;
		G[ed[i].u][ed[i].v]=ed[i].w;
		G[ed[i].v][ed[i].u]=ed[i].w;
		ans+=ed[i].w;
		if(!jud(ed[i])){
			ans=-1;
			break;
		}
	}
	cout<<ans;
	return 0;
}

