		for (int j = 1; j <= n; j++) {
			if (a[i][j]) {
				bool direct = 1;
				for (int k = 1; k <= n; k++) {
					if (a[i][k] && a[k][j] && a[i][j] == a[i][k] + a[k][j]) {
						direct = 0;
					}
				}
				if (direct) {
					dp[i][j] = a[i][j];
					sum += a[i][j];
				}
			}
		}
	}
	for (int k = 1; k <= n; k++) {
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= n; j++) {
				if (dp[i][k] != inf && dp[k][j] != inf && dp[i][j] > dp[i][k] + dp[k][j]) {
					dp[i][j] = dp[i][k] + dp[k][j];
				}
			}
		}
	}
	bool no = 0;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			if (i == j) continue;
			if (!dp[i][j]) {
				if (a[i][j]) {
					no = 1;
				}
			} else if (dp[i][j] != a[i][j]) {
				no = 1;
			}
		}
	}
	cout << (no ? -1 : sum / 2);
}

