			cout << -1 << endl;
			return 0;
		}
		if ((!((i==j)||(j==k)||(k==i))) &&a[i][j] == a[i][k] + a[k][j]) {
			m_use[i][j] = 0;
		}
	}
	FOR(i, 0, N) {
		FOR(j, i, N) {
