long long look_up(int i, int j) {
    if (i == j) return 0;

    for (int k = 1; k <= n; ++k) {
        if (dist[i][k] + dist[k][j] == dist[i][j] && i != k && j != k) {
            return look_up(i, k) - dist[k][j];
        }
    }

    return dist[i][j];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
