            aux[i][j] = 0LL;
        }
    }

    for (int k = 1; k <= n; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (i == j || k == i || k == j) continue;
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    cout << -1;
                    return 0;
                }
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i != j) aux[i][j] = look_up(i, j);
        }
    }

