using namespace std;
using ll = long long;
using ull = size_t;

ll N;
ll A[300][300];
ll G[300][300];
bool exist_path[300][300];

void input() {
    cin >> N;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
        cin >> A[i][j];
    }
}

void wf() {
    const ll inf = 1e9+1;
    for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++)
        G[i][j] = i != j ? (exist_path[i][j] ? A[i][j] : inf) : 0;
    for (ll g = 0; g < N; g++) {
        for (ll s = 0; s < N; s++) {
            for (ll t = 0; t < N; t++) {
                G[s][t] = min(G[s][t], G[s][g] + G[g][t]);
            }
        }
    }
}

bool exist_graph() {
    for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++)
        if (A[i][j] != G[i][j])
            return false;
    return true;
}

void solve() {
    for (ll i = 0; i < N; i++) for (ll j = 0; j < N; j++)
        exist_path[i][j] = i != j;
    wf();
    if (not exist_graph()) {
        cout << -1 << endl;
        return;
    }

    struct Path {
        ll f, t, c;
    };
    vector<Path> paths;
    for (ll i = 0; i < N; i++) for (ll j = i + 1; j < N; j++)
        paths.push_back({i, j, A[i][j]});
    sort(paths.begin(), paths.end(), [](auto l, auto r) {return l.c < r.c;});

    for (auto path : paths) {
        exist_path[path.f][path.t] = false;
        exist_path[path.t][path.f] = false;
        wf();
        if (not exist_graph()) {
            exist_path[path.f][path.t] = true;
            exist_path[path.t][path.f] = true;
        }
    }
    ll ans = 0;
    for (ll i = 0; i < N; i++) {
        for (ll j = i + 1; j < N; j++) {
            cerr << exist_path[i][j] << ' ';
            if (exist_path[i][j]) ans += A[i][j];
        }
        cerr << endl;
    }
    cout << ans << endl;
}

int main() {
    input();

    solve();

    return 0;
}

