struct Edge {
	ll from, to, dist;

	Edge(ll u, ll v, ll d) : from(u), to(v), dist(d) {}
};

struct HeapNode {
	ll d, u;

	bool operator<(const HeapNode &rhs) const {
		return d > rhs.d;
	}
};

struct Dijkstra {
	ll n, m;
	vector <Edge> edges;
	vector<ll> G[maxn];
	bool done[maxn];
	ll d[maxn];
	ll roadcount[maxn];
	ll p[maxn];     //×î¶ÌÂ·ÖÐµÄÉÏÒ»Ìõ»¡
	vector<ll> path;

	void init(ll n) {
		this->n = n;
		for (ll i = 0; i < n; i++) G[i].clear();
		edges.clear();
		path.clear();
	}

	void addEdge(ll from, ll to, ll dist) {
		edges.push_back(Edge(from, to, dist));
		m = edges.size();
		G[from].push_back(m - 1);
	}

	void dijkstra(ll s) {    //´Ósµã¿ªÊ¼
		priority_queue <HeapNode> Q;
		for (ll i = 0; i <= n; i++) d[i] = INF;
		for (ll i = 0; i <= n; i++) roadcount[i] = 0;
		d[s] = 0;
		memset(done, 0, sizeof(done));
		Q.push((HeapNode) {
			0, s
		});
		while (!Q.empty()) {
			HeapNode x = Q.top();
			Q.pop();
			ll u = x.u;
			if (done[u]) continue;
			done[u] = true;
			for (ll i = 0; i < G[u].size(); i++) {
				Edge &e = edges[G[u][i]];
				if (d[e.to] > d[u] + e.dist) {
					d[e.to] = d[u] + e.dist;
					roadcount[e.to] = roadcount[u] + 1;
					p[e.to] = G[u][i];
					Q.push((HeapNode) {
						d[e.to], e.to
					});
				} else {
					if(d[e.to] == d[u] + e.dist) {
						roadcount[e.to] = max(roadcount[e.to],roadcount[u] + 1);
					}
				}
			}
		}
	}

	void findpath(ll x, ll end) {
		path.clear();
		path.push_back(x);
		findd(x, end);
	}

	void findd(ll x, ll end) {
		if (x == end)
			return;
		else {
			path.push_back(this->edges[this->p[x]].from);
			findd(this->edges[this->p[x]].from, end);
		}
	}
};

