#include <bits/stdc++.h>

using namespace std;

namespace {

    typedef double real;
    typedef long long ll;
    const ll INF = LLONG_MAX / 16LL;

    template<class T> ostream& operator<<(ostream& os, const vector<T>& vs) {
        if (vs.empty()) return os << "[]";
        auto i = vs.begin();
        os << "[" << *i;
        for (++i; i != vs.end(); ++i) os << " " << *i;
        return os << "]";
    }
    template<class T> istream& operator>>(istream& is, vector<T>& vs) {
        for (auto it = vs.begin(); it != vs.end(); it++) is >> *it;
        return is;
    }

    int N;
    vector<vector<int>> A;
    void input() {
        cin >> N;
        A = vector<vector<int>>(N, vector<int>(N, 0));
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                cin >> A[i][j];
            }
        }
    }

    struct S {
        int from, to; ll cost;
        S(int from, int to, ll cost) : from(from), to(to), cost(cost) {}
        bool operator<(const S& s) const {
            return cost > s.cost;
        }
    };

    ll calc() {
        priority_queue<S> PQ;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                PQ.push(S(i, j, A[i][j]));
            }
        }
        auto D = vector<vector<ll>>(N, vector<ll>(N, INF));
        ll ans = 0;
        while (not PQ.empty()) {
            auto cur = PQ.top(); PQ.pop();
            // cout << cur.from << " -> " << cur.to << " : " << cur.cost << endl;
            auto cur_opt = D[cur.from][cur.to];
            if (cur.cost > cur_opt) return -1;
            if (cur.cost == cur_opt) continue;
            ans += cur.cost;
            D[cur.from][cur.to] = D[cur.to][cur.from] = cur.cost;
            for (auto k : {cur.from, cur.to}) {
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < N; j++) {
                        D[i][j] = min(D[i][j], D[i][k] + D[k][j]);
                    }
                }
            }
        }
        return ans;
    }

    void solve() {
        cout << calc() << endl;
    }
}

int main() {
    input(); solve();
    return 0;
}

