		cin >> A[i][j];
	}
	vector<vector<int>> B = A;
	for (int k = 0; k < N; ++ k) for (int i = 0; i < N; ++ i) for (int j = 0; j < N; ++ j) {
		B[i][j] = min(B[i][j], B[i][k] + B[k][j]);
	}
	if (A != B) {
		cout << -1 << endl;
		return 0;
	}
	vector<pair<int, pair<int,int>>> E;
	for (int i = 0; i < N; ++ i) for (int j = i+1; j < N; ++ j) E.push_back({A[i][j], {i,j}});
	sort(E.begin(), E.end());
	long long r = 0;
	vector<vector<int>> C(N, vector<int>(N, INF));
	for (int i = 0; i < N; ++ i) C[i][i] = 0;
	for (auto e : E) {
		int u = e.second.first;
		int v = e.second.second;
		int w = e.first;
		if (w < C[u][v]) {
			r += w;
			C[u][v] = C[v][u] = w;
			for (int i = 0; i < N; ++ i) {
				C[i][u] = C[u][i] = min(C[i][u], C[i][v] + w);
			}
			for (int i = 0; i < N; ++ i) {
				C[i][v] = C[v][i] = min(C[i][v], C[i][u] + w);
			}
