using namespace std;

struct St
{
	int a;
	int b;
	int len;

	St(int a, int b, int len) :a(a), b(b), len(len) {}

	bool operator<(const St &n) const { return len > n.len; }
};

int N;
int A[300][300];
int fix[300][300];

vector<int> connect[200];
struct DikSt
{
	int n;
	int len;
	DikSt(int n, int len) : n(n), len(len) {}
	bool operator<(const DikSt &n) const { return len > n.len; }
};
int ans[200];
int dikstra(int from, int to)
{
	REP(i, N) ans[i] = INT64_MAX;
	ans[from] = 0;
	priority_queue<DikSt> q;
	q.push(DikSt(from, 0));
	while (q.size() > 0)
	{
		DikSt st = q.top();
		q.pop();
		for (int next : connect[st.n])
		{
			int len = st.len + fix[st.n][next];
			if (ans[next] > len)
			{
				ans[next] = len;
				q.push(DikSt(next, len));
			}
		}
	}
	return ans[to];
}

signed main()
{
	cin >> N;
	REP(x, N) REP(y, N) cin >> A[x][y];

	priority_queue<St> q;
	for (int i = 0; i < N; i++)
	{
		for (int j = i + 1; j < N; j++)
		{
			q.push(St(i, j, A[i][j]));
		}
	}

