#define INF 0xffffffffffffLL
using namespace std;

int n;

struct edge {
	int u, v, d;
} A[90050];
int cnt = 0;
inline bool cmp(const edge &a, const edge &b) {
	return a.d < b.d;
}

int h[330], to[90050], w[90050], nx[90050], e = 1;
inline void adde(int u, int v, int d) {
	to[e] = v; w[e] = d;
	nx[e] = h[u]; h[u] = e++;
}

struct node {
	int p;
	long long d;
	inline bool operator < (const node &a) const {
		return d > a.d;
	}
};
long long dis[330];

long long dijkstra(int s, int t) {
	for (int i = 0; i < n; i++) dis[i] = INF;
	priority_queue<node> q;
	q.push((node){ s, dis[s] = 0 });
	while (!q.empty()) {
		node cur = q.top(); q.pop();
		if (cur.p == t) return dis[t];
		if (cur.d > dis[cur.p]) continue;
		for (int i = h[cur.p]; i; i = nx[i])
			if (dis[to[i]] > cur.d + w[i])
				q.push((node){ to[i], dis[to[i]] = cur.d + w[i] });
	}
	return INF;
}

long long solve() {
	sort(A,A+cnt,cmp);
	long long ans = 0;
	for (int i = 0; i < cnt; i++) {
		long long dis = dijkstra(A[i].u,A[i].v);
		if (A[i].d > dis) return -1;
		if (A[i].d < dis) {
			ans += A[i].d;
			adde(A[i].u,A[i].v,A[i].d);
			adde(A[i].v,A[i].u,A[i].d);
		}
	}
	return ans;
}

int main() {
	scanf("%d",&n);
	int d;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++) {
			scanf("%d",&d);
			if (d) A[cnt++] = (edge){i,j,d};
		}
	printf("%I64d\n",solve());
	return 0;
}

