vector<vector<pair<int, long long int> > > nowgraph(301);
vector<vector<long long int> > minc(301, vector<long long int>(301, -1));

long long int dijkstra(int s, int t)
{
	if(minc[s][t] > 0) return minc[s][t];
	priority_queue<pair<long long int, int> > qu;
	qu.push(make_pair(0, s));
	vector<bool> ischecked(301, false);
	while(!qu.empty()){
		int nownode = (qu.top()).second;
		int nowcost = -(qu.top()).first;
		ischecked[nownode] = true;
		// cout << nownode << endl;
		qu.pop();
		if(nownode == t) return nowcost;
		for(int i = 0; i < nowgraph[nownode].size(); i++){
			int next = nowgraph[nownode][i].first;
			long long int c = nowgraph[nownode][i].second;
			if(ischecked[next]) continue;
			minc[s][next] = minc[next][s] = min(minc[next][s], nowcost + c);
			qu.push(make_pair(-nowcost - c, next));
		}
	}
	return mod;
}

int main()
{
	int n;
	cin >> n;
	long long int a[301][301];
	priority_queue<pair<long long int, pair<int, int> > > qu;
	for(int i = 0; i < n; i++){
		for(int j = 0; j < n; j++){
			cin >> a[i][j];
			if(i < j) qu.push(make_pair(-a[i][j], make_pair(i, j)));
		}
	}
	long long int ans = 0;
	while(!qu.empty()){
		int s = ((qu.top()).second).first;
		int t = ((qu.top()).second).second;
		long long int c = -(qu.top()).first;
		// cout << s << " " << t << endl;
		qu.pop();
		long long int nowc = dijkstra(s, t);
		if(nowc < c){
			cout << -1 << endl;
			return 0;
		}
		if(nowc == c) continue;
		nowgraph[s].push_back(make_pair(t, c));
		nowgraph[t].push_back(make_pair(s, c));
		minc[s][t] = minc[t][s] = c;
		ans += c;
	}
	cout << ans << endl;
	return 0;
}

