void DFS(int w) {
    vis[w] = true;
    for (auto p : V[w]) {
        int u = p.first;
        int kr = p.second;
        if (!vis[u]) {
            Distance[u] = Distance[w] + kr;
            DFS(u);
        }
    }
}

long long calcDist(int a, int b) {
    for (int i = 1; i <= n; i++) {
        Distance[i] = INF;
        vis[i] = false;
    }
    Distance[a] = 0;
    DFS(a);
    return Distance[b];
}

