long long Work() {
    long long ans = 0;
    int n;
    scanf("%d", &n);
    vector< vector<long long> > a(n, vector<long long>(n, 0));
    vector< vector<long long> > b(n, vector<long long>(n, 0));
    vector< pair<long long, pair<int, int> > > c;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (i < j) {
                c.push_back(make_pair(a[i][j], make_pair(i, j)));
            }
            if (i > j && a[i][j] != a[j][i]) { return false; }
        }
    sort(c.begin(), c.end(), [](const pair<long long, pair<int, int> >& a,
                                const pair<long long, pair<int, int> >& b) {
            return (a.first < b.first);
         });
    for (const auto& iter : c) {
        int x = iter.second.first, y = iter.second.second;
        if (b[x][y] == iter.first) {
            continue;
        }
        if (b[x][y] < iter.first && b[x][y] != 0) {
            return -1;
        }
        ans += iter.first;
        b[x][y] = b[y][x] = iter.first;
        for (int i = 0; i < n; i++) {
            if (b[y][i] != 0 && (b[x][i] == 0 || b[x][i] > b[x][y] + b[y][i])) {
                b[x][i] = b[x][y] + b[y][i];
                b[i][x] = b[x][i];
            }
            if (b[x][i] != 0 && (b[y][i] == 0 || b[y][i] > b[x][y] + b[x][i])) {
                b[y][i] = b[x][y] + b[x][i];
                b[i][y] = b[y][i];
            }
        }
    }
    return ans;
}

int main() {
    printf("%lld\n", Work());
    return 0;
}

