LL dijkstra(int cur, int target) {
    set<pair<LL, int> > S;
    S.insert({0ll, cur});
    while (!S.empty()) {
        auto front = *S.begin();
        S.erase(S.begin());
        int u = front.second;
        LL dist = front.first;
        if (u == target) return dist;
        if (vis[u]) continue;
        vis[u] = 1;
        for (pair<int, int> p: g[u]) {
            int v = p.first;
            LL l = p.second;
            S.insert({l + dist, v});
        }
    }
    return INF;
}

