const int MAXN = 305;
struct { int v, next; ll w; } e[MAXN * MAXN];
int head[MAXN], cnt_edge;
inline void add_edge(int u, int v, ll w) {
    e[cnt_edge] = { v, head[u], w };
    head[u] = cnt_edge++;
}
int n;
struct Item {
    ll val;
    int u, v;
    bool operator < (const Item &item) const {
        return val < item.val;
    }
};
ll dis[MAXN];
bool inque[MAXN];
void spfa(int s) {
    queue<int> que;
    dis[s] = 0;
    inque[s] = true;
    que.push(s);
    while(!que.empty()) {
        int u = que.front(); que.pop();
        inque[u] = false;
        for(int i = head[u]; i != -1; i = e[i].next) {
            if(dis[e[i].v] > dis[u] + e[i].w) {
                dis[e[i].v] = dis[u] + e[i].w;
                if(!inque[e[i].v]) {
                    inque[e[i].v] = true;
                    que.push(e[i].v);
                }
            }
        }
    }
}
Item item[MAXN * MAXN];
int cnt_item;
int main() {
    memset(head, 0xff, sizeof(head));
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) {
        ll val; scanf("%lld", &val);
        if(i < j) {
            item[cnt_item++] = (Item){val, i, j};
        }
    }
    sort(item, item + cnt_item);
    ll ans = 0;
    for(int i = 0; i < cnt_item; i++) {
        memset(dis, 0x3f, sizeof(dis));
        spfa(item[i].u);
        if(dis[item[i].v] < item[i].val) {
            printf("-1\n");
            return 0;
        }
        else if(dis[item[i].v] > item[i].val) {
            add_edge(item[i].u, item[i].v, item[i].val);
            add_edge(item[i].v, item[i].u, item[i].val);
            ans += item[i].val;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

