void dijkstra(vector<edge> graph[],ll d[],int start){
  priority_queue<P,vector<P>,greater<P>> que;
  fill(d,d+MAX_N,INF);
  d[start]=0;
  que.push(P(0,start));
  while(!que.empty()){
    P p=que.top(); que.pop();
    int v=p.second; //行き先
    if(d[v]<p.first)  continue;
    rep(i,graph[v].size()){
      edge e=graph[v][i];
      if(d[v]+e.cost<d[e.to]){
        d[e.to]=d[v]+e.cost;
        que.push(P(d[e.to],e.to));
      }
    }
  }
  return ;
}


