#include <bits/stdc++.h>

using namespace std;

const int MAX = 300;
int n;
long long aij[MAX][MAX], bij[MAX][MAX];

void get_input() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> aij[i][j];
        }
    }
}

void init_bij() {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            bij[i][j] = aij[i][j];
        }
    }
}

void warshall_floyd() {
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                bij[i][j] = min(bij[i][j], bij[i][k] + bij[k][j]);
            }
        }
    }
}

bool can_remove_edge_i_j(int i, int j) {
    for (int k = 0; k < n; k++) {
        if (k == i || k == j) continue;
        if (bij[i][j] == bij[i][k] + bij[k][j]) return true;
    }
    return false;
}

long long sum_of_necessary_edges() {
    long long res = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (bij[i][j] < aij[i][j]) return -1;
            if (! can_remove_edge_i_j(i, j)) {
                res += aij[i][j];
            }
        }
    }
    assert (res % 2 == 0);
    return res / 2;
}

int main(void) {
    get_input();
    init_bij();
    warshall_floyd();
    cout << sum_of_necessary_edges() << endl;
    return 0;
}

