            roads.push_back({i, j, a});
        }
    }
    sort(roads.begin(), roads.end(), [](road l, road r) {
        return l.a < r.a; 
    });
    long d[n][n], sum=0;
    fill(d[0], d[n], INF);
    for (int i=0; i<n; i++) d[i][i] = 0;
    for (auto r:roads) {
        int i = r.i, j = r.j;
