        if (d[i][j] > a) {
            for (int k=0; k<n; k++) {
                d[i][k] = d[k][i] = min(d[i][k], d[j][k] + a);
                d[j][k] = d[k][j] = min(d[j][k], d[i][k] + a);
            }
            sum += a;
        } else if (d[i][j] < a) {
            sum = -1;
            break;
        }
    }
    cout << sum << '\n';
