#define MaxN 300+10
using namespace std;
typedef long long LL;
int xd[MaxN];
int find(int a)
{
	if(xd[a]<0)
		return a;
	else
		return xd[a]=find(xd[a]);
} 
 int merge(int a,int b)
 {
 	if(-xd[a]<-xd[b])
 	{
 		xd[b]+=xd[a];
 		xd[a]=b;
 		return -xd[b];
	 }
	 else
	{
		xd[a]+=xd[b];
		xd[b]=a;
		return -xd[a];
	}
 }

LL roads[MaxN][MaxN]; 
LL next_roads[MaxN][MaxN];
LL min(LL a,LL b)
{
	return a<b ? a:b;
}
int main()
{
	int N;
	memset(xd,-1,sizeof(xd));
	scanf("%d",&N);
	for(int i=1;i<=N;i++)
		for(int k=1;k<=N;k++)
		{
			scanf("%lld",&roads[i][k]);
			next_roads[i][k]=roads[i][k];
		}
	for(int k=1;k<=N;k++)
		for(int p=1;p<=N;p++)
			for(int q=1;q<=N;q++)
				next_roads[p][q]=min(next_roads[p][q],next_roads[p][k]+next_roads[k][q]);
	int row,colomn;
	for(row=1;row<=N;row++)
		for(colomn=1;colomn<=N;colomn++)
			if(roads[row][colomn]!=next_roads[row][colomn])
				break;

	if(!(row==N+1 && colomn==N+1) )
		printf("-1\n");
	else
	{
		int sun=0;
		for(int i=1;i<=N;i++)
		{
			int k;
			for(k=i+1;k<=N;k++)
			{
				if(next_roads[i][k]!=0)
				{
					int roota=find(i);
					int rootb=find(k);
					if(roota!=rootb)
					{
						sun=merge(roota,rootb);
						if(sun==N)
							break;
					} 
				}
			}
			if(k<=N)
				break;
		}
		if(sun!=N)
			printf("-1\n");
		else
		{
			LL total=0;
			for(int i=1;i<N;i++)
				for(int k=i+1;k<=N;k++)
				{
					int zhan;
					for(zhan=1;zhan<=N;zhan++)
					{
						if(zhan==i || zhan==k)
							continue;
						if(next_roads[i][k]==next_roads[i][zhan]+next_roads[zhan][k])
							break;
					}
					if(zhan==N+1)
						total+=next_roads[i][k];
				}
			printf("%lld\n",total);
		}
	}

	return 0;
}

