int validate(int from, int to, int n, long long min) {
	bool flg = false;
	for (int i = 0; i < n; i++) {
		if (i == from || i == to) {
			continue;
		}
		if (dist[from][i] + dist[i][to] < min) {
			return -1;
		}
		else if(dist[from][i] + dist[i][to] == min){
			flg = true;
		}
	}
	return flg ? min : 0;
}

int main(void) {
	int N, buf;
	scanf("%d", &N);

	dist = vector<vector<long long>>(N, vector<long long>(N, 0));
	road = vector<vector<long long>>(N, vector<long long>(N, 0));

	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			scanf("%d", &buf);
			dist[i][j] = buf;
		}
	}
	int sum = 0;
	for (int from = 0; from < N; from++) {
		for (int to = from + 1; to < N; to++) {
			if (dist[to][from] != dist[from][to]) {
				printf("-1\n");
				return 0;
			}

			int res = validate(from, to, N, dist[from][to]);
			if (res < 0) {
				printf("-1\n");
				return 0;
			}
			else {
				sum += dist[from][to] - res;
			}
		}
	}

	printf("%lld\n", sum);

	return 0;
}

