struct x_t
{
	int s, e;
	ll d;
	bool operator<(const x_t&rhs) const
	{
		if(d!=rhs.d) return d<rhs.d;
		if(s!=rhs.s) return s>rhs.s;
		return e>rhs.e;
	}
};


ll solve(vvll&a)
{
	int n=a.size();
	ll ret=0;
	set<x_t> s;
	vector<vector<pair<int,ll>>> w(n);

	for(int i=0;i<n;i++)
	{
		for(int j=0;j<i;j++)
		{
			s.insert((x_t){i, j, a[i][j]});
		}
	}
	for(auto it=s.begin();it!=s.end();++it)
	{
		ll d=it->d;
		int i=it->s;
		int j=it->e;
		ll d2=calc(w, i, j);
		if(d2<d)
		{
			return -1;
		}
		if(d2>d)
		{
			w[i].push_back(make_pair(j, d));
			w[j].push_back(make_pair(i, d));
			ret+=d;
		}
	}
	return ret;
}


