#define INF 1000000007
using namespace std;
typedef long long ll;
typedef pair<int,int> P;

int n;
int re_dist[301][301];

struct edge{
	int f,t,c;
	edge(){}
	edge(int ff,int tt,int cc){
		f=ff;
		t=tt;
		c=cc;
	}
	bool operator<(const edge &e)const{
		return c<e.c;
	}
};

vector<edge> ed;
vector<P> G[301];
int dist[301];

int dijk(int s,int e){
	for(int i=0;i<n;i++){
		dist[i]=INF;
	}
	dist[s]=0;
	priority_queue<P,vector<P>,greater<P> > que;
	que.push(P(0,s));
	while(que.size()){
		P p=que.top();
		que.pop();
		if(dist[p.second]<p.first)continue;
		if(p.second==e)return p.first;
		for(int i=0;i<G[p.second].size();i++){
			P ep=G[p.second][i];
			if(dist[ep.first]>dist[p.second]+ep.second){
				dist[ep.first]=dist[p.second]+ep.second;
				que.push(P(dist[ep.first],ep.first));
			}
		}
	}
	return INF;
}

void dijk2(int s){
	for(int i=0;i<n;i++){
		dist[i]=INF;
	}
	dist[s]=0;
	priority_queue<P,vector<P>,greater<P> > que;
	que.push(P(0,s));
	while(que.size()){
		P p=que.top();
		que.pop();
		if(dist[p.second]<p.first)continue;
		for(int i=0;i<G[p.second].size();i++){
			P ep=G[p.second][i];
			if(dist[ep.first]>dist[p.second]+ep.second){
				dist[ep.first]=dist[p.second]+ep.second;
				que.push(P(dist[ep.first],ep.first));
			}
		}
	}
}

bool check(){
	for(int i=0;i<n;i++){
		dijk2(i);
		for(int j=0;j<n;j++){
			if(dist[j]!=re_dist[i][j])return false;
		}
	}
	return true;
}

