	for(int i=0;i<n;i++){
		for(int j=0;j<n;j++){
			scanf("%d",&re_dist[i][j]);
		}
	}
	for(int i=0;i<n;i++){
		if(re_dist[i][i]!=0){
			printf("-1\n");
			return 0;
		}
	}
	for(int i=0;i<n;i++){
		for(int j=i+1;j<n;j++){
			if(re_dist[i][j]!=re_dist[j][i]){
				printf("-1\n");
				return 0;
			}else{
				ed.push_back(edge(i,j,re_dist[i][j]));
			}
		}
	}
	sort(ed.begin(),ed.end());
	ll sum=0;
	for(int i=0;i<ed.size();i++){
		if(dijk(ed[i].f,ed[i].t)>ed[i].c){
			sum+=ed[i].c;
			G[ed[i].f].push_back(P(ed[i].t,ed[i].c));
			G[ed[i].t].push_back(P(ed[i].f,ed[i].c));
		}
	}
	if(!check()){
		printf("-1\n");
		return 0;
	}
