			U[n] = i;
			V[n] = j;
			n ++;
		}
	}
	for(i=0; i<n; i++)
		idx[i] = i;
	qsort(idx, n, sizeof(int), cmp);
	for(i=0; i<N; i++){
		for(j=0; j<N; j++){
			if(i==j)
				A2[i][j] = 0;
			else
				A2[i][j] = -1;
		}
	}
	res = 0;
	ok = 1;
	int u, v, l;
	for(k=0; k<n; k++){
		u = U[idx[k]];
		v = V[idx[k]];
		l = L[idx[k]];
		if(A2[u][v] != -1 && A2[u][v] < l){
			ok = 0;
			return ;
		}
		if(A2[u][v]!=-1 &&  A2[u][v]==l) 
			continue;
		A2[u][v] = l;
		A2[v][u] = l;
		res += l;
		for(i=0; i<N; i++){
			for(j=i+1; j<N; j++){
				if(A2[i][u]!=-1 && A2[v][j]!=-1){
					if(A2[i][j]==-1 || A2[i][u]+l+A2[v][j] < A2[i][j])
						A2[i][j] = A2[j][i] = A2[i][u]+l+A2[v][j];
				}
				if(A2[i][v]!=-1 && A2[u][j]!=-1){
					if(A2[i][j]==-1 || A2[i][v]+l+A2[u][j] < A2[i][j])
						A2[i][j] = A2[j][i] = A2[i][v]+l+A2[u][j];
				}
			}
		}
	}
}

