long long krustkal(vector<edge>graph_[], int n_)
{
	vector<pair<int, edge> >vec;
	for (int i = 0; i < n_; ++i)
	{
		for (int j = 0; j < graph_[i].size(); ++j)
		{
			vec.push_back({ i, graph_[i][j] });
		}
	}
	sort(vec.begin(), vec.end(), [](const pair<int, edge>& e1, const pair<int, edge>&e2)
	{
		return e1.second < e2.second;
	});
	union_find uf(n_);
	long long res = 0;
	for (int i = 0; i < vec.size(); ++i)
	{
		int a = vec[i].first;
		int b = vec[i].second.to;
		LL cost = vec[i].second.cost;
