int find_her(int x){
    if(x == parent[x])return x;
    return parent[x] = find_her(parent[x]);
}

void tmerge(int a,int b,long long c){
    int aa = a , bb = b;
    int d1 = aa , d2 = bb;
    a = find_her(a);
    b = find_her(b);
    if(sz[a] < sz[b]){
        swap(a , b);
        swap(aa , bb);
        swap(d1 , d2);
    }
    for(int i=0;i<(int)G[a].size();i++){
        for(int j=0;j<(int)G[b].size();j++){
            int gag1 = G[a][i];
            int gag2 = G[b][j];
            aa = d1;
            bb = d2;
            if(gag1 > gag2){
                swap(gag1 , gag2);
                swap(aa , bb);
            }
            mas[gag1][gag2] = min(mas[gag1][gag2] , mas[min(aa , gag1)][max(aa , gag1)] + c + mas[min(bb , gag2)][max(bb , gag2)]);
        }
    }
    if(a != b){
        sz[a] += sz[b];
        parent[b] = a;
        for(int i=0;i<(int)G[b].size();i++) G[a].push_back(G[b][i]);
        G[b].clear();
    }
}

