        for(int j=i+1;j<=n;j++){
            mas[i][j] = 1ll * inf * inf;
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            long long val;
            scanf("%lld",&val);
            if(i < j) g.push_back(make_pair(val , make_pair(i,j)));
        }
    }
    sort(g.begin() , g.end());
    for(int i=0;i<(int)g.size();i++){
        long long x = g[i].first;
        int a = g[i].second.first;
        int b = g[i].second.second;
        if(x > mas[a][b]){
            cout<<-1<<endl;
            return 0;
        }
        if(x == mas[a][b])continue;
        answ += x;
        tmerge(a , b , x);
    }
    cout<<answ<<endl;
    return 0;
}

