    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            scanf("%d", &A[i][j]);
            dists.push_back({A[i][j], {i, j}});
        }
    }

    sort(dists.begin(), dists.end());
    for (auto p : dists) {
        int dist = p.first;
        int a = p.second.first;
        int b = p.second.second;
        int d = calcDist(a, b);
        if (d == dist) {
            continue;
        } else if (d < dist) {
            printf("-1\n");
            return 0;
        } else {
            addEdge(a, b, dist);
        }
    }

    printf("%d\n", ans);

    return 0;
}

