ll solve() {
	int n = ri();

	vvi D(n, vi(n));

	ll sum = 0;
	rep(i, n) rep(j, n) D[i][j] = ri();
	out(D);
	vvi E = D;

	rep(i, n) rep(j, i + 1, n) sum += D[i][j];
	out(sum);

	rep(k, n) {
		rep(i, n) {
			rep(j, n) {
				amin(D[i][j], D[i][k] + D[k][j]);
			}
		}
	}

	if (D != E) return -1;

	rep(i, n) {
		rep(j, i+1, n) {
			bool need = 1;
			rep(k, n) if (k != i && k != j) {
				if (D[i][j] == D[i][k] + D[k][j]) {
					need = 0;
				}
			}
			if (!need) {
				sum -= D[i][j];
			}
		}
	}

	return sum;
}

int main() {
	cout << solve() << endl;
	return 0;
}

