const int MAX_V=300+1;
LL A[MAX_V][MAX_V];
int V;
// 18:00-18:45 pause
// 20:40-21:06 TLE
// 21:20 give up
const LL Inf=1e17;

vector<pair<LL,int>> G[MAX_V];
LL D[MAX_V];
LL dist(int s, int d) {
  REPE(i,V) D[i]=Inf;
  set<pair<LL,int>> Q;
  D[s]=0; Q.emplace(0,s);
  while(SZ(Q)) {
    LL d; int u;
    auto it=Q.begin();
    tie(d,u)=*it; Q.erase(it);
    FORR(p,G[u]) {
      LL w=p.first; int v=p.second;
      LL d2=d+w;
      if(d2<D[v]) {
        auto it2=Q.find({D[v],v});
        if(it2!=Q.end()) Q.erase(it2);
        Q.emplace(d2,v);
        D[v]=d2;
      }
    }
  }
  return D[d];
}

// 4 secs for test case #11
LL solve_TLE(vector<tuple<LL,int,int>> S) {
  LL res=0;
  FORR(t,S) {
    LL w; int u,v;
    tie(w,u,v)=t;
    LL d=dist(u,v);
    if(d<w) return -1;
    if(d==w) continue;

    G[u].emplace_back(w,v);
    G[v].emplace_back(w,u);
    res+=w;
  }
  return res;
}

LL solve() {
  REP(k,V)REP(i,V)REP(j,V) if(A[i][k]+A[k][j]<A[i][j]) return -1;
  LL res=0;
  REP(j,V)REP(i,j) res+=A[i][j];
  REP(j,V)REP(i,j) {
    bool ok=true;
    REP(k,V) if(k!=i&&k!=j&&A[i][k]+A[k][j]==A[i][j]) ok=false;
    if(!ok) res-=A[i][j];
  }

//  REP(j,V)REP(i,j) dump3(i,j,A[i][j]);
  return res;
}

