            }
        }
    }
    // 簡易チェック
    REP(i, N) {
        REP(j, N) {
            if(A[i][j] != A[i][j]) {
                printf("-1\n");
                return 0;
            }
        }
    }
    SORT(load);
    ll ans = 0;
    for(pair< ll, pair<ll, ll>> l_tmp : load) {
        ll dist = l_tmp.first;
        ll from = l_tmp.second.first;
        ll to = l_tmp.second.second;
        if(clear[from][to] != 0) {
            //ans += dist;
            continue;
        }
        //printf("from: %lld to: %lld d[to]: %lld dist: %lld\n",
        //        from, to, d[to], dist);
        dijkstra(from);
        if(d[to] > dist) {
            edge tmp;
            tmp.to = to;
            tmp.cost = dist;
            G[from].push_back(tmp);
            // G の更新
            //for(auto it = G[from].begin(); it != G[from].end(); ++it) {
