void WarshallFloyd(int size){
    //init
    for(int i = 0; i < size ; i++){
        for(int j = 0; j < size; j++){
            d[i][j] = A[i][j];
        }
    }
    for(int k = 0; k < size; k++){
        for(int i = 0; i < size ; i++){
            for(int j = 0; j < size; j++){
                d[i][j] = min(d[i][j], d[i][k]+d[k][j]);
            }
        }
    }
