            ans += d;

            for(int i : rep(0, n)) {
                for(int j : rep(0, n)) {
                    dist[j][i] = dist[i][j] = min({dist[i][j], dist[i][u] + dist[u][v] + dist[v][j], dist[i][v] + dist[v][u] + dist[u][j]});
                }
            }
