#define ll long long
#define Inf 100000000000ll
using namespace std;


vector<pair<int,ll> > roads[333];

ll best_dist[333];

ll djikstra(int u,int v,int N) {

    for(int i=1;i<=N;i++)
        best_dist[i]=-1;

    set<pair<ll,int> > dists;
    dists.insert({0,u});

    while(!dists.empty()) {
        set<pair<ll,int> >::iterator it = dists.begin();
        int curru = it->second;
        ll currd = it->first;
        dists.erase(it);
        if (curru == v)
            return currd;
        if (best_dist[curru]!=-1)
            continue;
        best_dist[curru] = currd;


        for(pair<int,ll> w_dist : roads[curru]) {
            int w = w_dist.first;
            if (best_dist[w]!=-1)
                continue;
            ll nextd = w_dist.second + currd;
            dists.insert({nextd, w});
        }
    }

    return Inf;
}

ll dist_brute[333][333];

ll djikstra_brute(int u,int v,int N) {

    for(int i=1;i<=N;i++)
        for(int j=1;j<=N;j++)
            dist_brute[i][j]=Inf;



    for(int i=1;i<=N;i++)
        for(pair<int,ll> v_dist : roads[i]) {

            int u=i;
            int v=v_dist.first;
            dist_brute[u][v]=v_dist.second;
        }


    for(int k=1;k<=N;k++)
        for(int i=1;i<=N;i++)
            for(int j=1;j<=N;j++)
                dist_brute[i][j]=min(dist_brute[i][k]+dist_brute[k][j],dist_brute[i][j]);
    return dist_brute[u][v];

}

