typedef long long int lli;
const lli inf = 1e18;

int main(){
    int n;
    cin >> n;
    vector<vector<lli> > a(n, vector<lli>(n));
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            cin >> a[i][j];
        }
    }

    vector<pair<lli, pair<int,int> > > dist;
    for(int i=0; i<n; i++){
        for(int j=i+1; j<n; j++){
            dist.push_back(make_pair(a[i][j], make_pair(i, j)));
        }
    }
    sort(dist.begin(), dist.end());

    lli ans = 0;
    vector<vector<lli> > adj(n, vector<lli>(n, inf));
    for(int i=0; i<n; i++) adj[i][i]=0;
    for(int i=0; i<(int)dist.size(); i++){
        int to=dist[i].second.first, from=dist[i].second.second;
        if(adj[from][to] > dist[i].first){
            adj[from][to] = adj[to][from] = dist[i].first;
            ans += dist[i].first;
        }else if(adj[from][to] < dist[i].first){
            ans = -1;
            break;
        }
        for(int j=0; j<n; j++){
            for(int k=j+1; k<n; k++){
                adj[j][k] = adj[k][j] = min(adj[j][k],
                    min(adj[j][from]+adj[to][k], adj[j][to]+adj[from][k])+dist[i].first);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

