void floyd(i64 g[305][305])
{
  for (int k = 0; k < N; ++k) {
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        chmin(g[i][j], g[i][k] + g[k][j]);
      }
    }
  }
  return;
}

