void warshall_floyd() {
    REP(i, n) {
        REP(j, n) {
            REP(k, n) {
                if (dist[j][i] == inf || dist[i][k] == inf) continue;
                // min(inf, inf + (N<0)) should be inf but not
                if (dist[j][k] >= dist[j][i] + dist[i][k]) {
                    dist[j][k] = dist[j][i] + dist[i][k];
                    if (j != i && i != k) flag[j][k] = 1;
                }
            }
        }
    }
}

