void solve(long long N, std::vector<std::vector<long long>> A) {
  ll res = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < i; ++j) {
      const int d1 = A[i][j];
      bool ok = true;
      for (int k = 0; k < N; ++k) {
        if (i == k || j == k) continue;
        const int d2 = A[i][k] + A[k][j];
        if (d1 > d2) {
          cout << -1 << endl;
          return;
        }
        if (d1 == d2) ok = false;
      }
      if (ok) res += d1;
    }
  }
  cout << res << endl;
}

