void dijkstra(ll K,ll s){
    priority_queue<Edge,vector<Edge>,greater<Edge>> Q;
    fill(res.begin(),res.end(),INF);
    res[K]=0;
    Q.push(Edge(0,K));
    while(!Q.empty()){
        Edge u = Q.top();Q.pop();
        ll v = u.second;
        if(res[v]<u.first) continue;
        for(int i=0;i<N;i++){
            if(v==K && i==s) continue;
            if(i==v) continue;
            if(res[i] < res[v]+A[v][i]) continue;
            else{
                res[i]=res[v]+A[v][i];
                Q.push(Edge(res[i],i));
            }
        }
    }
}

