int timer;
int was[N];

struct edge {
  int v, u, cost;
  edge(int v, int u, int cost) : v(v), u(u), cost(cost) {}
  bool operator < (const edge &x) {
    return cost < x.cost;
  }
};

bool bad[N][N];

bool go(int st, bool type = 0) {
  rep(i, 1, n) d[i] = linf;
  d[st] = 0;
  ++timer;
  rep(i, 1, n) {
    int v = -1;
    rep(j, 1, n) {
      if (was[j] != timer) {
        if (v == -1) v = j;
        else if (d[j] < d[v]) v = j;
      }
    }
    if (v == -1 || d[v] == linf) break;
    was[v] = timer;
    //if (type) {
    if (d[v] != a[st][v]) return 0;
//    }
    for (auto to : g[v]) {
      if (!bad[v][to.f] && d[to.f] > d[v] + to.s) {
        d[to.f] = d[v] + to.s;
      }
    }
  }
  return 1;
}
bool check(int v, int u) {
  bad[v][u] = bad[u][v] = 1;
  rep(i, 1, n) {
    if (!go(i)) {
      bad[v][u] = bad[u][v] = 0;
      return 0;
    }
  }
  return 1;
}
void solve() {
  n = get_int();
  rep(i, 1, n) {
    rep(j, 1, n) {
      a[i][j] = get_int();
      if (i != j) g[i].pb({j, a[i][j]});
    }
