  ll ans = 0;
  vector <edge> kr;
  rep(i, 1, n) {
    rep(j, 1, n)
      if (i < j) {
        kr.pb(edge(i, j, a[i][j]));
        ans += a[i][j];
      }
  }
  sort(all(kr));
  reverse(all(kr));
  for (auto it : kr)
    if (check(it.v, it.u)) {
      ans -= it.cost;
    }
  cout << ans;
}
