#include<bits/stdc++.h>

using namespace std;
using ll = long long;
using P = pair<int,int>;
const ll mod = 1000000007;
const ll INF = 1e15;


void dijkstra(ll N,ll start,const vector<vector<pair<int,ll>>>& Hen, vector<vector<ll>>& DS){
    vector<ll> dist(N,INF);
    using T = pair<ll,ll>;
    priority_queue<T, vector<T>, greater<T>> que;
    que.push({0,start}); //dist(start) = 0;

    while(que.size()){
        auto cur = que.top(); //見る地点
        que.pop();
        for(auto i : Hen[cur.second]){ //curから見れる全ての辺について
            if(dist[i.first] > cur.first + i.second){
                dist[i.first] = cur.first + i.second;
                que.push({dist[i.first],i.first});
            }
        }
    }


    for(int i = 0; i < N; i++){
        DS[i][start] = min(dist[i], DS[i][start]);
        DS[start][i] = min(dist[i], DS[start][i]);
    }
}




int main()
{
    int n;
    cin >> n;
    vector<vector<ll>> cost(n, vector<ll>(n));
    priority_queue<pair<ll, pair<ll,ll>>> que; 
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++) {
            cin >> cost[i][j];
            if(i > j){
                que.push({cost[i][j], {i, j}});
            }
        }
    }
    ll ans = 0;

    //最小全域木を構成する
    vector<vector<pair<int,ll>>> hen(n);
    vector<vector<ll>> dist(n, vector<ll>(n, INF));
    vector<bool> seen(n);

    while (que.size()) {
        auto cur = que.top();
        que.pop();
        if(seen[cur.second.first] || seen[cur.second.second])continue;

        dist[cur.second.first][cur.second.second] = cur.first;
        dist[cur.second.second][cur.second.first] = cur.first;
        seen[cur.second.second] = true;
        seen[cur.second.first] = true;
    }


    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            if(cost[i][j] == dist[i][j])continue;

            if(cost[i][j] > dist[i][j]){
                cout << -1 << endl;
                return 0;
            }

            hen[j].push_back({i, cost[i][j]});
            hen[i].push_back({j, cost[i][j]});
            dijkstra(n, i, hen, dist);
            dijkstra(n, j, hen, dist);
            ans += cost[i][j];
        }
    }
    cout << ans << endl;
}

