#include <bits/stdc++.h>
using namespace std;

#define loop(i,n) for(int i = 0; i < n; i++)
#define pii pair<int, int>
typedef long long LL;

const int INF = 1e9 + 7;
const int mod = 1e9 + 7;
const int MX = 1e3 + 5;

int n, m, vis[MX];
LL mn_dist[MX];
pair<int, pii> edges[MX * MX];
vector<pair<int, int> > g[305];

LL dfs(int cur, int target) {
    if (mn_dist[cur] != -1) return mn_dist[cur];
    if (cur == target) return 0;
    if (vis[cur]) return INF;
    vis[cur] = 1;
    LL res = INF;
    for (pair<int, int> p: g[cur]) {
        LL other = dfs(p.first, target);
        if (other < INF) {
            if (other + p.second < res) {
                res = other + p.second;
            }
        }
    }
    return mn_dist[cur] = res;
}

int main()
{
#ifdef DEBUG
    freopen("in.txt", "r", stdin);
#endif
    ios_base::sync_with_stdio(false);
    cin >> n;
    int cntr = 0;
    loop(i, n) {
        loop(j, n) {
            int l;
            cin >> l;
            if (i >= j) continue;
            edges[cntr] = {l, {i, j}};
            cntr++;
        }
    }
    sort(edges, edges + cntr);
    LL ans = 0;
    loop(i, cntr) {
        int length = edges[i].first;
        int u = edges[i].second.first;
        int v = edges[i].second.second;
        memset(vis, 0, sizeof(vis));
        memset(mn_dist, -1, sizeof(mn_dist));
        LL orig_length = dfs(u, v);
        if (orig_length == INF || length < orig_length) {
            g[u].push_back({v, length});
            g[v].push_back({u, length});
            ans += length;
        }
        else if (length > orig_length) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;
    return 0;
}

