    for (int j = 1; j <= n; ++j)
      cin >> g[i][j];

  auto dp = g;
  for (int k = 1; k <= n; ++k) {
    for (int i = 1; i <= n; ++i) {
      if(i == k) continue;
      for (int j = 1; j <= n; ++j) {
        if(j == i || j == k) continue;
        if(dp[i][k] && dp[k][j])
          dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
      }
    }
  }

  if(not (g == dp))
    return cout << -1, 0;

  ll cost = accumulate(all(dp), 0ll, [] (ll x, auto const& a) {
    return x + accumulate(all(a), 0ll);
  });


  cost >>= 1;
  for (int i = 1; i <= n; ++i) {
    for (int j = i+1; j <= n; ++j) {
      ll sum = 0;
      for (int k = 1; k <= n; ++k) {
        if(i == k || k == j)
          continue;
        if(g[i][k] + g[k][j] == g[i][j] || g[j][k] + g[k][i] == g[i][j])
          cost -= g[i][j];
      }
    }
  }

  cout << cost;
}

