int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i32>();
    auto as = V<V<i64>>(N, V<i64>(N, 0));

    auto cmp = [&](auto n1, auto n2) {
        return n1.second > n2.second;
    };

    using P = pair<pair<i32, i32>, i64>;
    priority_queue<P, vector<P>, decltype(cmp)> edges_queue(cmp);
    REP (i, N) {
        REP (j, N) {
            as[i][j] = read<i64>();
            if (i != j) {
                edges_queue.push(make_pair(make_pair(i, j), as[i][j]));
            }
        }
    }

    i64 total = 0;
    auto distance = V<V<i64>>(N, V<i64>(N, 1e10));
    REP (i, N) {
        distance[i][i] = 0;
    }
    while (!edges_queue.empty()) {
        auto edge = edges_queue.top();
        edges_queue.pop();
        auto n1 = edge.first.first;
        auto n2 = edge.first.second;
        auto d = edge.second;

        if (distance[n1][n2] == d) {
            // 何もしない
        } else if (distance[n1][n2] > d) {
            distance[n1][n2] = d;
            distance[n2][n1] = d;
            total += d;

            // Update distance
            REP (i, N) {
                REP (j, N) {
                    distance[i][j] = min(
                            distance[i][j],
                            min(distance[i][n1] + d + distance[n2][j], distance[i][n2] + d + distance[n1][j])
                    );
                }
            }
        } else {
            // distance[n1][n2] < d => 矛盾
            total = -1;
            break;
        }
    }

    cout << total << endl;

    return 0;
}

