#define ll long long
#define Inf 1000000001
using namespace std;


vector<pair<int,int> > roads[333];

int best_dist[333];

bool done[333];
bool dfs(int u,int v) {
    if (u == v)
        return true;
    if (done[u])
        return false;
    done[u]=true;
    for(pair<int,int> w_dist : roads[u]) {
        if (dfs(w_dist.first,v))
            return true;
    }
    return false;
}

bool IsConn(int u,int v,int N) {

    for(int i=1;i<=N;i++)
        done[i]=false;
    return dfs(u,v);

}

int djikstra(int u,int v,int maxD,int N) {

    for(int i=1;i<=N;i++) {
        best_dist[i]=-1;
        done[i]=false;
    }


    set<pair<int,int> > dists;
    dists.insert({0,u});

    while(!dists.empty()) {
        set<pair<int,int> >::iterator it = dists.begin();
        int curru = it->second;
        int currd = it->first;
        if (currd > maxD)
            return maxD+1;
        dists.erase(it);
        if (curru == v)
            return currd;
        if (done[curru])
            continue;
        done[curru] = true;


        for(pair<int,int> w_dist : roads[curru]) {
            int w = w_dist.first;
            int nextd = w_dist.second + currd;
            if (best_dist[w]==-1 || best_dist[w] > nextd) {
                dists.erase({best_dist[w], w});
                best_dist[w]=nextd;
                dists.insert({best_dist[w], w});
            }
        }
    }

    return Inf;
}



int A[333][333];

ll Solve(int N) {

    for(int i=1;i<=N;i++) {
        roads[i].clear();
    }

    vector<pair<ll,pair<int,int> > > dist_sorted;
    for(int i=1;i<=N;i++)
        for(int j=i+1;j<=N;j++)
            dist_sorted.push_back({A[i][j],{i,j}});

    sort(dist_sorted.begin(),dist_sorted.end());
    ll ans = 0;
    for(int i=0;i<dist_sorted.size();i++) {

        int u=dist_sorted[i].second.first;
        int v=dist_sorted[i].second.second;

        int reqd_dist = dist_sorted[i].first;
        int curr_dist = (IsConn(u,v,N) ? djikstra(u,v,reqd_dist,N) : Inf);

        if (curr_dist < reqd_dist) {
            return -1;
        } else if (curr_dist > reqd_dist) {
            roads[u].push_back({v,reqd_dist});
            roads[v].push_back({u,reqd_dist});
            ans += reqd_dist;
        }

    }

    return ans;



}

int main() {
    int N;
    cin>>N;
    for(int i=1;i<=N;i++)
        for(int j=1;j<=N;j++)
            cin>>A[i][j];

    cout << Solve(N) << endl;

}

#include <cstdio>
