using namespace std;

typedef long long int lli;
typedef pair<int, int> pii;
typedef pair<int, pii> pip;
const lli INF = 1e12;
int N;
int A[300][300];
lli dist[300][300];
int parent[301];	//-1로 초기화시켜둠

lli min(lli a, lli b) {
	return a < b ? a : b;
}

int ufFind(int u)
{
	if (parent[u] < 0)
		return u;
	return parent[u] = ufFind(parent[u]);
}

bool ufUnion(int u, int v)
{
	u = ufFind(u);
	v = ufFind(v);
	if (u == v)
		return false;
	parent[u] = v;
	return true;
}


int main()
{
	priority_queue<pip> pq;
	long long int ans = 0;
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			scanf("%d", &A[i][j]);
			if (j < i) {
				pq.push(make_pair(-A[i][j], make_pair(i, j)));
				dist[i][j] = dist[j][i] = INF;
			}
		}
		parent[i] = -1;
	}
	while (!pq.empty()) {
		int length = -pq.top().first;
		int i = pq.top().second.first;
		int j = pq.top().second.second;
		pq.pop();
		if (ufUnion(i, j) || dist[i][j] > length) {
			dist[i][j] = dist[j][i] = (lli)length;
			ans += length;
			int group = ufFind(i);
			for (int k = 0; k < N; k++) {
				if (ufFind(k) != group)
					continue;
				if (k == i || k == j)
					continue;
				dist[i][k] = dist[k][i] = min(dist[i][k], dist[i][j] + dist[j][k]);
				dist[j][k] = dist[k][j] = min(dist[j][k], dist[j][i] + dist[i][k]);
				for (int t = 0; t < N; t++) {
					if (ufFind(t) != group)
						continue;
					if (t == i || t == j || t == k)
						continue;
					dist[k][t] = dist[t][k] = min(dist[t][k], min(dist[t][j] + dist[j][i] + dist[i][k]
							, dist[t][i] + dist[i][j] + dist[j][k]));
				}
			}
		}
		else if (dist[i][j] < length) {
			printf("-1\n");
			return 0;
		}
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			if (A[i][j] != dist[i][j]) {
				printf("-1\n");
				return 0;
			}
		}
	}
	printf("%lld\n", ans);
}

