    for(int& x : vec)
        cin >> x;

    for(int k = 0; k < n; ++k)
    for(int i = 0; i < n; ++i)
    for(int j = 0; j < n; ++j)
        if (a[i][k] + a[k][j] < a[i][j])
            FINAL_OUT(-1);

    vector<vector<int> > g(n, vector<int>(n, 1000000009));
    for(int i = 0; i < n; ++i)
        g[i][i] = 0;
    long long ans = 0;


    vector<tuple<int,int,int> > edges;
    for(int i = 0; i < n; ++i)
    for(int j = 0; j < n; ++j)
        edges.emplace_back(a[i][j], i,j);
