    int cnt = n;
    for(int i = 0; i < n; ++i)
        par[i] = i;

    for(int i = 0;cnt > 1; ++i)
    {
        int w,x,y;
        tie(w,x,y) = edges[i];
        if (get_par(x) != get_par(y))
        {
            g[x][y] = g[y][x] = w;
            uni(x,y);
            --cnt;
            ans += w;
        }
