    for(int k = 0; k < n; ++k)
    for(int i = 0; i < n; ++i)
    for(int j = 0; j < n; ++j)
        if (g[i][k] + g[k][j] < g[i][j])
            g[i][j] = g[i][k] + g[k][j];

    for(const auto& e : edges)
    {
        int w,x,y;
        tie(w,x,y) = e;
        if (g[x][y] != w)
        {
            g[x][y] = g[y][x] = w;
