typedef long long LL;
int xd[MaxN];
int find(int a)
{
	if(xd[a]<0)
		return a;
	else
		return xd[a]=find(xd[a]);
} 
 int merge(int a,int b)
 {
 	if(-xd[a]<-xd[b])
 	{
 		xd[b]+=xd[a];
 		xd[a]=b;
 		return -xd[b];
	 }
	 else
	{
		xd[a]+=xd[b];
		xd[b]=a;
		return -xd[a];
	}
 }

LL roads[MaxN][MaxN]; 
LL next_roads[MaxN][MaxN];
LL min(LL a,LL b)
{
	return a<b ? a:b;
}
int main()
{
	int N;
