		{
			int k;
			for(k=i+1;k<=N;k++)
			{
				if(next_roads[i][k]!=0)
				{
					int roota=find(i);
					int rootb=find(k);
					if(roota!=rootb)
					{
						sun=merge(roota,rootb);
						if(sun==N)
							break;
					} 
				}
			}
			if(k<=N)
				break;
		}
		if(sun!=N)
			printf("-1\n");
		else
		{
			LL total=0;
			for(int i=1;i<N;i++)
