#define FOR(i,l,r) for(int (i) = (l); (i) <= (r); (i)++)
using namespace std;
const long long maxn = 305;
const long long oo = 3000000000000ll;
long long n;
long long aim[maxn][maxn];
long long dis[maxn][maxn];
struct Node{
	long long a,b,d;
	Node(long long a,long long b,long long d):a(a),b(b),d(d){}
	friend bool operator < (const Node &x, const Node &y){
		return x.d < y.d;
	}
};
vector <Node> vec;
inline void update(long long a,long long b){
	FOR(i,1,n) dis[i][b] = min(dis[i][b],dis[i][a]+dis[a][b]);
	FOR(i,1,n) dis[a][i] = min(dis[a][i],dis[a][b]+dis[b][i]);
	FOR(i,1,n) dis[i][b] = dis[b][i] = min(dis[i][b],dis[b][i]);
	FOR(i,1,n) dis[a][i] = dis[i][a] = min(dis[i][a],dis[a][i]);
}
inline bool check(){
	FOR(k,1,n) FOR(i,1,n) FOR(j,1,n) dis[i][j] = min(dis[i][j],dis[i][k]+dis[k][j]);
	FOR(i,1,n) FOR(j,1,n) if(dis[i][j] != aim[i][j]) return 0;
	return 1;
}
void work(){
	long long ans = 0;
	FOR(i,1,n) FOR(j,1,n) vec.push_back(Node(i,j,aim[i][j]));
	sort(vec.begin(),vec.end());
	for(long long i = 0; i < vec.size(); i++){
		if(dis[vec[i].a][vec[i].b] < vec[i].d) {cout << "-1" << endl; return;}
		if(dis[vec[i].a][vec[i].b] > vec[i].d) {
			dis[vec[i].a][vec[i].b] = vec[i].d;
			update(vec[i].a,vec[i].b);
			ans += vec[i].d;
		}
	}
	if(check()) cout << ans << endl;
	else cout << "-1" << endl;
}
int main(){
#ifdef __APPLE__
	freopen("main.in","r",stdin);
#endif
	cin >> n;
	FOR(i,1,n)FOR(j,1,n) cin >> aim[i][j];
	FOR(i,1,n)FOR(j,1,n) dis[i][j] = oo;
	work();
	return 0;
}

