constexpr int kMaxN = 300 + 3;

int main() {
    int n;
    scanf("%d", &n);

    static int distance[kMaxN][kMaxN];

    for (int i = 0; i < n; i += 1) {
        for (int j = 0; j < n; j += 1) {
            scanf("%d", distance[i] + j);
        }
    }

    static bool necessary[kMaxN][kMaxN];
    memset(necessary, 1, sizeof(necessary));

    bool bad = false;
    for (int u = 0; u < n; u += 1) {
        for (int v = 0; v < u; v += 1) {
            int d = distance[u][v];
            for (int w = 0; w < n; w += 1) {
                if (w == u || w == v) {
                    continue;
                }
                int add = distance[u][w] + distance[w][v];
                if (d == add) {
                    necessary[u][v] = false;
                } else if (d > add) {
                    bad = true;
                }
            }
        }
    }

    if (bad) {
        std::cout << -1 << std::endl;
    } else {
        int64_t total = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (not necessary[i][j]) {
                    continue;
                }
                total += distance[i][j];
            }
        }
        std::cout << total << std::endl;
    }
    return 0;
}

