                if (D[i][k] + D[k][j] == D[i][j]) {
                    D[i][j] = INF;
                    break;
                }
            }
        }
    }

    long long int ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (D[i][j] == INF) continue;
            ans += D[i][j];
        }
    }

    cout << ans << endl;

    return 0;
}

