long long validate(int from, int to, int n, long long min) {
	bool flg = false;
	for (int i = 0; i < n; i++) {
		if (i == from || i == to) {
			continue;
		}
		if (dist[from][i] + dist[i][to] < min) {
			return -1;
		}
		else if(dist[from][i] + dist[i][to] == min){
			flg = true;
		}
	}
	return flg ? min : 0;
}

