class UnionFind {
public:
	vector<int> par, rank, _size;

	UnionFind(int n) {
		par = vector<int>(n);
		rank = vector<int>(n);
		_size = vector<int>(n);
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
			_size[i] = 1;
		}
	}

	// 木の根を求める
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}

	// xとyの属する集合を併合
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y)return;

		if (rank[x] < rank[y]) {
			par[x] = y;
			_size[y] += _size[x];
		}
		else {
			par[y] = x;
			_size[x] += _size[y];
			if (rank[x] == rank[y])rank[x]++;
		}
	}

	// xとyが同じ集合に属するか否か
	bool same(int x, int y) {
		return find(x) == find(y);
	}

	int size(int x) {
		return _size[find(x)];
	}
};

ll Dijkstra(Graph graph, int start, vll &cost, int V, int target, ll upper) {
	pqlP Q;

	fill(cost.begin(), cost.end(), INFL);
	cost[start] = 0;

	Q.push(mp(0, start));	// (cost, index)

	while (!Q.empty()) {
		P pos = Q.top();
		Q.pop();
		if (pos.second == target) {
			//cout << "test" << pos.first << endl;
			return pos.first;
		}
		if (pos.first > upper) {
			return INFL;
		}
		rep(i, graph[pos.second].size()) {
			if (cost[graph[pos.second][i].to] > cost[pos.second] + graph[pos.second][i].cost) {
				cost[graph[pos.second][i].to] = cost[pos.second] + graph[pos.second][i].cost;
				Q.push(mp(cost[graph[pos.second][i].to], graph[pos.second][i].to));
			}
		}
	}
	return cost[target];
}

bool WarshallFloyd(vvll &graph, int V) {
	rep(k, V)rep(i, V)rep(j, V) {
		// i->(k)->j
		if (graph[i][k] != INFL && graph[k][j] != INFL) {
			graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j]);
		}
	}
	rep(i, V) {
		if (graph[i][i] < 0) return false;
	}
	return true;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	Edges edges;
	G = Graph(N);
	A = vvi(N, vi(N));
	UnionFind uf(N);

	rep(i, N) {
		rep(j, N) {
			cin >> A[i][j];
			if (i < j) {
				edges.push_back(Edge{ i,j,A[i][j] });
			}
		}
	}
	sort(all(edges));

	vvll adj(N, vll(N, INFL));
	rep(i, N)adj[i][i] = 0;
	ll ans = 0;

	for (auto edge : edges) {
		vll cost(N, INFL);
		ll dist = Dijkstra(G, edge.from, cost, N, edge.to, edge.cost);
		if (!uf.same(edge.from, edge.to) || dist > edge.cost) {
			G[edge.from].push_back(edge);
			G[edge.to].push_back(Edge{ edge.to, edge.from, edge.cost });
			adj[edge.from][edge.to] = adj[edge.to][edge.from] = edge.cost;
			ans += edge.cost;
			uf.unite(edge.from, edge.to);
		}
		else if (dist < edge.cost) {
			cout << -1 << endl;
			return 0;
		}
	}

	WarshallFloyd(adj, N);

	rep(i, N) {
		rep(j, N) {
			if (adj[i][j] != A[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

