vector<pair<int,int> > roads[333];


bool done[333];
bool dfs(int u,int v) {
    if (u == v)
        return true;
    if (done[u])
        return false;
    done[u]=true;
    for(pair<int,int> w_dist : roads[u]) {
        if (dfs(w_dist.first,v))
            return true;
    }
    return false;
}

bool IsConn(int u,int v,int N) {

    for(int i=1;i<=N;i++)
        done[i]=false;
    return dfs(u,v);

}


int djikstra(int u,int v,int maxD,int N) {


    set<pair<int,int> > dists;
    bitset<333> dones;
    unordered_map<int,int> best_dists;
    dones.reset();
    dists.insert({0,u});

    int iters=0;
    while(!dists.empty()) {
        set<pair<int,int> >::iterator it = dists.begin();
        int curru = it->second;
        int currd = it->first;
        if (currd > maxD)
            return maxD+1;
        dists.erase(it);
        if (curru == v)
            return currd;
        if (dones[curru])
            continue;
        dones.set(curru);

        iters++;
        for(pair<int,ll> w_dist : roads[curru]) {
            int w = w_dist.first;
            ll nextd = w_dist.second + currd;

            if (nextd > maxD)
                continue;

            if (best_dists.find(w) == best_dists.end() || best_dists[w] > nextd) {
                dists.erase({best_dists[w],w});
                best_dists[w]=nextd;
                dists.insert({nextd, w});
            }

        }
    }
    return Inf;
}



