vector<pair<LL,int>> G[MAX_V];
LL D[MAX_V];
LL dist(int s, int d) {
  REPE(i,V) D[i]=Inf;
  set<pair<LL,int>> Q;
  D[s]=0; Q.emplace(0,s);
  while(SZ(Q)) {
    LL d; int u;
    auto it=Q.begin();
    tie(d,u)=*it; Q.erase(it);
    FORR(p,G[u]) {
      LL w=p.first; int v=p.second;
      LL d2=d+w;
      if(d2<D[v]) {
        auto it2=Q.find({D[v],v});
        if(it2!=Q.end()) Q.erase(it2);
        Q.emplace(d2,v);
        D[v]=d2;
      }
    }
  }
  return D[d];
}

