//------------------------------------------------------

class UnionFind {
public:
    vector<int> par, sizes;

    UnionFind(int n) : par(n), sizes(n, 1) {
        rep(i, n) par[i] = i;
    }

    int root(int x) {
        if (x == par[x]) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sizes[x] < sizes[y]) swap(x, y);
        par[y] = x;
        sizes[x] += sizes[y];
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sizes[root(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    ll a[n][n];
    rep(i, n) rep(j, n) cin >> a[i][j];

    smaller_queue<pair<ll, pll> > que;
    rep(i, n) REP(j, i + 1, n) que.push(MP(a[i][j], MP(i, j)));
    ll ans = 0;
    ll d[n][n];
    rep(i, n) rep(j, n) d[i][j] = LINF;
    UnionFind uf(301);
    while (!que.empty()) {
        ll now_dist = que.top().first;
        pll p = que.top().second;
        ll From = p.first, To = p.second;
        if (d[From][To] == LINF || now_dist < d[From][To]) {
            ans += now_dist;
            d[From][To] = now_dist;
            d[To][From] = now_dist;
            uf.unite(From, To);

            rep(i, n) {
                if (uf.same(From, i)) {
                    d[To][i] = min(d[To][i], d[From][i] + now_dist);
                    d[i][To] = min(d[i][To], d[From][i] + now_dist);
                    d[From][i] = min(d[From][i], d[To][i] + now_dist);
                    d[i][From] = min(d[i][From], d[To][i] + now_dist);
                }
            }
        }
        que.pop();
    }

    bool valid = true;
    rep(i, n) REP(j, i + 1, n) if (a[i][j] != d[i][j]) valid = false;
    cout << (valid ? ans : -1) << endl;
    return 0;
}

