void f(int u,int v){
	if( gra[u][v] >= 0 ) return;

	bool flag = false;
	for(int k=0;k<N;++k){
		if( k == u || k == v ) continue;
		if( dist[u][k]+dist[k][v] == dist[u][v] ){
			flag = true;
			f(u,k);
			f(k,v);
		}
	}
	if( flag == false ){
		//中継で一致するものがないなら(u,v)辺がある
		gra[u][v] = dist[u][v];
		gra[v][u] = dist[v][u];
	}
}
void solve(){
	cin >> N;

	dist = vector< vector<LL> >(N,vector<LL>(N));
	LL temp;
	for(int i=0;i<N;++i){
		for(int j=0;j<N;++j){
			cin >> temp;
			dist[i][j] = temp;
		}
	}
	for(int k=0;k<N;++k){
		for(int i=0;i<N;++i){
			for(int j=0;j<N;++j){
				if( dist[i][k]+dist[k][j] < dist[i][j] ){
					cout << -1 << endl;
					//最短ではない
					return;
				}
			}
		}
	}

	gra = vector< vector<LL> >(N,vector<LL>(N,-1));

	for(int i=0;i<N;++i){
		for(int j=i;j<N;++j){
			if( i==j ){
				gra[i][j] = 0;
				continue;
			}
			bool flag = false;
			for(int k=0;k<N;++k){
				if( i==k || j==k) continue;
				if( dist[i][k]+dist[k][j] == dist[i][j] ){
					//中継の最短がある。
					flag = true;
					break;
				}
			}
			if( flag == false ){
				//(i,j)が最短で分割できない
				gra[i][j] = dist[i][j];
				gra[j][i] = dist[j][i];
			}
		}
	}

	LL ans = 0;
	for(int i=0;i<N;++i){
		for(int j=i;j<N;++j){
			LL res = gra[i][j];
			if( res > 0 ){
				ans += res;
			}
		}
	}
	cout << ans << endl;
}

