public:
	vector<int> Parent;
	vector<int> Rank;
	UnionFind(int n){
		++n;
		Parent.resize(n, 0);
		Rank.resize(n, 0);
		for(int i=0; i<n; ++i)
			Parent[i] = i;
	}

	int find(int x){
		if(Parent[x] == x) return x;
		return Parent[x] = find(Parent[x]);
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;
		if(Rank[x] < Rank[y]) Parent[x] = y;
		else{
			Parent[y] = x;
			if(Rank[x] == Rank[y]) ++Rank[x];
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};
class Edge{
public:
	long long cost;
	int from, to;
	Edge(long long c, int f, int t){
		cost = c;
		from = f;
		to = t;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
bool operator < (const Edge &e, const Edge &f){
	return e.cost != f.cost ? e.cost > f.cost : e.from != f.from ? e.from < f.from : e.to < f.to;
}
void dijkstra(int s, const Graph &g, vector<long long> &dist){
	int V = g.size();
	dist = vector<long long>(V, INF);
	dist[s] = 0;
	priority_queue<Edge> q;
	q.push(Edge(0, s, s));
	while(!q.empty()){
		Edge e = q.top();
		q.pop();
		if(dist[e.to] < e.cost) continue;
		for(int i=0; i<(int)g[e.to].size(); ++i){
			Edge f = g[e.to][i];
			if(dist[f.to] > dist[e.to] + f.cost){
				dist[f.to] = dist[e.to] + f.cost;
				q.push(Edge(dist[f.to], s, f.to));
			}
		}
	}
}

int main(){
//	cin.tie(0);
//	ios::sync_with_stdio(false);
	cin >> n;
	UnionFind uf(n);
	Graph g(n);
	vector<Edge> w;
	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j){
			int t;
			cin >> t;
			if(i <= j) continue;
			w.push_back(Edge(t, i, j));
		}
	sort(w.begin(), w.end());
	reverse(w.begin(), w.end());
	for(auto e:w){
		int i = e.from, j = e.to, t = e.cost;
		if(!uf.same(i, j)){
			uf.unite(i, j);
			ans += t;
			g[i].push_back(Edge(t, i, j));
			g[j].push_back(Edge(t, j, i));
		}else{
			vector<long long> d(n, INF);
			dijkstra(i, g, d);
			if(d[j] < t){
				cout << -1 << "\n";
				return 0;
			}else if(d[j] > t){
				ans += t;
				g[i].push_back(Edge(t, i, j));
				g[j].push_back(Edge(t, j, i));
			}
		}
	}
	cout << ans << "\n";
}

