constexpr ll INF = numeric_limits<ll>::max();

ll N;
ll A[300][300];

void solve()
{
    // 条件を満たすグラフはAの部分グラフ
    // よって、ワーシャルフロイドで更新があれば存在しない
    FOR(k, 0, N) {
        REP(i, N) {
            REP(j, N) {
                if(A[i][j] > A[i][k] + A[k][j]) {
                    cout << -1 << "\n";
                    return;
                }
            }
        }
    }

    // 全てのi,j (i!=j)について
    // A[i][j] == A[i][k] + A[k][j] なるkがあればi,j間の辺を取り除く
    ll total = 0;
    FOR(i, 0, N) {
        FOR(j, i+1, N) {
            bool del = false;
            FOR(k, 0, N) {
                if(i == k || k == j) continue;
                if(A[i][k] == 0 || A[k][j] == 0) {
                    ;
                }
                else if(A[i][j] == A[i][k] + A[k][j]) {
                    del = true;
                }
                else {
                    ;
                }
            }
            if(del) {
                A[i][j] = 0;
                A[j][i] = 0;
            }
            else {
                total += A[i][j];
            }
        }
    }

    cout << total << "\n";
}

int main()
{
    cin >> N;
    REP(i, N) {
        REP(j, N) {
            cin >> A[i][j];
        }
    }

    solve();

    return 0;
}

