template<class Len = int>
class Dijkstra {
 private:
  int n;
  std::vector<std::vector<std::pair<int, Len> > > edges;
 public:
  explicit Dijkstra(int n) : n(n), edges(n) {}

  void add_edge(int from, int to, Len cost) {
    edges[from].push_back(std::pair<int, Len>(to, cost));
  }

  std::vector<Len> solve(int source) {
    const Len inf = 1e16;
    typedef std::pair<Len, int> pi;
    std::vector<Len> d(n, inf);
    std::priority_queue<pi, std::vector<pi>, std::greater<pi> > que;
    que.push(pi(0, source));
    while (!que.empty()) {
      pi p = que.top();
      que.pop();
      int idx = p.second;
      if (d[idx] <= p.first) {
        continue;
      }
      d[idx] = p.first;
      for (int j = 0; j < edges[idx].size(); ++j) {
        que.push(pi(p.first + edges[idx][j].second, edges[idx][j].first));
      }
    }
    return d;
  }
};

// Union Find begin

class UnionFind {
 private:
  vector<ll> _par;
  vector<ll> _rank;
 public:
  explicit UnionFind(ll n);
  ll find(ll x);
  void unite(ll x, ll y);
  bool isSame(ll x, ll y);
};

UnionFind::UnionFind(ll n) {
  for (ll i = 0; i < n; ++i) {
    _par.push_back(i);
    _rank.push_back(0);
  }
}

ll UnionFind::find(ll x) {
  if (_par.at(static_cast<unsigned long>(x)) == x) return x;
  else return _par.at(static_cast<unsigned long>(x)) = find(_par.at(static_cast<unsigned long>(x)));
}

void UnionFind::unite(ll x, ll y) {
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (_rank.at(static_cast<unsigned long>(x)) < _rank.at(static_cast<unsigned long>(y)))
    _par.at(static_cast<unsigned long>(x)) = y;
  else {
    _par.at(static_cast<unsigned long>(y)) = x;
    if (_rank.at(static_cast<unsigned long>(x)) == _rank.at(static_cast<unsigned long>(y)))
      ++_rank.at(static_cast<unsigned long>(x));
  }

}

bool UnionFind::isSame(ll x, ll y) {
  return find(x) == find(y);
}

// Union Find end

void solve(istream &ccin = cin, ostream &ccout = cout) {
  ll n;
  ccin >> n;
  ll2d a(n, ll1d(n));
  rep(i, n) rep(j, n) ccin >> a[i][j];
  vector<Edge> edges;
  vector<pair<ll, pair<int, int>>> p;
  rep(i, n) rep(j, n) p.emplace_back(a[i][j], pair<int, int>(i, j));
  sort(all(p));

  ll cost_sum = 0;
  Dijkstra<ll> dij(n);
  UnionFind unf(n);
  bool isCanCreate = true;
  rep(i, p.size()) {
    ll cost = p[i].first;
    ll to = p[i].second.first;
    ll fr = p[i].second.second;
    if (!unf.isSame(to, fr)) {
      unf.unite(to, fr);
      dij.add_edge(to, fr, cost);
      dij.add_edge(fr, to, cost);
      cost_sum += cost;
    }else{
      ll1d dij_s = dij.solve(to);
      if(dij_s[fr] < cost){
        isCanCreate = false;
        break;
      }else if(dij_s[fr] > cost){
        dij.add_edge(to, fr, cost);
        dij.add_edge(fr, to, cost);
        cost_sum += cost;
      }
    }
  }
  if(isCanCreate)
    ccout << cost_sum << endl;
  else
    ccout << -1 << endl;

}

int main() {
  ios::sync_with_stdio(false);
  solve();
  return 0;
}

