using namespace std;

int N;
llint G[305][305];
llint dist[305][305];
bool del[305][305];

int main(void)
{
	cin >> N;
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			cin >> G[i][j];
			dist[i][j] = G[i][j];
		}
	}

	for(int k = 0; k < N; k++){
		for(int i = 0; i < N; i++){
			for(int j = 0; j < N; j++){
				if( k != i && k != j && dist[i][k] + dist[k][j] == dist[i][j]) del[i][j] = true;
				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
			}
		}
	}

	bool check = false;
	llint ans = 0;

	for(int i = 0; i < N; i++){
		for(int j = i + 1; j < N; j++){
			if(G[i][j] > dist[i][j]){
				check = true;
				goto end;
			}
			if(!del[i][j]) ans += G[i][j];
		}
	}

	end:
	if(check) ans = -1;
	cout << ans << endl;

	return 0;
}

#include <iostream>
