const int INF=0x3f3f3f3f;
const int N=305;
int g[N][N];
int d[N][N];
bool vis[N];
int n,m;

void Dijkstra(int s)
{
    mem(d[s],INF);
    mem(vis,false);
    d[s][s]=0;

    while(true)
    {
        int v=-1;
        for(int i=0;i<n;i++)
        if(!vis[i]&&(v==-1||d[s][i]<d[s][v]))v=i;

        if(v==-1)break;
        vis[v]=true;

        for(int i=0;i<n;i++)
        {
            d[s][i]=min(d[s][i],d[s][v]+g[v][i]);
        }
    }
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n;
	for(int i=0;i<n;i++)
		for(int j=0;j<n;j++)
		{
			cin>>g[i][j];
		}

	ll ans=0;
	bool flag=true;
	for(int i=0;i<n;i++)
	{
		Dijkstra(i);
		for(int j=i+1;j<n;j++)
		if(d[i][j]<g[i][j])flag=false;
	}

	if(!flag)cout<<-1<<endl;
	else 
	{
		for(int i=0;i<n;i++)
		{
			for(int j=i+1;j<n;j++)
			{
				bool flag=false;
				for(int k=0;k<n;k++)
				{
					if(k==i||k==j)continue;
					if(d[i][k]+d[k][j]==d[i][j])flag=true;
				}
				if(!flag)ans+=d[i][j];
			}
		}
		cout<<ans<<endl;
	} 
	return 0;
}

