vector<pair<int,ll> > adj[200005];


//	multiple source dijkstra.
//	returns the distance vector from the source/s.

vector<ll> dij(vector<int> src,int n,bool spc = false){
	set<pair<ll,int> > q;	//	pair(dist,node).
	bool vis[n+1];
	memset(vis,false,sizeof(vis));
	for(int i=0;i<src.size();i++){
		if(!spc)
			q.insert(make_pair(0ll,src[i]));
		else {
			//	any special stuff for the intial distance of the sources.

		}
	}
	vector<ll> dis(n+1,1e16);

	while(q.size()){
		pair<ll,int> tmp = *q.begin();
		q.erase(q.begin());
		if(vis[tmp.second]){
			continue;
		}
		vis[tmp.second] = true;
		dis[tmp.second] = tmp.first;

		int cur = tmp.second;
		for(int i=0;i<adj[cur].size();i++){
			if(!vis[adj[cur][i].first] && dis[adj[cur][i].first] > tmp.first + adj[cur][i].second){
				dis[adj[cur][i].first] = tmp.first + adj[cur][i].second;
				q.insert(make_pair(dis[adj[cur][i].first],adj[cur][i].first));
			}
		}
	}

	return dis;
}

