vector<tuple<int, int, int>> E;
int color[300], dist[300][300], D[300][300];

int find_(int a)
{
	if (a == color[a]) return a;
	return color[a] = find_(color[a]);
}

void union_(int a, int b)
{
	a = find_(a);
	b = find_(b);
	color[a] = color[b] = min(a, b);
}

