using namespace std;
typedef pair<int, int> P1;
typedef pair<int, pair<int, int> > P2;
static const int INF = 1ll<<60;
static const int dx[] = { 1, -1, 0, 0, };
static const int dy[] = { 0, 0, 1, -1 };
static const int mod = 1000000007;
static const int MAX_N = 100000;

int N;
int A[305][305];
vector<P2> G;
vector<P1> E[305];
int ans;
int dist[305];
int used[305][305]={false};

int dijkstra(int s,int e){
    for(int i=0;i<305;++i)dist[i] = INF;
    priority_queue< P1, vector<P1>, greater<P1> > pq;
    dist[s] = 0;
    pq.push(P1(0,s));
    while(!pq.empty()){
        P1 p = pq.top();
        pq.pop();
        int v = p.second;
        if(dist[v]<p.first)continue;
        for(auto e : E[v]){
            if(dist[e.first]>dist[v]+e.second){
                dist[e.first] = dist[v]+e.second;
                pq.push(P1(dist[e.first],e.first));
            }
        }
    }
    return dist[e];
}

signed main(){
    cin>>N;
    for(int i=0;i<N;++i){
        for(int j=0;j<N;++j){
            int a;
            int u = min(i,j);
            int v = max(i,j);
            cin>>a;
            A[u][v] = a;
            G.PB(P2(a,P1(u,v)));
        }
    }

    sort(G.begin(),G.end());

    for(auto u : G){
        int from = u.second.first, to = u.second.second;
        if(used[from][to])continue;
        used[from][to] = true;
        int cost = dijkstra(from,to);
        if(cost==INF||cost>u.first){
            E[from].PB(P1(to,u.first));
            E[to].PB(P1(from,u.first));
            ans+=u.first;
        }
        else {
            if(cost!=u.first){
                cout<<-1<<endl;
                return 0;
            }
        }
    }
    cout<<ans<<endl;

}

