template <typename T, typename U> class dijkstra {
public:

    struct edge {
        T to;
        U cost;
    };

    using P = pair<U, T>;
    map<T, vector<edge> > E;
    map<T, U> d;

    void calc(T s) {
        priority_queue <P, vector<P>, greater<P> > que;
        rep(i, 301) d[i] = LINF; //INF
        que.emplace(U(0), s);
        d[s] = U(0);
        while (!que.empty()) {
            P p = que.top();
            que.pop();
            T v = p.second;
            if (d[v] < p.first) continue;

            for (auto&& e : E[v]) {
                //if (d.find(e.to) == d.end()) d[e.to] = INF;
                if (d[e.to] > d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    que.emplace(d[e.to], e.to);
                }
            }
        }
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    ll a[n][n];
    rep(i, n) rep(j, n) cin >> a[i][j];

    smaller_queue<pair<ll, pll> > que;
    rep(i, n) REP(j, i + 1, n) que.push(MP(a[i][j], MP(i, j)));
    ll ans = 0;
    dijkstra<ll, ll> ds;
    while (!que.empty()) {
        ll now_dist = que.top().first;
        pll p = que.top().second;
        ll From = p.first, To = p.second;
        ds.calc(p.first);
        if (ds.d[p.second] == LINF || now_dist < ds.d[p.second]) {
            ans += now_dist;
            ds.E[From].push_back({To, now_dist});
            ds.E[To].push_back({From, now_dist});
        }
        que.pop();
    }
    ll dist[n][n];
    rep(i, n) rep(j, n) dist[i][j] = (i == j ? 0 : LINF);

    rep(i, n) {
        for (auto e : ds.E[i]) {
            dist[i][e.to] = dist[e.to][i] = e.cost;
        }
    }
    bool valid = true;

    rep(i, n) {
        ds.calc(i);
        REP(j, i + 1, n) if (ds.d[j] != a[i][j]) valid = false;
    }

    cout << (valid ? ans : -1) << endl;
    return 0;
}

