    cin >> n;
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <=n; ++j) {
            cin >> mp[i][j];
        }
    }
    if (!s()) {
        cout << -1 << endl;
        return 0;
    }
    ll sum = 0;
    for (i = 1; i <= n; ++i) {
        for (j = i + 1; j <= n; ++j) {
            if (mp2[i][j] < mp[i][j]) {
                cout << "ma\n";
            }
            if (mp2[i][j] > mp[i][j]) {
                sum += mp[i][j];
            }
        }
    }
    cout << sum << endl;
    return 0;
}

