LL int dis[300][300];  
LL int path[300][300];
LL int old[300][300];

void folyd(LL int n)
{  
    for(LL int k = 1 ; k <= n ; k++)
	{
        for(LL int i = 1 ; i <= n ; i++)
		{  
            for(LL int j = 1 ; j <= n ; j++)  
                dis[i][j] = min(dis[i][k]+dis[k][j] , dis[i][j]);
		}
	}
}

int main()
{
    LL int n;
    cin>>n;
    LL int add=0;
    memset(old,0,sizeof(old));
    memset(dis,0,sizeof(dis));
    memset(path,0,sizeof(path));
    for (int i=0;i<n;i++)
        for(int j=0;j<n;j++)
        {
		    cin>>path[i][j];
		    old[i][j]=path[i][j];
		}
	for (int tim=0;tim<n-1;tim++)
	{
	    LL int num=1000000000;
	    LL int heng,zong;
	for (int i=0;i<n;i++)
        for(int j=0;j<n;j++)
        {
		    if(path[i][j]=0)
			    continue;
			else if (path[i][j]<num)
			    {
				num=path[i][j];
				heng=i;
				zong=j;
			    }
		}
		dis[heng][zong]=path[heng][zong];
		dis[zong][heng]=path[heng][zong];
		path[zong][heng]=0;
		path[heng][zong]=0;
		add+=dis[heng][zong];
	}
    folyd(n);
    int flag=0;
    for (int i=0;i<n;i++)
        for(int j=0;j<n;j++)
        {
		    if(old[i][j]!=dis[i][j])
		        flag=1;
		}
	if (flag==1)
	cout<<-1<<endl;
	else
	cout<<add<<endl;
	return 0;
}

