#include<bits/stdc++.h>

using namespace std;
using ll = long long;
using P = pair<ll,ll>;
const ll mod = 1000000007;
const ll INF = 1e15;


void dijkstra(ll N,ll start,const vector<vector<pair<ll,ll>>>& Hen, vector<vector<ll>>& DS){
    vector<ll> dist(N,1e15);
    using T = pair<ll,ll>;
    priority_queue<T,vector<T>,greater<T>> que;
    que.push({0,start}); //dist(start) = 0;
    while(que.size()){
        auto cur = que.top(); //見る地点
        que.pop();
        for(auto i : Hen[cur.second]){ //curから見れる全ての辺について
            if(dist[i.first] > cur.first + i.second){
                dist[i.first] = cur.first + i.second;
                que.push({dist[i.first],i.first});
            }
        }
    }

    for(ll i = 0; i < N; i++){
        DS[i][start] = min(dist[i], DS[i][start]);
        DS[start][i] = min(dist[i], DS[start][i]);
    }

}




int main()
{
    ll n;
    cin >> n;
    vector<vector<ll>> cost(n, vector<ll>(n));
    using T = pair<ll,pair<ll,ll>>;
    priority_queue<T, vector<T>, greater<T>> que;
    for(ll i = 0; i < n; i++){
        for(ll j = 0; j < n; j++){
            cin >> cost[i][j];
            if(i > j) que.push({cost[i][j], {i, j}});
        }
    }

    vector<vector<ll>> dist(n, vector<ll>(n, INF));
    vector<vector<pair<ll,ll>>> hen(n);
    for(ll i = 0; i < n; i++)dist[i][i] = 0;
    ll ans = 0;

    while(que.size()){
        ll co = que.top().first;
        auto ver = que.top().second;
        que.pop();
        if(co > dist[ver.first][ver.second] || co > dist[ver.second][ver.first]){
            cout << -1 << endl;
            return 0;
        }

        if(co == dist[ver.first][ver.second])continue;

        hen[ver.first].push_back({ver.second, co});
        hen[ver.second].push_back({ver.first, co});
        dijkstra(n, ver.first, hen, dist);
        dijkstra(n, ver.second, hen, dist);
        ans += co;

    }
    cout << ans << endl;

}

