};

void wf(){
  for(ll k=0; k<N; k++){
    for(ll s=0; s<N; s++){
      for(ll j=0; j<N; j++){
        B[s][j]=min(B[s][j],B[s][k]+B[k][j]);
      }
    }
  }  
}

int main(){
