  vector<P> Z(0,{0,0,0});
  for(ll i=0; i<N; i++) for(ll j=0; j<N; j++) cin>>A[i][j];
  for(ll i=0; i<N; i++) B[i][i]=0;
  for(ll i=0; i<N; i++) for(ll j=i+1; j<N; j++) Z.push_back({A[i][j],i,j});
  sort(Z.begin(), Z.end(), [](auto& x, auto& y){return x.d < y.d;});  
  UnionFind tree(N);
  ll cnt=0,i=-1,ans=0,zsz=Z.size();
  while(cnt<N-1 && ++i<zsz){
    P v=Z[i];
    if(tree.issame(v.to1,v.to2)) continue;
    cnt++;
    ans+=v.d;
    tree.unite(v.to1,v.to2);
    //Bに最短直通だけコピー
    B[v.to1][v.to2]=v.d;
    B[v.to2][v.to1]=v.d;
  }
//check＋ルート追加
  while(++i<zsz){
    wf();
    //check
    bool add=false;
    for(ll i=0; i<N; i++){
      if(add) break;
      for(ll j=0; j<N; j++){
        if(A[i][j]==B[i][j])continue;
        else if(A[i][j]>B[i][j]){//小さければどうしようもない
          cout<<-1<<endl;
          return 0;
        }
        else{//大きければ追加
          add=true;
          break;
        }
      }
    }
    if(!add){//完全一致
      cout<<ans<<endl;      
      return 0;
    }
    P v=Z[i];
    ans+=v.d;
    B[v.to1][v.to2]=v.d;
    B[v.to2][v.to1]=v.d;
  }
  cout<<ans<<endl;
}

