	std::cin >> N;
	std::vector<std::vector<std::int64_t>> data(N);
	for (int i = 0; i < N; ++i)
	{
		data[i] = std::vector<std::int64_t>(i + 1, std::int64_t(std::numeric_limits<std::int32_t>::max()) * 300);
		data[i][i] = 0;
	}
	auto access = [&](int i, int j)->std::int64_t&
	{
		return data[std::max(i, j)][std::min(i, j)];
	};
	lib::p_queue<std::pair<std::int64_t, std::pair<int, int>>> queue;
	for (int i = 0; i < N; ++i)
	{
		for (int j = 0; j <= i; ++j)
		{
			std::int64_t a;
			std::cin >> a;
		}
		for (int j = i + 1; j < N; ++j)
		{
			std::int64_t v;
			std::cin >> v;
			queue.emplace(v, std::make_pair(i, j));
		}
	}
	std::int64_t sum = 0;
	while (queue.size())
	{
		auto top = queue.top();
		queue.pop();
		auto val = top.first;
		auto pair = top.second;
		if (val > access(pair.first, pair.second))
		{
			std::cout << -1 << std::endl;
			return;
		}
		if (val == access(pair.first, pair.second))
		{
			continue;
		}
		access(pair.first, pair.second) = val;
		sum += val;
		for (int i = 0; i < N; ++i)
		{
			for (int j = 0; j < i; ++j)
			{
				access(i, j) = std::min({
					access(i,j),
					access(i,pair.first) + access(j,pair.second) + val,
					access(j,pair.first) + access(i,pair.second) + val });
			}
		}
	}
	std::cout << sum << std::endl;
}

