    return cost < x.cost;
  }
};

bool bad[N][N];

void go(int st) {
  rep(i, 1, n) d[i] = linf;
  d[st] = 0;
  ++timer;
  rep(i, 1, n) {
    int v = -1;
    rep(j, 1, n) {
      if (was[j] != timer) {
        if (v == -1) v = j;
        else if (d[j] < d[v]) v = j;
      }
    }
    if (v == -1 || d[v] == linf) break;
    was[v] = timer;
    for (auto to : g[v]) {
      if (!bad[v][to.f] && d[to.f] > d[v] + to.s) {
        d[to.f] = d[v] + to.s;
      }
    }
  }
}
bool check(int v, int u) {
  bad[v][u] = bad[u][v] = 1;
  rep(i, 1, n) {
