					numComplete++;
				}

				minDist[tmpSrc][tmpDst]= std::min(prevDist + roadList[i].dist, minDist[tmpSrc][tmpDst]);

			}

			prevDist= minDist[std::min(roadList[i].dst, j)][std::max(roadList[i].dst, j)];

			if(prevDist>= 0){
				int tmpSrc= std::min(roadList[i].src, j);
				int tmpDst= std::max(roadList[i].src, j);

				if(prevDist + roadList[i].dist < aList[tmpSrc][tmpDst]){
