#include <bits/stdc++.h>

using namespace std;

const int N = 305;
const long long INF = 1e18 + 5;

int n;
int A[N][N];
vector<pair<int, pair<int, int> > > dists;
vector<pair<int, int> > V[N];
long long dist[N];
bool vis[N];

long long calcDist(int a, int b) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
        vis[i] = false;
    }
    priority_queue<pair<long long, int> > Q;
    dist[a] = 0;
    Q.push({0, a});
    while (!Q.empty()) {
        int w = Q.top().second;
        Q.pop();
        if (vis[w]) continue;
        vis[w] = true;
        for (auto e : V[w]) {
            int u = e.first;
            int kr = e.second;
            if (dist[u] > dist[w] + kr) {
                dist[u] = dist[w] + kr;
                Q.push({-dist[u], u});
            }
        }
    }
    return dist[b];
}

long long ans;
void addEdge(int a, int b, int dist) {
    V[a].push_back({b, dist});
    V[b].push_back({a, dist});
    ans += dist;
}

int main() {

    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            scanf("%d", &A[i][j]);
            dists.push_back({A[i][j], {i, j}});
        }
    }

    sort(dists.begin(), dists.end());
    for (auto p : dists) {
        int dist = p.first;
        int a = p.second.first;
        int b = p.second.second;
        long long d = calcDist(a, b);
        if (d == dist) {
            continue;
        } else if (d < dist) {
            printf("-1\n");
            return 0;
        } else {
            addEdge(a, b, dist);
        }
    }

    printf("%lld\n", ans);

    return 0;
}

