priority_queue<pair<int,int>,vector<pair<int,int> >,greater<pair<int,int> > > q1;
priority_queue<pair<long long int,int>,vector<pair<long long int,int> >,greater<pair<long long int,int> > > q2;
vector<pair<int,int> > path[305];
bool used[305];

long long int path_check(int a,int b){
	long long int c,d;
	q2.push(make_pair(0,a));
	while(!q2.empty()){
		c=q2.top().first,d=q2.top().second,q2.pop();
		if(used[d])continue;
		used[d]=true;
		if(b==d)return c;

		for(int i=0;i<path[d].size();i++){
			if(used[path[d][i].first])continue;
			q2.push(make_pair(c+path[d][i].second,path[d][i].first));
		}
	}
	return -1;
}

int main(){
	int n;
	long long int i,j,k;
	long long int a,b,c;
	long long int s=0;
	cin>>n;
	for(i=0;i<n;i++){
		for(j=0;j<n;j++){
			scanf("%d",&a);
			if(i>=j)continue;
			q1.push(make_pair(a,i*n+j));
		}
	}
	while(!q1.empty()){
		a=q1.top().first,b=q1.top().second,q1.pop();
		c=b%n,b/=n;
		memset(used,false,sizeof(used));
		k=path_check(b,c);
		while(!q2.empty()){q2.pop();}
		if(k==-1 || k>a){
			path[b].push_back(make_pair(c,a));
			path[c].push_back(make_pair(b,a));
			s+=a;
		}else if(k<a){
			s=-1;
			break;
		}
	}
	cout<<s<<endl;
	while(!q1.empty()){q1.pop();}
	return 0;
}

