struct Edge{
    int u,v,w;
    bool operator<(const Edge &a) const{
        return w<a.w;
    }
};
vc<Edge> G[maxn];
ll dis[maxn];
bool vis[maxn];
struct D{
    ll d,u;
    bool operator<(const D& a)const{
        return d>a.d;
    }
};
ll dij(int s,int t)
{
    memset(dis,0x3f,sizeof(dis));
    memset(vis,0,sizeof(vis));
    dis[s]=0;
    priority_queue<D> q;
    q.push(D{0,s});
    while(!q.empty())
    {
        auto u=q.top();q.pop();
        if(vis[u.u]) continue;
        vis[u.u]=1;
        for(auto &e:G[u.u])
        {
            int v=e.v;
            if(dis[v]>dis[u.u]+e.w)
            {
                dis[v]=dis[u.u]+e.w;
                q.push(D{dis[v],v});
            }
        }
    }
    return dis[t];
}
