void dijkstra(int s,int n)
{
	for(int i=1;i<=n;i++)
	{
		d[i]=-1;
		vst[i]=false;
	}
	d[s]=0;
	p.first=d[s];
	p.second=s;
	m2.push(p);
	while(!m2.empty())
	{
		p=m2.top();
		int u=p.second;
		m2.pop();
		if(vst[u])continue;
		vst[u]=true;
		for(int i=0,v,w;i<adj[u].size();i++)
		{
			v=adj[u][i].first;
			w=adj[u][i].second;
			if(d[v]==-1 || d[u]+w<d[v])
			{
				prnt[v]=u;
				d[v]=d[u]+w;
				p.first=d[v];
				p.second=v;
				m2.push(p);
			}
		}
	}
}









