/*
  let's try computer shogi!!!
  行列を距離が短い道路順にソートする。fromとtoが接続されていなかったら、
  二つの都市を結ぶ道路を建設する
  fromとtoが既に接続されていて、かつ、其の距離が行列で与えられた値より小さかったら-1
 */

int N;

struct load{
  int from;
  int to;
  long long int distance;
};

// 既に決定された距離
std::vector<std::vector<long long int>> fdist;

const long long int infdist = 114514191919334;

bool comp_load(const load &l1, const load &l2){
  return l1.distance < l2.distance;
}

void viewload(vector<load> &loads){
  for(int i=0;i<loads.size();++i){
    //cerr<<loads[i].from<<","<<loads[i].to<<","<<loads[i].distance<<"(from,to,dist)"<<endl;
  }
}


std::vector<long long int> dijkstra(std::vector<std::vector<long long int>> &dist, int from)
{
  long long int at;
  std::vector<long long int> prev(dist.size());
  std::map<int, long long int> ensemble;

  for(int i=0;i<dist.size();i++){
    ensemble.insert(std::pair<long long int, long long int>(i, infdist));
  }
  ensemble[from]=0;
  while(ensemble.size()!=0){
    auto nodeItr = min_element(ensemble.begin(),ensemble.end(),[&](std::pair<long long int, long long int> lhs,std::pair<int, long long int> rhs){
	return lhs.second < rhs.second;
      });
    at = nodeItr->first;
    for(int i=0;i<dist[at].size();i++){
      if(ensemble.find(i)!=ensemble.end() && dist[at][i]!=0){
	//cerr<<dist[at][i]<<","<<at<<","<<i<<"d,a,i"<<endl;
	if(ensemble[i] > ensemble[at]+dist[at][i]){
	  ensemble[i] = ensemble[at]+dist[at][i];
	  prev[i] = ensemble[at]+dist[at][i];
	}
      }
    }
    ensemble.erase(nodeItr);
  }
  return prev;
}


int main(){
  vector<load> loads;
  cin >> N;
  fdist.resize(N);
  for(int i=0;i<N;++i){
    fdist[i].resize(N);
    for(int j=0;j<N;++j){
      load ld;
      ld.from = i;
      ld.to = j;
      cin >> ld.distance;
      loads.push_back(ld);
      fdist[i][j] = infdist / 5000;
    }
  }
  sort(loads.begin(), loads.end(), comp_load);
  viewload(loads);

  long long int ans = 0;
  for(int i=0;i<loads.size();++i){
    // fromからtoへの距離を求める
    vector<long long int> ftdists = dijkstra(fdist,loads[i].from);
    for(int i=0;i<N;++i){
      //cerr<<ftdists[i]<<",";
    }
    //cerr<<endl;
    long long int ftdist = ftdists[loads[i].to];
    //cerr<<ftdist<<","<<loads[i].from<<","<<loads[i].to<<",(d,i,j)"<<endl;

    if(ftdist > loads[i].distance){
      // 道をつなぐ
      fdist[loads[i].from][loads[i].to] = fdist[loads[i].to][loads[i].from] = loads[i].distance;
      ans += loads[i].distance;
    }else if(ftdist< loads[i].distance){
      //cerr<<loads[i].distance<<" is larger"<<endl;
      cout<<"-1"<<endl;
      return 0;
    }
  }
  cout<<ans<<endl;
  return 0;
}

