using namespace std;
using ll=long long; 
using Weight=ll;
struct Edge {
    int src,dest; Weight weight;
    bool operator<(const Edge &rhs)const{
        return weight<rhs.weight;
    }
};
using Edges=vector<Edge>;
using Graph=vector<Edges>;

const Weight INF=1e12;

void dijkstra(const Graph &g,int s,vector<Weight> &d){
    assert(0<=s && s<g.size());
    d.assign(g.size(),INF); d[s]=0;
    vector<int> used(g.size(),0);
    using P=pair<Weight,int>;
    priority_queue<P,vector<P>,greater<P>> que;
    que.push({0,s});
    while(!que.empty()){  
        auto val=que.top(); que.pop();
        Weight dist=val.first;
        int v=val.second;
        if(used[v]) continue;
        used[v]=true;
        for(auto e:g[v]){
            int to=e.dest;
            Weight w=e.weight;
            if(dist+w<d[to]){
                d[to]=dist+w;
                que.push({d[to],to});
            }
        }
    }
}




int main(){
    int n;
    cin>>n;
    cin.tie(0);
    ios::sync_with_stdio(false);
    vector<vector<ll>> edge(n,vector<ll>(n,0));
    for(int i=0;i<n;i++)for(int j=0;j<n;j++) cin>>edge[i][j];

    const ll INF=1e15;
    vector<vector<ll>> d(n,vector<ll>(n,INF));
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            d[i][j]=edge[i][j];
        }
    }
    for(int k=0;k<n;k++){
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++){
                d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
            }
        }
    }
    if(d!=edge){
        cout<<-1<<endl;
        return 0;
    }

    using pp=pair<ll,pair<int,int>>;
    priority_queue<pp,vector<pp>,greater<>> que;
    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            que.push({edge[i][j],{i,j}});
        }
    }

    ll res=0;
    Graph g(n);
    while(!que.empty()){
        auto val=que.top();
        que.pop();
        long long int cost=val.first;
        int a=val.second.first;
        int b=val.second.second;
        vector<ll> d(n,INF);
        dijkstra(g,a,d);
        if(d[b]!=cost){
            res+=cost;
            Edge e;
            e.src=a;
            e.dest=b;
            e.weight=cost;
            g[a].push_back(e);
            e.src=b;
            e.dest=a;
            g[b].push_back(e);
        }
    }
    cout<<res<<endl;
    return 0;
}

