using namespace std;

bool isRequired(const vector<vector<int>>& m, int src, int dst){
	const int n = m.size();
	vector<long long> dist(n, 1LL << 60);
	using Node = pair<long long, int>;
	priority_queue<Node, vector<Node>, greater<Node>> qu;
	qu.emplace(0, src);
	dist[src] = 0;
	while(!qu.empty()){
		auto pr = qu.top(); qu.pop();
		long long d = pr.first;
		for(int i=0;i<n;i++){
			if(pr.second == src && i == dst) continue;
			long long nd = d + m[pr.second][i];
			if(nd < dist[i]){
				dist[i] = nd;
				qu.emplace(nd, i);
			}
		}
	}
	return (dist[dst] > m[src][dst]);
}

long long solve(const vector<vector<int>>& m){
	const int n = m.size();
	for(int k=0;k<n;k++){
		for(int i=0;i<n;i++){
			for(int j=0;j<n;j++){
				if(m[i][k]+m[k][j] < m[i][j]) return -1;
			}
		}
	}
	long long res = 0;
	for(int i=0;i<n;i++){
		for(int j=i+1;j<n;j++) if(isRequired(m, i, j)) res += m[i][j];
	}
	return res;
}

