int dijkstra(vector<unordered_map<int, ll>>& edges, int start, int goal)
{
    if (start == goal) return 0;
    auto comp = [](pair<int, ll>& l, pair<int, ll>& r){return l.second > r.second;};
    priority_queue<pair<int, ll>, vector<pair<int, ll>>, decltype(comp)> pq(comp);
    vector<char> finished(edges.size(), false);
    pq.emplace(start, 0);
    finished[start] = true;

    while (!pq.empty()){
        const int next_node = get<0>(pq.top());
        const ll temp_cost = get<1>(pq.top());
        pq.pop();
        if (next_node == goal) return temp_cost;
        finished[next_node] = true;
        for (auto& node : edges[next_node]){
            if (finished[node.first]) continue;
            const ll next_cost = temp_cost + node.second;
            pq.emplace(node.first, next_cost);
        }
    }
    return -1;
}

