 int merge(int a,int b)
 {
 	if(-xd[a]<-xd[b])
 	{
 		xd[b]+=xd[a];
 		xd[a]=b;
 		return -xd[b];
	 }
	 else
	{
		xd[a]+=xd[b];
		xd[b]=a;
		return -xd[a];
	}
 }

