}

bool wf2(vector< vector<long long int> > d, long long int x, long long int y){
  long long int tmp = d[y][x];
  d[y][x] = inf;
  for(int i=0; i<n; i++){
    for(int j=0; j<n; j++){
      for(int k=0; k<n; k++){
        d[j][k] = min(d[j][k], d[j][i] + d[i][k]);
      }
    }
  }
  return tmp == d[y][x];
}
