bool dijk(vector< vector<long long int> > d, int x, int y){
  long long int tmp = d[y][x];
  int pos = x;
  vector<long long int> c(n, inf);
  vector<bool> v(n, false);
  v[pos] = true;
  c[pos] = 0;
  priority_queue< pair<int, int> > pq;
  pq.push(make_pair(0,pos));
  while( !pq.empty() ){
    pair<int, int> p = pq.top();
    pq.pop();
    for(int i=0; i<g.size(); i++){
      if( g[i].to == p.second && !v[g[i].from] ){
        v[g[i].from] = true;
        c[g[i].from] = min(c[g[i].from], c[g[i].to] + g[i].cost);
        pq.push(make_pair(c[g[i].from], g[i].from));
      }else if( g[i].from == p.second && !v[g[i].to] ){
        v[g[i].to] = true;
        c[g[i].to] = min(c[g[i].to], c[g[i].from] + g[i].cost);
        pq.push(make_pair(c[g[i].to], g[i].to));
      }
    }
  }
  return c[y] == tmp;
}

