int w[300][300];
using namespace std;

signed main(){
  const int INF=1e18;
  int N;
  cin>>N;
  int out=0;
  for(int i=0;i<N;i++)for(int j=0;j<N;j++)if(i!=j)w[i][j]=INF;
  for(int i=0;i<N;i++)for(int j=0;j<N;j++)cin>>g[i][j];
  int ans=0;
  typedef pair<int,int> P;
  priority_queue<P,vector<P>,greater<P>> que;
  for(int i=0;i<N;i++){
    for(int j=0;j<i;j++){
      que.push(P(g[i][j],i*1000+j));
    }
  }
  while(que.size()){
    P p=que.top();
    que.pop();
    int mi=(p.second)/1000;
    int mj=(p.second)%1000;
    if(p.first==w[mi][mj])continue;
    if(p.first>w[mi][mj]){
      out++;
      continue;
    }
    w[mi][mj]=p.first;
    ans+=p.first;
    for(int i=0;i<N;i++){
      for(int j=0;j<N;j++){
        for(int k=0;k<N;k++){
          w[i][j]=min(w[i][j],w[i][k]+w[k][j]);
        }
      }
    }
  }
  if(out)cout<<-1<<endl;
  else cout<<ans<<endl;
}

