vi adjL[N];

vi parent;

void reset (int n) {
    parent = vi(n+1);
    lp(i,1,n) parent[i] = i;
}

int find_set(int x){
    if(x == parent[x]) return x;
    return parent[x] = find_set(parent[x]);
}

bool union_sets(int x,int y){
    x = find_set(x) , y = find_set(y);
    parent[x] = y;

    return x !=y ;
}


ll MST_Kruskal() {
    ll mstcoast = 0;
    reset(n);
    priority_queue <edge> q;

    for(int i=0;i<(int) edgeList.size() ;i++)
        q.push(edgeList[i]);

    while(!q.empty()) {
        edge e = q.top();       q.pop();
        if(union_sets( e.from , e.to )) {
            adjL[e.from].pb(e.to);
            adjL[e.to].pb(e.from);
            mstcoast+=e.w;
        }
    }

    return mstcoast;
}

