typedef long long LL;

const LL INF = 1e14;
const int mod = 1e9 + 7;
const int MX = 1e3 + 5;

int n, m, vis[MX];
LL mn_dist[MX];
pair<int, pii> edges[MX * MX];
vector<pair<int, int> > g[305];

int comp[305], sz[305];

void init_dsu() {
    loop(i, 305) {
        sz[i] = 1;
        comp[i] = i;
    }
}

int find(int u) {
    if (u == comp[u]) return u;
    return comp[u] = find(comp[u]);
}

void merge(int u, int v) {
    u = comp[u];
    v = comp[v];
    if (u == v) return;
    if (sz[u] > sz[v]) swap(u, v);
    sz[v] += sz[u];
    comp[u] = v;
}

LL dijkstra(int cur, int target) {
    set<pair<LL, int> > S;
    S.insert({0ll, cur});
    while (!S.empty()) {
        auto front = *S.begin();
        S.erase(S.begin());
        int u = front.second;
        LL dist = front.first;
        if (u == target) return dist;
        if (vis[u]) continue;
        vis[u] = 1;
        for (pair<int, int> p: g[u]) {
            int v = p.first;
            LL l = p.second;
            S.insert({l + dist, v});
        }
    }
    return INF;
}

