            if (i >= j) continue;
            edges[cntr] = {l, {i, j}};
            cntr++;
        }
    }
    sort(edges, edges + cntr);
    LL ans = 0;
    init_dsu();
    loop(i, cntr) {
        int length = edges[i].first;
        int u = edges[i].second.first;
        int v = edges[i].second.second;
        memset(vis, 0, sizeof(vis));
        memset(mn_dist, -1, sizeof(mn_dist));
        LL orig_length;
        if (find(u) != find(v)) orig_length = INF;
        else orig_length = dijkstra(u, v);
        if (orig_length == INF || length < orig_length) {
            g[u].push_back({v, length});
            g[v].push_back({u, length});
            merge(u, v);
            ans += length;
        }
        else if (length > orig_length) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << ans << endl;
    return 0;
}

