int prim(int s=0){
    priority_queue<pii,vector<pii>,greater<pii> > pq;
    pq.emplace(0,s);
    int total=0;
    vector<bool> used(N,false);
    while(!pq.empty()){
        int d;
        int cur;
        tie(d,cur) = pq.top();
        pq.pop();
        if(used[cur]) continue;
        used[cur] = true;
        total += d;
        for (int i = 0; i < N; i++)
        {
            if(i==cur) continue;
            if(used[i]) continue;
            pq.emplace(A[cur][i],i);
        }

    }
    return total;
}

