    }
};

int main(){
    int N;
    cin >> N;

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            cin >> dist[i][j];
            dist_backup[i][j] = dist[i][j];
        }
    }

    for(int k=0;k<N;k++){
        for(int i=0;i<N;i++){
            for(int j=0;j<N;j++){
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }

    vector<edge> E;
    for(int i=0;i<N;i++){
        for(int j=i+1;j<N;j++){
            if(dist[i][j] != dist_backup[i][j]){
                cout << -1 << endl;
                return 0;
            }
            E.emplace_back(i, j, dist[i][j]);
        }
