                    if(answer[x][k] + answer[k][y] == value) {
                        must = 0;
                    }
                }
            }
        }

        if(no) {
            answer[x][y] = answer[y][x] = value;
            ans += value;
        }
        else{
            if(must) {
                answer[x][y] = answer[y][x] = value;
                ans += value;
            }
        }

        make_heap(vec.begin(), vec.end(), cmp);
    }

    cout<< ans <<'\n';

}

