  Graph graph(n);
  int tmp;
  REP(i, n) {
    REP(j, n) {
      cin >> tmp;
      if(i < j) v.push(Edge(i, j, tmp));
    }
  }

  ll ans = 0;


  int siz = SZ(v);
  int from, to, cost;
  REP(i, siz) {
    from = v.top().from;
    to = v.top().to;
    cost = v.top().cost;
    v.pop();

    vector<ll> d = dijkstra(graph, from);
    if(cost < d[to]) {
      ans += cost;
      graph[from].pb(Edge(from, to, cost));
      graph[to].pb(Edge(to, from, cost));
    } else if(cost > d[to]) {
      cout << -1 << endl;
      return 0;
    }
  }

  assert(false);
  cout << ans << endl;

}

