ll dist (int A, int B) {
	for(int i=1;i<=n;i++) {
		dis[i] = inf;
	}
	dis[A] = 0;
	pq.push({0, A});
	while(!pq.empty()) {
		ll C = pq.top().Y, D = -pq.top().X;
		pq.pop();
		if(dis[C] != D) continue;
		if(C == B) return D;
		for(auto &T : adj[C]) {
			ll A, B;
			tie(A, B) = T;
			if(dis[A] > D + B) {
				dis[A] = D + B;
				pq.push({-dis[A], A});
			}
		}
	}
	return inf;
}

