#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()
#define INF 1000000000000000000

struct path {
    int from, to;
    ll cost;
    bool operator<(const path& p) const { return cost < p.cost; }
};

int N;
ll A[300][300], AN[300][300];

int main() {
    cin >> N;
    REP(i, N) REP(j, N) {
        cin >> A[i][j];
        AN[i][j] = INF;
    }
    REP(i, N) AN[i][i] = 0;

    vector<path> ps;
    FOR(i, 1, N) REP(j, i) {
        ps.push_back({i, j, A[i][j]});
    }
    sort(ALL(ps));

    ll ans = 0;
    for (auto p : ps) {
        if (p.cost < AN[p.from][p.to]) {
            ans += p.cost;
            AN[p.from][p.to] = p.cost;
            AN[p.to][p.from] = p.cost;
            REP(i, N) {
                AN[i][p.to] = AN[p.to][i] = min(AN[i][p.to], AN[i][p.from] + AN[p.from][p.to]);
                AN[i][p.from] = AN[p.from][i] = min(AN[i][p.from], AN[i][p.to] + AN[p.to][p.from]);
            }
        }
        else if (p.cost > A[p.from][p.to]) {
            cout << -1 << endl;
            return 0;
        }
    }
    bool same = true;
    REP(i, N) REP(j, N) same &= A[i][j] == AN[i][j];
    if (same) cout << ans << endl;
    else cout << -1 << endl;
    return 0;
}

