        }
}

inline void Move(int &u, int d){
    int i = 0;
    while (d){
        if (d & 1)
            u = p[u][i];
        d >>= 1; i++;
    }
}

bool cmp(edge a, edge b){
    return a.c < b.c;
}

int LCA(int u, int v){
    if (d[u] < d[v])
        Move(v, d[v] - d[u]);
    else
        Move(u, d[u] - d[v]);
    if (u == v) return u;
    for (int i = LOG; i >= 0; i--){
        if (p[u][i] != p[v][i]){
            u = p[u][i];
            v = p[v][i];
        }
    }
    return p[u][0];
}

int DIST(int u, int v){
    return dist[u] + dist[v] - 2 * dist[LCA(u, v)];
}

struct cmpx{
    bool operator () (ii a, ii b){
        return a.y > b.y;
    }
};

void Dijkstra(int s){
    priority_queue <ii, vector <ii>, cmpx> heap;
    heap.push(ii(s, 0));
    fill(dist, dist + n + 1, oo);
    dist[s] = 0;
    while (heap.size()){
        int u = heap.top().x;
        long long w = heap.top().y;
        heap.pop();
        if (dist[u] != w) continue;
        for (int v: adj[u])
            if (dist[v] > dist[u] + a[u][v]){
                dist[v] = dist[u] + a[u][v];
                heap.push(ii(v, dist[v]));
            }
    }
}

