	int n;
	cin >> n;
	ll orit[301][301];
	ll wt[301][301];
	for (size_t i = 1; i <= n; i++)
	{
		for (size_t j = 1; j <= n; j++)
		{
			cin >> orit[i][j];
			wt[i][j] = orit[i][j];
		}
	}
	bool find[301][301];
	for (size_t i = 1; i <= n; i++)
	{
		for (size_t j = 1; j <= n; j++)
		{
			find[i][j] = false;
		}
	}

	for (size_t i = 1; i <= n; i++)
	{
		for (size_t j = 1; j <= n; j++)
		{
			for (size_t k = 1; k <= n; k++)
			{

				if (j != i && i != k && wt[j][k] == wt[j][i] + wt[i][k]) {
					find[j][k] = true;
				}
				wt[j][k] = min(wt[j][k], wt[j][i] + wt[i][k]);
			}
		}
	}

	ll res = 0;
	for (size_t i = 1; i <= n; i++)
	{
		for (size_t j = i + 1; j <= n; j++)
		{
			if (orit[i][j] > wt[i][j]) {
				cout << -1 << endl;
				return;
			}
			res += find[i][j] ? 0 : wt[i][j];
		}
	}
	cout << res << endl;
}


