typedef long long ll;
const int MAXN = 305;
struct { int v, next; ll w; } e[MAXN * MAXN];
int head[MAXN], cnt_edge;
inline void add_edge(int u, int v, ll w) {
    e[cnt_edge] = { v, head[u], w };
    head[u] = cnt_edge++;
}
ll dis[MAXN][MAXN];
int n;
struct Item {
    ll val;
    int u, v;
    bool operator > (const Item &item) const {
        return val > item.val;
    }
};
priority_queue<Item, vector<Item>, greater<Item>> que;
queue<int> que_;
bool inque[MAXN];
void spfa(int s) {
    que_.push(s);
    inque[s] = true;
    while(!que_.empty()) {
        int u = que_.front(); que_.pop();
        inque[u] = false;
        for(int i = head[u]; i != -1; i = e[i].next) {
            if(dis[s][e[i].v] > dis[s][u] + e[i].w) {
                dis[s][e[i].v] = dis[s][u] + e[i].w;
                if(!inque[e[i].v]) {
                    que_.push(e[i].v);
                    inque[e[i].v] = true;
                }
            }
        }
    }
}
int main() {
    memset(head, 0xff, sizeof(head));
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) for(int j = 1; j <= n; j++) {
        if(i == j) dis[i][j] = 0;
        else dis[i][j] = 1e18;
        ll val; scanf("%lld", &val);
        if(i < j) {
            que.push((Item){val, i, j});
        }
    }
    ll ans = 0;
    while(!que.empty()) {
        Item item = que.top(); que.pop();
        spfa(item.u);
        if(dis[item.u][item.v] < item.val) {
            printf("-1\n");
            return 0;
        }
        else {
            add_edge(item.u, item.v, item.val);
            add_edge(item.v, item.u, item.val);
            if(dis[item.u][item.v] > item.val) ans += item.val;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

