    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

pair<Weight, Edges> Kruskal(const Graph &g) {
	int n = g.size();
	UnionFind uf(n);
	priority_queue<Edge> Q;
	for (int u = 0; u < n; u++)
		for (__typeof(g[u].begin()) e = g[u].begin(); e != g[u].end(); e++)
			if (u < e->dst)
				Q.push(*e);

	Weight total = 0;
	Edges F;
	while (F.size() < n - 1 && !Q.empty()) {
		Edge e = Q.top();
		Q.pop();
		if (uf.unionSet(e.src, e.dst)) {
			F.push_back(e);
			total += e.weight;
		}
	}
	return pair<Weight, Edges>(total, F);
}

ll WarshallFloyd(const Matrix &g,Matrix &dist) {
    int n = (int)g.size();
    ll ret=0;
    dist = g;
    vector<vector<bool> >isused(n,vector<bool>(n,false));
    repeat(k, n) repeat(i, n) repeat(j, n) {
      if(k==i || k==j) continue;
        if(dist[i][k] == INF || dist[k][j] == INF) continue;
        if(!isused[i][j] && dist[i][j] == dist[i][k] + dist[k][j]){
          ret-=dist[i][j];
          isused[i][j] = true;
          isused[j][i] = true;
        }
        if (dist[i][j] > dist[i][k] + dist[k][j]) {
          return -1;
        }
    }
    repeat(i,n){
      for(int j=i+1;j<n;j++){
        ret += dist[i][j];
      }
    }
    return ret;
}

