bool canpose(ll num, const vector<ll>& ans, int pos, int& cnt) {
	//if (m.count(num)) return m[num];
	if (num < ans[pos]) {
		return false;
	}
	if (num == ans[pos]) {
		cnt++;
		return true;
	}
	if (pos + 1 < ans.size() && canpose(num, ans, pos + 1, cnt)) {
		return true;
	}
	if (pos + 1 < ans.size() && canpose(num - ans[pos], ans, pos + 1, cnt)) {
		cnt++;
		return true;
	}
	return false;
}

