			}
		}
		else
		{
			dsu.merge(u,v);
			ans+=w;
			H.addedge(u,v,w);
		}
	}
	H.Floyd();
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<n;j++)
		{
			if(H.d[i][j]!=a[i][j])
			{
				cout<<-1<<'\n';
				return 0;
			}
		}
	}
