    if(par[x] == x) return x;
    return (par[x] = root(par[x]));
  }

  bool find(int x,int y){
    return root(x) == root(y);
  }

  void set(int x,int y){
    x = root(x);
    y = root(y);

    if(x == y)return;

    if(size[x] > size[y]){
      par[y] = par[x];
      size[x] += size[y];
    }else{
      par[x] = par[y];
      size[y] += size[x];
    }

