LL dijkstra(LL s,LL e){
    vector<bool> close(n+1,false);
    priority_queue<point,vector<point>,greater<point>> pq;
    pq.push(point{s,0});
    while(!pq.empty()){
        point tmp = pq.top();
        pq.pop();
        if(close[tmp.i]){
            continue;
        }
        close[tmp.i] = true;
        if(tmp.i == e){
            return tmp.c;
        }
        for(int i = 0; i < v[tmp.i].size(); i++){
            if(v[tmp.i][i].v1 == tmp.i){
                if(!close[v[tmp.i][i].v2]){
                    pq.push(point{v[tmp.i][i].v2,v[tmp.i][i].cost + tmp.c});
                }
            }else{
                if(!close[v[tmp.i][i].v1]){
                    pq.push(point{v[tmp.i][i].v1,v[tmp.i][i].cost + tmp.c});
                }
            }
        }
    }
    return -1;
}

