ll dis(int s,int t){
    ll mind[n];for(int i=0;i<=n-1;i++)mind[i]=INF;
    mind[s]=0;
    queue<ll>q;q.push(s);
    while(!q.empty()){
        ll top=q.front();q.pop();
        for(auto x:v[top]){
            ll y=x.first,dist=x.second;
            if(dist+mind[top]<mind[y]){
                mind[y]=mind[top]+dist;
                q.push(y);
            }
        }
    }
    return mind[t];
}

