void copy() {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      dp[i][j] = d[i][j];
    }
  }
}

void warshall_floyd() {
  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = i; j < n; j++) {
        if (i != k && k != j && d[i][j] >= d[i][k] + d[k][j]) {
          summinus += d[i][j];
        }
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
}

