						if(d[j][k]==-1||d[j][u]+d[k][v]+w<d[j][k])
						{
							d[j][k]=d[j][u]+d[k][v]+w;
						}
					}
					if(d[j][v]!=-1&&d[k][u]!=-1)
					{
