						{
							d[j][k]=d[j][v]+d[k][u]+w;
						}
					}
				}
			}
			res+=w;
		}
		else if(d[u][v]<w)
		{
			cout<<"-1\n";
			return;
		}
	}
	cout<<res<<"\n";
}

