ll dist[302][302];
ll dist_backup[302][302];

struct edge{
    int a, b, cost;
    edge(int a, int b, int cost): a(a), b(b), cost(cost) {}
    bool operator<(const edge& right) const {
        return cost < right.cost;
    }
};

int main(){
    int N;
    cin >> N;

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            cin >> dist[i][j];
            dist_backup[i][j] = dist[i][j];
        }
    }

    for(int k=0;k<N;k++){
        for(int i=0;i<N;i++){
            for(int j=0;j<N;j++){
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }

    vector<edge> E;
    for(int i=0;i<N;i++){
        for(int j=i+1;j<N;j++){
            if(dist[i][j] != dist_backup[i][j]){
                cout << -1 << endl;
                return 0;
            }
            E.emplace_back(i, j, dist[i][j]);
            dist[i][j] = INF;
        }
    }

    for(int i=0;i<N;i++){
        dist[i][i] == 0;
    }

    sort(E.begin(), E.end());
    ll ans = 0;
    for(edge e : E){
        if(dist[e.a][e.b] <= e.cost) continue;
        ans += e.cost;
        dist[e.a][e.b] = e.cost;
        dist[e.a][e.b] = e.cost;
        for(int i=0;i<N;i++){
            for(int j=i+1;j<N;j++){
                dist[i][j] = min(dist[i][j], dist[i][e.a] + e.cost + dist[e.b][j]);
                dist[i][j] = min(dist[i][j], dist[i][e.b] + e.cost + dist[e.a][j]);
                dist[j][i] = dist[i][j];
            }
        }
    }

    cout << ans << endl;

    return 0;
}

