using namespace std;

int n;
long long dist[305][305];
long long aux[305][305];

long long look_up(int i, int j) {
    if (i == j) return 0;

    for (int k = 1; k <= n; ++k) {
        if (dist[i][k] + dist[k][j] == dist[i][j] && i != k && j != k) {
            return look_up(i, k) - dist[k][j];
        }
    }

    return dist[i][j];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cin >> dist[i][j];
            aux[i][j] = 0LL;
        }
    }

    for (int k = 1; k <= n; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    cout << -1;
                    return 0;
                }
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i != j) aux[i][j] = look_up(i, j);
        }
    }

    long long sum = 0LL;

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            sum += aux[i][j];

    cout << sum / 2LL;

    return 0;
}

