ll mdd(ll x, ll y){
	fill(md, md + MN, inf);
	md[x] = 0;
	pq.push({x, 0});
	while(!pq.empty()){
		ASDF cur = pq.top();
		pq.pop();
		for(auto &i : e[cur.x]){
			ll cnd = cur.y + i.y;
			if(cnd < md[i.x]){
				md[i.x] = cnd;
				pq.push({i.x, cnd});
			}
		}
	}
	return md[y];
}

