int V;
vector<vector<ll>> G;
vector<vector<ll>> d;

void warshall_floyd() {
	for (int k = 0; k < V; k++)
		for (int i = 0; i < V; i++)
			for (int j = 0; j < V; j++)
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> V;
	G.resize(V, vector<ll>(V));
	cin >> G;
	d = G;

	warshall_floyd();

	for (int i = 0; i < V; i++) {
		for (int j = 0; j < V; j++) {
			if (G[i][j] != d[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	ll ans = 0;
	// 辺 (i, j) を残すかどうか
	for (int i = 0; i < V - 1; i++) {
		for (int j = i + 1; j < V; j++) {
			ll cost = d[i][j];
			// k を経由した経路で cost と等しいものが存在するなら辺 (i, j) は必要ない
			bool equal = false;
			for (int k = 0; k < V; k++) {
				if (k == i || k == j)
					continue;
				if (cost == d[i][k] + d[k][j]) {
					equal = true;
					break;
				}
			}
			if (!equal)
				ans += cost;
		}
	}

	cout << ans << endl;

	return 0;
}

