void solve() {
  ll n; cin >> n;

  ll mat[n][n];
  f0r(i, n) f0r(j, n) cin >> mat[i][j];

  ll v = n * (n - 1) / 2;
  pair<ll, pll> dists[v];
  ll c = 0;
  f0r(i, n) f0r(j, i) {
    dists[c++] = mp(mat[i][j], mp(i, j));
  }
  sort(dists, dists + v);

  ll ans = 0;
  f0r(i, v) {
    pair<ll, pll> k = dists[i];
    pll p = k.s;
