        cout << -1 << '\n';
        return;
      } else if (mat[p.f][j] + mat[j][p.s] == mat[p.f][p.s]) {
        cur = 1;
      }
    }
    if (!cur) ans += mat[p.f][p.s];
  }
  cout << ans << '\n';
}

