template <typename Edge, typename T>
void Dijkstra(const vector<vector<Edge>>& edge, int s, vector<T>& d) {
    using P = pair<T, int>;
    priority_queue<P, vector<P>, greater<P>> q;
    d[s] = 0;
    q.emplace(0, s);
    while (q.size()) {
        T dist;
        int v;
        tie(dist, v) = q.top();
        q.pop();
        if (d[v] < dist) continue;
        for (auto&& e : edge[v]) {
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                q.emplace(d[e.to], e.to);
            }
        }
    }
}
template <typename T>
void WarshallFloyd(vector<vector<T>>& link) {
    int N = link.size();
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                link[i][j] = min(link[i][j], link[i][k] + link[k][j]);
            }
        }
    }
}

