struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   Int dist[312][312];
   Int dist2[312][312];
   void solve() {
      Int n; scan(n);
      for(Int i = 0; i < n; ++i) {
         for(Int k = 0; k < n; ++k) {
            Int t; scan(t);
            dist[i][k] = dist2[i][k] = t;
         }
      }
      for(Int k = 0; k < n; ++k) {
         for(Int i = 0; i < n; ++i) {
            for(Int j = 0; j < n; ++j) {
               dist[i][j] = std::min(dist[i][j], dist[i][k] + dist[k][j]);
            }
         }
      }
      bool res = true;
      Int total = 0;
      for(Int i = 0; i < n; ++i) {
         for(Int k = 0; k < n; ++k) {
            if( dist[i][k] != dist2[i][k] ) res = false;
            if( dist[i][k] != dist[k][i] ) res = false;
            total += dist[i][k];
         }
      }
      if( not res ) {
         puts("-1");
         return;
      }
      dumpl(total);
      dumpl(total / n - 1);
      Int w = 0;
      for(Int i = 0; i < n; ++i) {
         for(Int j = 0; j < i; ++j) {
            bool b = true;
            for(Int k = 0; k < n; ++k) {
               if( i == k or j == k ) continue;
               if( dist[i][j] == dist[i][k] + dist[k][j] ) b = false;
            }
            if( b ) w += dist[i][j];
         }
      }
      printf("%ld\n", w);
   }
};

