  int n; cin >> n;
  priority_queue<Edge> v;
  Graph graph(n);
  ll tmp;
  REP(i, n) {
    REP(j, n) {
      cin >> tmp;
      if(i != j) v.push(Edge(i, j, tmp));
    }
  }

  ll ans = 0;

  REP(i, SZ(v)) {
    int from = v.top().from, to = v.top().to, cost = v.top().cost; v.pop();
    vector<int> d = dijkstra(graph, from);
    if(cost < d[to]) {
      ans += cost;
      graph[from].pb(Edge(from, to, cost));
      graph[to].pb(Edge(to, from, cost));
    } else if(cost > d[to]) {
      cout << -1 << endl;
      return 0;
    }
  }

  cout << ans << endl;

}

