int calcDist(int a, int b) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
        vis[i] = false;
    }
    priority_queue<pair<int, int> > Q;
    dist[a] = 0;
    Q.push({0, a});
    while (!Q.empty()) {
        int w = Q.top().second;
        Q.pop();
        if (vis[w]) continue;
        vis[w] = true;
        for (auto e : V[w]) {
            int u = e.first;
            int kr = e.second;
            if (dist[u] > dist[w] + kr) {
                dist[u] = dist[w] + kr;
                Q.push({-dist[u], u});
            }
        }
    }
    return dist[b];
}

int ans;
void addEdge(int a, int b, int dist) {
    V[a].push_back({b, dist});
    V[b].push_back({a, dist});
    ans += dist;
}

