        }

    sort(e.begin(), e.end());

    for (auto p : e) {
        int u = p.S.F;
        int v = p.S.S;
        int w = p.F;
        int len = dijkstra(u, v);
        if ((len != -1 && len < w) || (len > w && c[u][v])) {
            cout << -1;
            return 0;
        }
        if (len != w) {
            c[u][v] = c[v][u] = w;
            res += w;
            adj[u].PB(MP(v, w));
            adj[v].PB(MP(u, w));
        }
    }

    cout << res;
}

