void WF(int dp[N][N]){

  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++) if(i!=j && dp[i][j] == 0) dp[i][j] = INF;

  for(int k=0;k<n;k++)
    for(int i=0;i<n;i++)
      for(int j=0;j<n;j++) Min(dp[i][j],dp[i][k]+dp[k][j]);

  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++) if(dp[i][j] == INF) dp[i][j] = 0;

}

bool same(int a[N][N],int b[N][N]){
  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++) if(a[i][j]!=b[i][j]) return 0;
  return 1;
}

void cp(int from[N][N],int to[N][N]){
  for(int i=0;i<n;i++)
    for(int j=0;j<n;j++) to[i][j] = from[i][j];
}

