    val queue = PriorityQueue<Edge>( kotlin.Comparator { e1, e2 ->
        if ( e1.d != e2.d ) return@Comparator Integer.compare( e1.d, e2.d )
        if ( e1.u != e2.u ) return@Comparator Integer.compare( e1.u, e2.u )
        return@Comparator Integer.compare( e1.v, e2.v )
    } )
    for ( i in 0 until n ) {
