            e[i][j] = st.nextInt()
            if ( i < j ) queue.add( Edge( i, j, e[i][j] ) )
        }
    }
    val dist = Array( n, { LongArray( n, { Long.MAX_VALUE / 4 } ) } )
    for ( i in 0 until n ) dist[i][i] = 0
    var r = 0L
    while ( queue.isNotEmpty() ) {
        val edge = queue.poll()
        if ( dist[edge.u][edge.v] < edge.d ) {
            println( -1 )
            return
        }
        if ( dist[edge.u][edge.v] > edge.d ) {
            r += edge.d
            for ( i in 0 until n ) {
                for ( j in 0 until n ) {
                    dist[i][j] = Math.min( dist[i][j],
                            Math.min(
                                    dist[i][edge.u] + edge.d + dist[edge.v][j],
