// Reads multiple ints in a line, separate by a space.
// It works even if the actual number of ints is smaller than n.
// WARNING: This function does not work for -2^31.
// NOTE: This function does not handle error cases.
fun fastReadInts(n: Int): IntArray {
  val xs = IntArray(n)
  val s = readLine()!!
  var currentValue = 0
  var isNegative = false
  var currentIndex = 0
  for (c in s) {
    if (c == ' ') {
      xs[currentIndex] = currentValue * if (isNegative) -1 else 1
      currentValue = 0
      isNegative = false
      currentIndex++
    } else if (c == '-') {
      isNegative = true
    } else {
      currentValue *= 10
      currentValue += c - '0'
    }
  }
  xs[currentIndex] = currentValue * if (isNegative) -1 else 1
  return xs
}

fun main(args: Array<String>) {
  val n = readLine()!!.toInt()
  val matrix = Array(n, { fastReadInts(n) })
  for (x in 0 until n) {
    for (y in 0 until n) {
      for (z in 0 until n) {
        if (x == y || x == z || y == z) continue
        if (matrix[x][y] + matrix[y][z] < matrix[x][z]) {
          println(-1)
          return
        }
      }
    }
  }

  var ans = 0L
  for (x in 0 until n) {
    for (y in x + 1 until n) {
      val removable = (0 until n).filter { p -> p != x && p != y }
          .any { p -> matrix[x][p] + matrix[p][y] == matrix[x][y] }
      if (!removable) {
        ans += matrix[x][y]
      }
    }
  }
  println(ans)
}

