			for (int j = 0; j < n; j++) {
				map[i][j] = sc.nextInt();
			}
		}
		System.out.println(helper(map));

	}

	private static long helper(long[][] map) {
		// TODO Auto-generated method stub

		if (!floyd(map))
			return -1;
		int[] dis = new int[map.length];
		Map<Integer, Set<Integer>> m = new HashMap<Integer, Set<Integer>>();
		for (int i = 0; i < map.length; i++) {
			Set<Integer> tmp = new HashSet();
			tmp.add(i);
			m.put(i, tmp);
		}
		List<a> l = new ArrayList<a>();
		for (int i = 0; i < map.length; i++)
			for (int j = i + 1; j < map.length; j++)
				l.add(new a(i, j, map[i][j]));
		List<a> l1 = new ArrayList<a>();
		Collections.sort(l, (a, b) -> (int)a.length -(int) b.length);
		long count = 0;
		for (int i = 0; i < l.size(); i++) {
			a tmp = l.get(i);


			if (!(m.get(tmp.p1).contains(tmp.p2))) {
				l1.add(tmp);
				count += tmp.length;
				Set<Integer> tmps = m.get(tmp.p1);
				tmps.addAll(m.get(tmp.p2));
				for (int value : tmps) {
					m.put(value, tmps);
				}
				m.put(tmp.p2, m.get(tmp.p1));
			} else {
				long tmpi = longest(tmp, l1);

				if (map[tmp.p1][tmp.p2] < tmpi)
					count += map[tmp.p1][tmp.p2];
				l1.add(tmp);
			}

		}

		return count;
	}

	private static long longest(a tmp, List<a> l1) {
		// TODO Auto-generated method stub
		long[][] tmpmap = new long[map.length][map.length];
		for(int i=0;i<map.length;i++)
			for(int j=0;j<map.length;j++)
				tmpmap[i][j]=Integer.MAX_VALUE;
		for (a aa : l1){
			tmpmap[aa.p1][aa.p2] = aa.length;
			tmpmap[aa.p2][aa.p1]=aa.length;
		}
		floyd2(tmpmap);

		return tmpmap[tmp.p1][tmp.p2];
	}

	private static boolean floyd(long[][] map) {
		// TODO Auto-generated method stub
		for (int i = 0; i < map.length; i++) {
			for (int j = 0; j < map.length; j++) {
				for (int k = 0; k < map.length; k++) {
					if (k != i && k != j) {
						if (map[i][k] + map[k][j] < map[i][j])
							return false;
					}
				}
			}
		}
		return true;
	}
	private static void floyd2(long[][] map) {
		// TODO Auto-generated method stub
		for (int i = 0; i < map.length; i++) {
			for (int j = 0; j < map.length; j++) {
				for (int k = 0; k < map.length; k++) {
					if (k != i && k != j) {
						if (map[i][k] + map[k][j] < map[i][j])
							map[i][j]=map[i][k] + map[k][j];
					}
				}
			}
		}

	}

