/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        DRestoringRoadNetwork solver = new DRestoringRoadNetwork();
        solver.solve(1, in, out);
        out.close();
    }

    static class DRestoringRoadNetwork {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int n = in.ints();
            int[][] a = in.ints(n, n);
            boolean[][] used = new boolean[n][n];
            ArrayUtil.fill(used, true);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i == j || j == k) continue;
                        if (a[i][j] + a[j][k] < a[i][k]) {
                            out.ans(-1).ln();
                            return;
                        } else if (a[i][j] + a[j][k] == a[i][k]) {
                            used[i][k] = false;
                        }
                    }
                }
            }
            long ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    if (used[i][j]) ans += a[i][j];
                }
            }
            out.ans(ans).ln();
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(long l) {
            return ans(Long.toString(l));
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static final class ArrayUtil {
        private ArrayUtil() {
        }

        public static void fill(boolean[] a, boolean v) {
            Arrays.fill(a, v);
        }

        public static void fill(boolean[][] a, boolean v) {
            for (int i = 0; i < a.length; i++) {
                fill(a[i], v);
            }
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public int[] ints(int length) {
            return IntStream.range(0, length).map(x -> ints()).toArray();
        }

        public int[][] ints(int height, int width) {
            return IntStream.range(0, height).mapToObj(x -> ints(width)).toArray(int[][]::new);
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    long[][] A;
    PriorityQueue<Edge> es;
    long[][] dp;
    final static long INF = 1000000007;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        es = new PriorityQueue<>((e1, e2) -> Long.compare(e1.cost, e2.cost));
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in)
        )) {
            String line = br.readLine();
            String[] elems;
            n = Integer.parseInt(line);
            A = new long[n][n];
            for (int i = 0; i < n; i++) {
                elems = br.readLine().split(" ");
                for (int j = 0; j < n; j++) {
                    A[i][j] = Long.parseLong(elems[j]);
                    if (j < i)
                        es.add(new Edge(i, j, A[i][j]));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void solve() {
        dp = new long[n][n];
        for (int i = 0; i < n; i++)
            dp[i] = Arrays.copyOf(A[i], n);
        upd(dp);
        long ret = 0L;
        while (!es.isEmpty()) {
            Edge e = es.poll();
            if (e.cost > dp[e.a][e.b]) {
                es.add(e);
                break;
            }
            else {
                if (!check(e.a, e.b)) {
                    ret += dp[e.a][e.b];
                }
            }
        }
        if (!es.isEmpty()) {
            System.out.println(-1);
        }
        else {
            System.out.println(ret);
        }
    }

    private void upd(long[][] arr) {
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++)
                    arr[i][j] = Math.min(arr[i][j],
                            arr[i][k] + arr[k][j]);
            }
        }
    }

    private boolean check(int u ,int v) {
        boolean ret = false;
        for (int i = 0; i < n; i++)
            if (i != u && i != v)
                ret |= dp[u][v] == dp[u][i] + dp[i][v];
        return ret;
    }

    private void print(long[][] array) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (array[i][j] == INF)
                    System.out.printf("INF ");
                else
                    System.out.printf("%2d ", array[i][j]);
            }
            System.out.println();
        }
    }

    private class Edge {
        int a, b;
        long cost;
        Edge (int a, int b, long c) {
            this.a = a;
            this.b = b;
            this.cost = c;
        }

        @Override
        public String toString() {
            return String.format("%3d <-> %3d: %d", a, b, cost);
        }
    }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[][] a = new int[n][n];
		boolean enable = true;
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				a[i][j] = sc.nextInt();
			}
		}
		sc.close();

		int[][] wf = new int[n][n];
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				wf[i][j] = a[i][j];
			}
		}

		for(int k=0; k<n; k++){
			for(int i=0; i<n; i++){
				for(int j=0; j<n; j++){
					if(wf[i][j] > wf[i][k]+wf[k][j]){
						enable = false;
					}
				}
			}
		}
		boolean[][] remove = new boolean[n][n];

		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				remove[i][j] = false;
			}
		}

		for(int k=0; k<n; k++){
			for(int i=0; i<n; i++){
				for(int j=0; j<n; j++){
					if(wf[i][j] != 0 && wf[i][j] >= wf[i][k]+wf[k][j] && k!=i && k!=j){
						remove[i][j] = true;
					}
				}
			}
		}

		long sum = 0;

		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				if(!remove[i][j]){
					sum += wf[i][j];
				}
			}
		}

		if(!enable){
			System.out.println("-1");
		}else{
			System.out.println("" + sum/2);
		}

	}
}

