import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author silviase
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DRestoringRoadNetwork solver = new DRestoringRoadNetwork();
        solver.solve(1, in, out);
        out.close();
    }

    static class DRestoringRoadNetwork {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            // 残っている道の中で最小の道が正しい道としてやる
            // だから道を一応並べ替える必要がある？
            // 安い順に道を見て行って矛盾があれば・・みたいな
            //　どういう順番に更新していけばいいんだろう…
            // O(N^2)で更新ができそう
            // 矛盾ってどう見つけるんだろう
            // たとえば i->j , cost:cについて
            // i->k, k->jで道が存在してcost < c => 矛盾
            // i->k, k->jでの道すべてに対してcost > c => 矛盾しない、直接結ぶ道が必要
            // i->k, k->jで道が存在してcost = c => 矛盾しないが、道は必要ない
            // それでよさそう
            int n = in.nextInt();
            int[][] remTable = new int[n][n];
            long ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    remTable[i][j] = in.nextInt();
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    // 各道(i->j)について考える
                    boolean need = true;
                    for (int k = 0; k < n; k++) {
                        if (i == k || k == j) continue;
                        // i = 0
                        // j = 2
                        if (remTable[i][j] > remTable[i][k] + remTable[k][j]) {
                            // 矛盾
                            ans = -1;
                            break;
                        } else if (remTable[i][j] == remTable[i][k] + remTable[k][j]) {
                            need = false;
                        }
                    }
                    if (ans == -1) continue;
                    if (need) {
                        ans += remTable[i][j];
                    }
                }
            }
            out.println(ans);


        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    static long MOD = 1000000007;

    static public void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        long[][] arrs = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                arrs[i][j] = sc.nextLong();
            }
        }

        List<Vertex> vertexs = new ArrayList<>();
        List<Edge> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            vertexs.add(new Vertex(i));
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long d = arrs[i][j];
                if (d > 0) {
                    edges.add(new Edge(String.valueOf(i), vertexs.get(i), vertexs.get(j), d));
                }
            }
        }

        Graph graph = new Graph(vertexs, edges);
        WarshallFloydAlgorithm warshallFloydAlgorithm = new WarshallFloydAlgorithm(graph);
        long[][] warshallResutls = warshallFloydAlgorithm.execute();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (i != j && warshallResutls[i][j] != arrs[i][j]) {
                    System.out.println(-1);
                    System.exit(0);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long longest = Long.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    long distance = warshallResutls[i][k] + warshallResutls[k][j];
                    if (i != k && j != k && distance < longest) {
                        longest = distance;
                    }
                }

                if (longest == warshallResutls[i][j]) {
                    warshallResutls[i][j] = 1000000000L;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (warshallResutls[i][j] != 1000000000L) {
                    ans += warshallResutls[i][j];
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.println(Arrays.toString(warshallResutls[i]));

        }

        System.out.println(ans);
    }

    static private class WarshallFloydAlgorithm {

        private final List<Vertex> vertexes;
        private final List<Edge> edges;
        private final long INF = 1000000000L;

        public WarshallFloydAlgorithm(Graph graph) {
            this.vertexes = new ArrayList<>(graph.getVertices());
            this.edges = new ArrayList<>(graph.getEdges());
        }

        public long[][] execute() {
            int n = vertexes.size();

            long[][] distances = new long[n][n];
            for (long[] row : distances)
                Arrays.fill(row, INF);

            for (Edge edge : this.edges) {
                distances[edge.getSource().getId()][edge.getDestination().getId()] = edge.getWeight();
                distances[edge.getDestination().getId()][edge.getSource().getId()] = edge.getWeight();
            }

            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        long d = distances[i][k] + distances[k][j];
                        if (d < distances[i][j])
                            distances[i][j] = d;
                    }
                }
            }

            return distances;
        }
    }

    static private class Graph {
        private final List<Vertex> vertices;
        private final List<Edge> edges;

        public Graph(List<Vertex> vertices, List<Edge> edges) {
            this.vertices = vertices;
            this.edges = edges;
        }


        public List<Vertex> getVertices() {
            return this.vertices;
        }

        public List<Edge> getEdges() {
            return this.edges;
        }
    }

    static private class Edge {
        private final String id;
        private final Vertex source;
        private final Vertex destination;
        private final long weight;

        public Edge(String id, Vertex source, Vertex destination, long weight) {
            this.id = id;
            this.source = source;
            this.destination = destination;
            this.weight = weight;
        }

        public String getId() {
            return this.id;
        }

        public Vertex getDestination() {
            return this.destination;
        }

        public Vertex getSource() {
            return this.source;
        }

        public long getWeight() {
            return this.weight;
        }

        @Override
        public String toString() {
            return "weight: " + this.weight + ", " + this.source.toString() + "," + this.destination.toString();
        }
    }

    static private class Vertex {
        final private int id;

        public Vertex(int id) {
            this.id = id;
        }

        public int getId() {
            return this.id;
        }

        @Override
        public int hashCode() {
            return this.id;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null) return false;
            if (getClass() != obj.getClass()) return false;
            Vertex other = (Vertex) obj;
            return this.getId() == other.getId();
        }

        @Override
        public String toString() {
            return "id: " + this.id;
        }
    }
}

