	public void solveD() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long[][] A = new long[N][];
		for (int i = 0; i < N; i++) {
			A[i] = new long[N];
			for (int j = 0; j < N; j++) {
				A[i][j] = sc.nextLong();
			}
		}
		for (int k = 0; k < N; k++) {
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					if (A[i][j] > A[i][k] + A[k][j]) {
						System.out.println(-1);
						return;
					}
				}
			}
		}
		long ans = 0L;
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				boolean isEqual = false;
				for (int k = 0; k < N; k++) {
					if (k == i || k == j) {
						continue;
					}
					if (A[i][j] == A[i][k] + A[k][j]) {
						isEqual = true;
					}
				}
				if (!isEqual) {
					ans += A[i][j];
				}
			}
		}
		System.out.println(ans / 2);
	}

