                  if(d[i][j] > d[i][k] + d[k][j]){
                      return -1;
                  } else if (d[i][j] == d[i][k] + d[k][j]) {
                    use[i][j] ++;
                  }
              }
          }
      }

      long ret = 0;
      for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
          if (use[i][j] < 3) {
            ret += d[i][j];
          }
        }
      }
      return ret;
  }


