import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	private void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int[][] edge = new int[N][N];
		PriorityQueue<Edge> que = new PriorityQueue<>();
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				edge[i][j] = in.nextInt();
				if(i != j){
					que.add(new Edge(i,j,edge[i][j]));
				}
			}
		}
		boolean[][] valiable = new boolean[N][N];
		long sum = 0;

		while(!que.isEmpty()) {
			Edge e = que.poll();
			if(valiable[e.x][e.y]) continue;
			sum += e.l;
			if(edge[e.x][e.y] != edge[e.y][e.x]){
				System.out.println(-1);
				return;
			}
			valiable[e.x][e.y] = true;
			valiable[e.y][e.x] = true;
			for (int i = 0; i < N; i++) {
				if((long)(edge[e.x][i]) + e.l < edge[e.y][i] ||
				   (long)(edge[e.y][i]) + e.l < edge[e.x][i]) {
					System.out.println(-1);
					return;
				}
				if(valiable[e.x][i] && edge[e.y][i] == (long)(edge[e.x][i]) + e.l){
					valiable[e.y][i] = true;
					valiable[i][e.y] = true;
				}
				if(valiable[e.y][i] && edge[e.x][i] == (long)(edge[e.y][i]) + e.l){
					valiable[e.x][i] = true;
					valiable[i][e.x] = true;
				}
			}
		}
		System.out.println(sum);
	}

	public static void main(String[] args) {
		new Main().solve();
	}

	class Edge implements Comparable<Edge>{
		int x,y,l;
		public Edge(int x,int y,int l) {
			this.x = x;
			this.y = y;
			this.l = l;
		}
		@Override
		public int compareTo(Edge o) {
			return Integer.compare(l, o.l);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    long[][] A;
    PriorityQueue<Edge> es;
    long[][] ans;
    long[][] dp;
    final static long INF = 1000000007;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        es = new PriorityQueue<>((e1, e2) -> Long.compare(e1.cost, e2.cost));
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in)
        )) {
            String line = br.readLine();
            String[] elems;
            n = Integer.parseInt(line);
            A = new long[n][n];
            for (int i = 0; i < n; i++) {
                elems = br.readLine().split(" ");
                for (int j = 0; j < n; j++) {
                    A[i][j] = Long.parseLong(elems[j]);
                    if (j < i)
                        es.add(new Edge(i, j, A[i][j]));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void solve() {
        ans = new long[n][n];
        dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(ans[i], INF);
            Arrays.fill(dp[i], INF);
            ans[i][i] = dp[i][i] = 0;
        }
        Edge firstEdge = es.poll();
        add(firstEdge);
        while (!es.isEmpty()) {
            Edge e = es.poll();
            if (e.cost == dp[e.a][e.b])
                continue;
            if (e.cost > dp[e.a][e.b]) {
                es.add(e);
                break;
            }
            else
                add(e);
        }
        if (!es.isEmpty()) {
            System.out.println(-1);
        }
        else {
            long ret = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= i; j++)
                    if (ans[i][j] != INF)
                        ret += ans[i][j];
            }
            System.out.println(ret);
        }
    }

    private void add(Edge e) {
        ans[e.a][e.b] = ans[e.b][e.a] = e.cost;
        for (int i = 0; i < n; i++) {
            dp[i][e.b] = dp[e.b][i] =
                    Math.min(dp[i][e.b], dp[i][e.a] + e.cost);
            dp[i][e.a] = dp[e.a][i] =
                    Math.min(dp[i][e.a], dp[i][e.b] + e.cost);
        }
    }

    private void print() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (ans[i][j] == INF)
                    System.out.printf("INF ");
                else
                    System.out.printf("%2d ", ans[i][j]);
            }
            System.out.println();
        }
    }

    private class Edge {
        int a, b;
        long cost;
        Edge (int a, int b, long c) {
            this.a = a;
            this.b = b;
            this.cost = c;
        }

        @Override
        public String toString() {
            return String.format("%3d <-> %3d: %d", a, b, cost);
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    static long MOD = 1000000007;
    static final long INF = 10000000000L;

    static public void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        long[][] arrs = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                arrs[i][j] = sc.nextLong();
            }
        }

        List<Vertex> vertexs = new ArrayList<>();
        List<Edge> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            vertexs.add(new Vertex(i));
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long d = arrs[i][j];
                if (d > 0) {
                    edges.add(new Edge(String.valueOf(i), vertexs.get(i), vertexs.get(j), d));
                }
            }
        }

        Graph graph = new Graph(vertexs, edges);
        WarshallFloydAlgorithm warshallFloydAlgorithm = new WarshallFloydAlgorithm(graph);
        long[][] warshallResutls = warshallFloydAlgorithm.execute();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (i != j && warshallResutls[i][j] != arrs[i][j]) {
                    System.out.println(-1);
                    System.exit(0);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long longest = Long.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    long distance = warshallResutls[i][k] + warshallResutls[k][j];
                    if (i != k && j != k && distance < longest) {
                        longest = distance;
                    }
                }

                if (longest == warshallResutls[i][j]) {
                    warshallResutls[i][j] = INF;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (warshallResutls[i][j] != INF) {
                    ans += warshallResutls[i][j];
                }
            }
        }

        System.out.println(ans);
    }

    static private class WarshallFloydAlgorithm {

        private final List<Vertex> vertexes;
        private final List<Edge> edges;

        public WarshallFloydAlgorithm(Graph graph) {
            this.vertexes = new ArrayList<>(graph.getVertices());
            this.edges = new ArrayList<>(graph.getEdges());
        }

        public long[][] execute() {
            int n = vertexes.size();

            long[][] distances = new long[n][n];
            for (long[] row : distances)
                Arrays.fill(row, INF);

            for (Edge edge : this.edges) {
                distances[edge.getSource().getId()][edge.getDestination().getId()] = edge.getWeight();
                distances[edge.getDestination().getId()][edge.getSource().getId()] = edge.getWeight();
            }

            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        long d = distances[i][k] + distances[k][j];
                        if (d < distances[i][j])
                            distances[i][j] = d;
                    }
                }
            }

            return distances;
        }
    }

    static private class Graph {
        private final List<Vertex> vertices;
        private final List<Edge> edges;

        public Graph(List<Vertex> vertices, List<Edge> edges) {
            this.vertices = vertices;
            this.edges = edges;
        }


        public List<Vertex> getVertices() {
            return this.vertices;
        }

        public List<Edge> getEdges() {
            return this.edges;
        }
    }

    static private class Edge {
        private final String id;
        private final Vertex source;
        private final Vertex destination;
        private final long weight;

        public Edge(String id, Vertex source, Vertex destination, long weight) {
            this.id = id;
            this.source = source;
            this.destination = destination;
            this.weight = weight;
        }

        public String getId() {
            return this.id;
        }

        public Vertex getDestination() {
            return this.destination;
        }

        public Vertex getSource() {
            return this.source;
        }

        public long getWeight() {
            return this.weight;
        }

        @Override
        public String toString() {
            return "weight: " + this.weight + ", " + this.source.toString() + "," + this.destination.toString();
        }
    }

    static private class Vertex {
        final private int id;

        public Vertex(int id) {
            this.id = id;
        }

        public int getId() {
            return this.id;
        }

        @Override
        public int hashCode() {
            return this.id;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null) return false;
            if (getClass() != obj.getClass()) return false;
            Vertex other = (Vertex) obj;
            return this.getId() == other.getId();
        }

        @Override
        public String toString() {
            return "id: " + this.id;
        }
    }
}

