                {
                    for (int b = 0; b * B * 100 <= F; ++b)
                    {
                        var v = (a * A + b * B) * 100;
                        if(!hashAB.Contains(v) && v>0 && v <= F)
                        {
                            hashAB.Add(v);
                        }
                    }
                }
                var hashCD = new HashSet<int>();
                for (int c = 0; c * C <= F; ++c)
                {
                    for (int d = 0; d * D <= F; ++d)
                    {
                        var v = (c * C + d * D);
                        if (!hashCD.Contains(v) && v <= F)
                        {
                            hashCD.Add(v);
                        }
                    }
