                int maxAB = 0, maxCD = 0;
                foreach(var water in hashAB)
                {
                    foreach(var suger in hashCD)
                    {
                        if (water / 100 * E < suger) { continue; }
                        if (water + suger > F) { continue; }
                        var node = 1.0 * suger / (water + suger);
                        if (node > max)
                        {
