                long total = 0;
                for(int i = 0; i < N; ++i)
                {
                    for(int j = i + 1; j < N; ++j)
                    {
                        bool hasAnotherPath = false;
                        for (int k = 0; k < N; ++k)
                        {
                            if (i != k && j != k && Dist[i, k] + Dist[k, j] == Dist[i, j]) { hasAnotherPath = true; break; }
