        class Util
        {
            public static long[] ASum(long[] array)
            {
                var res = new long[array.Length + 1];
                for (int i = 0; i < array.Length; ++i)
                {
                    res[i + 1] = res[i] + array[i];
                }
                return res;
            }
            public static T[,] Dup<T>(T[,] matrix)
            {
                var n0 = matrix.GetLength(0);
                var n1 = matrix.GetLength(1);
                var m = new T[n0, n1];
                for (int i = 0; i < n0; ++i)
                {
                    for (int j = 0; j < n1; ++j)
                    {
                        m[i, j] = matrix[i, j];
                    }
                }
                return m;
            }
            public static void WarshallFloyd(long[,] dist)
            {
                var N = dist.GetLength(0);
                for (int k = 0; k < N; ++k)
                {
                    for (int i = 0; i < N; ++i)
                    {
                        for (int j = 0; j < N; ++j)
                        {
                            dist[i, j] = Math.Min(dist[i, j], dist[i, k] + dist[k, j]);
                        }
                    }
                }
            }
        }

