class Solution
{
    // 最短距離を示す双方向グラフについて，
    // 各最短経路を維持できる辺の最小合計値を求める
    // 入力が不正な最短距離の場合は-1を返す
    public static long GetMinDistanceSum(long[][] dist)
    {
        long sum = 0;
        var first = 0;
        var n = dist.Length;

        // 辺ijを自身の辺を通らずkを経由したもので代替できるかチェック
        for (int i = first; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                long d = long.MaxValue;
                for (int k = first; k < n; k++)
                {
                    if (i == k || j == k)
                    {
                        continue;
                    }
                    if (dist[i][k] == long.MaxValue || dist[k][j] == long.MaxValue)
                    {
                        continue;
                    }
                    d = Math.Min(d, dist[i][k] + dist[k][j]);
                }
                // 代替不可であれば，必要な辺
                if (dist[i][j] < d)
                {
                    sum += dist[i][j];
                }
                // 直通経路が最短ではない．入力不正
                else if (dist[i][j] > d)
                {
                    return -1;
                }
            }
        }
        return sum;
    }

    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var graph = new long[n][];
        for (int i = 0; i < n; i++)
        {
            graph[i] = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        }
        var sum = GetMinDistanceSum(graph);
        Console.WriteLine(sum);
    }
}

