    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int[,] dist = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dist[i, j] = cin.nextInt();
            }
        }

        long ans = 0;

        for (int i = 0; i < N; i++)
        {
            if (dist[i, i] != 0)
            {
                Console.WriteLine("-1");
                return;
            }
            for (int j = i + 1; j < N; j++)
            {
                if(dist[i,j] != dist[j, i])
                {
                    Console.WriteLine("-1");
                    return;
                }
                int minDist = int.MaxValue;

                for (int k = 0; k < N; k++)
                {
                    if (k == i || k == j) continue;
                    minDist = Math.Min(minDist, dist[i, k] + dist[k, j]);
                }

                if(minDist < dist[i, j])
                {
                    Console.WriteLine("-1");
                    return;
                }
                else if(minDist == dist[i, j])
                {
                    continue;
                }
                else
                {
                    ans += dist[i, j];
                }
            }
        }
        Console.WriteLine(ans);
    }
}



