{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(solver());
        }
        static long solver()
        {
            var N = long.Parse(Console.ReadLine());
            var routes = new PriorityQueue<Route>(true);
            for (long i = 0; i < N; i++)
            {
                var read = Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
                for (long j = i + 1; j < N; j++) routes.Push(new Route(i + 1, j + 1, read[j]));
            }

            var roads = new List<Edge>();
            while (routes.Count() != 0)
            {
                var currentRoute = routes.Pop();
                var distance = new long[N + 1];
                for (long i = 0; i < N + 1; i++) distance[i] = long.MaxValue;
                distance[currentRoute.x] = 0;
                for (long i = 0; i < N; i++)
                {
                    foreach (Edge e in roads)
                    {
                        if (distance[e.from] == long.MaxValue) continue;
                        if (distance[e.to] > distance[e.from] + e.cost)
                            distance[e.to] = distance[e.from] + e.cost;
                    }
                }
                if (distance[currentRoute.y] > currentRoute.length)
                {
                    roads.Add(new Edge(currentRoute.x, currentRoute.y, currentRoute.length));
                    roads.Add(new Edge(currentRoute.y, currentRoute.x, currentRoute.length));
                }
                else if (distance[currentRoute.y] < currentRoute.length)
                {
                    return -1;
                }
                else { }
            }
            return roads.Sum(e => e.cost) / 2;
        }
    }
    struct Edge
    {
        public long from;
        public long to;
        public long cost;
        public Edge(long _from, long _to, long _cost)
        {
            from = _from;
            to = _to;
            cost = _cost;
        }
    }
    struct Route : IComparable<Route>
    {
        public long x;
        public long y;
        public long length;

        public Route(long _x, long _y, long _length)
        {
            x = _x;
            y = _y;
            length = _length;
        }
        public int CompareTo(Route other)
        {
            return length.CompareTo(other.length);
        }
    }

    class PriorityQueue<T> where T : IComparable<T>
    {
        private List<T> nodes;
        private Boolean isAsc;

        public PriorityQueue(Boolean _isAsc)
        {
            this.nodes = new List<T>();
            this.isAsc = _isAsc;
        }

        public long Count()
        {
            return this.nodes.Count;
        }
        public T Pop()
        {
            T returnNode = this.nodes[0];
            this.nodes[0] = this.nodes[nodes.Count - 1];
            this.nodes.RemoveAt(nodes.Count - 1);
            int root = 0;
            while (root * 2 + 1 < this.nodes.Count)
            {
                int child = root * 2 + 1;
                if (child + 1 < this.nodes.Count && compare(this.nodes[child + 1], this.nodes[child]) > 0) child += 1;
                if (compare(this.nodes[child], this.nodes[root]) > 0)
                {
                    swap(child, root);
                    root = child;
                }
                else
                {
                    break;
                }
            }
            return returnNode;
        }
        public T Top()
        {
            return this.nodes[0];
        }
        public void Push(T t)
        {
            this.nodes.Add(t);
            var addPosition = nodes.Count - 1;
            while (addPosition > 0)
            {
                var parent = (int)(addPosition - 1) / 2;
                if (compare(nodes[addPosition], nodes[parent]) > 0)
                {
                    swap(addPosition, parent);
                    addPosition = parent;
                }
                else
                {
                    break;
                }
            }
        }
        private long compare(T x, T y)
        {
            return this.isAsc ? y.CompareTo(x) : x.CompareTo(y);
        }
        private void swap(int x, int y)
        {
            T temp = nodes[x];
            nodes[x] = nodes[y];
            nodes[y] = temp;
        }
    }
}

