namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        private static long Solve(int N, int[][] A)
        {
            var roads = new long[N][];
            var distances = new long[N][];
            var tuples = new List<Tuple<int, int, int>>();
            for (int i = 0; i < N; ++i)
            {
                roads[i] = Enumerable.Repeat(long.MaxValue, N).ToArray();
                distances[i] = Enumerable.Repeat(long.MaxValue, N).ToArray();
                for (int j = i + 1; j < N; ++j)
                {
                    tuples.Add(new Tuple<int, int, int>(A[i][j], i, j));
                }
            }
            tuples.Sort();
            long sum = 0;
            foreach (var tuple in tuples)
            {
                int z = tuple.Item1;
                int a = tuple.Item2;
                int b = tuple.Item3;
                long d = distances[a][b];
                if (z < d)
                {
                    roads[a][b] = z;
                    roads[b][a] = z;
                    distances[a][b] = z;
                    distances[b][a] = z;
                    sum += z;
                    {
                        var q = new Queue<int>();
                        q.Enqueue(b);
                        while (q.Count > 0)
                        {
                            int i = q.Dequeue();
                            for (int j = 0; j < N; ++j)
                            {
                                if (roads[i][j] < long.MaxValue && distances[a][i] + roads[i][j] < distances[a][j])
                                {
                                    distances[a][j] = distances[a][i] + roads[i][j];
                                    distances[j][a] = distances[a][i] + roads[i][j];
                                    q.Enqueue(j);
                                }
                            }
                        }
                    }
                    {
                        var q = new Queue<int>();
                        q.Enqueue(a);
                        while (q.Count > 0)
                        {
                            int i = q.Dequeue();
                            for (int j = 0; j < N; ++j)
                            {
                                if (roads[i][j] < long.MaxValue && distances[b][i] + roads[i][j] < distances[b][j])
                                {
                                    distances[b][j] = distances[b][i] + roads[i][j];
                                    distances[j][b] = distances[b][i] + roads[i][j];
                                    q.Enqueue(j);
                                }
                            }
                        }
                    }
                }
                else if (z > d)
                {
                    return -1;
                }
            }
            return sum;
        }
        static void Main(string[] args)
        {
            int N = ReadInt();
            int[][] A = new int[N][];
            for (int i = 0; i < N; ++i) { A[i] = ReadInts(); }
            Console.WriteLine(Solve(N, A));
        }
    }
}

using System;
