public class PriorityQueue<TKey, TValue>
{
    SortedDictionary<TKey, HashSet<TValue>> dict = new SortedDictionary<TKey, HashSet<TValue>>();
    Dictionary<TValue, TKey> rDict = new Dictionary<TValue, TKey>();
    int count = 0;

    public int Count
    {
        get
        {
            return count;
        }
    }

    public void Enqueue(TKey key, TValue value)
    {
        if (!dict.ContainsKey(key))
        {
            dict[key] = new HashSet<TValue>();
        }

        var prev = dict[key].Count;
        if (!dict[key].Contains(value))
        {
            dict[key].Add(value);
            rDict[value] = key;
            count++;
        }
    }

    public KeyValuePair<TKey, TValue> Dequeue()
    {
        var queue = dict.First();
        if (queue.Value.Count <= 1)
        {
            dict.Remove(queue.Key);
        }

        var val = queue.Value.First();
        queue.Value.Remove(val);
        count--;
        rDict.Remove(val);
        return new KeyValuePair<TKey, TValue>(queue.Key, val);
    }

    public KeyValuePair<TKey, TValue> Peek()
    {
        var queue = dict.First();
        var val = queue.Value.First();
        return new KeyValuePair<TKey, TValue>(queue.Key, val);
    }

    public void ChangePriority(TKey newKey, TValue value)
    {
        ChangePriority(rDict[value], newKey, value);
    }

    public void ChangePriority(TKey prevKey, TKey newKey, TValue value)
    {
        var set = dict[prevKey];
        set.Remove(value);
        if (set.Count == 0)
        {
            dict.Remove(prevKey);
        }
        count--;

        Enqueue(newKey, value);
    }

    public bool ContainsValue(TValue val)
    {
        return rDict.ContainsKey(val);
    }
}

public struct Edge
{
    public readonly int Dest;
    public readonly long Weight;

    public Edge(int vd, long w)
    {
        Dest = vd;
        Weight = w;
    }
}
class Solution
{
    public static long[] Dijkstra(long[][] link, int start)
    {
        var n = link.Length;
        var d = Enumerable.Repeat(long.MaxValue, n).ToArray();
        d[start] = 0;
        var q = new PriorityQueue<long, int>();
        q.Enqueue(0, start);

        while (q.Count > 0)
        {
            var u = q.Dequeue();
            for (int v = 0; v < n; v++)
            {
                var len = link[u.Value][v];
                if (d[v] > d[u.Value] + len)
                {
                    d[v] = d[u.Value] + len;
                    if (q.ContainsValue(v))
                    {
                        q.ChangePriority(d[v], v);
                    }
                    else
                    {
                        q.Enqueue(d[v], v);
                    }
                }
            }
        }

        return d;
    }

    public static List<Edge> GetMinSpanningTree(Dictionary<int, List<Edge>> edges, int startVertex = 0)
    {
        var treeEdges = new List<Edge>();
        var treeVertex = new HashSet<int>() { startVertex };
        var nearEdges = new PriorityQueue<long, Edge>();
        foreach (var e in edges[startVertex])
        {
            nearEdges.Enqueue(e.Weight, e);
        }

        while (nearEdges.Count > 0)
        {
            var edge = nearEdges.Dequeue().Value;
            if (treeVertex.Contains(edge.Dest))
            {
                continue;
            }

            treeEdges.Add(edge);
            treeVertex.Add(edge.Dest);
            foreach (var e in edges[edge.Dest])
            {
                nearEdges.Enqueue(e.Weight, e);
            }
        }

        return treeEdges.ToList();
    }
    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var link = new long[n][];
        for (int i = 0; i < n; i++)
        {
            link[i] = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        }

        for (int i = 0; i < n; i++)
        {
            var d = Dijkstra(link, i);
            if (!d.SequenceEqual(link[i]))
            {
                Console.WriteLine(-1);
                return;
            }
        }

        var edges = new Dictionary<int, List<Edge>>();
        for (int i = 0; i < n; i++)
        {
            edges[i] = new List<Edge>();
            for (int j = 0; j < n; j++)
            {
                if (i != j)
                {
                    edges[i].Add(new Edge(j, link[i][j]));
                }
            }
        }

        var minTree = GetMinSpanningTree(edges);
        var length = minTree.Sum(e => e.Weight);
        Console.WriteLine(length);
    }
}

