		for (var i = 0; i < N; i++)
		{
			var I = G();
			for (var j = 0; j < N; j++) a[i, j] = I[j];
		}
		WriteLine(Check(a));
	}
	long Check(int[,] a)
	{
		for (var k = 0; k < N; k++) for (var v = 0; v < N; v++) for (var w = 0; w < N; w++) if (a[v, w] > a[v, k] + a[k, w]) return -1;
		var s = 0L;
		for (var i = 0; i < N; i++)
			for (var j = 0; j < i; j++)
			{
				var need = false;
				for (var k = 0; k < N; k++) if (k != i && k != j) need |= a[i, j] == a[i, k] + a[k, j];
				if (!need) s += a[i, j];
			}
		return s;
	}
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
	static void Main()
	{
		long n = long.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
    long[,] moveMatrix = new long[n,n];
    bool[,] smallerPath = new bool[n,n];//近道の存在
    bool answer = true;
    bool countPlus = true;
    long answerCount = 0;
    for(long i = 0; i < n; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      for(long j = 0; j < n; j++) moveMatrix[i,j] = nums[j];
    }

    for(int k = 0; k < n; k++)
    {
      for(int i = 0; i < n; i++)
      {
        for(int j = 0; j < n; j++)
        {
          if(moveMatrix[i,j] > moveMatrix[i,k] + moveMatrix[k,j])//近道が存在
          {
            answer = false;
          }else if(moveMatrix[i,j] == moveMatrix[i,k] + moveMatrix[k,j])
          {
            smallerPath[i,j] = true;
            smallerPath[j,i] = true;
          }
        }
      }
    }

    for(long i = 0; i < n; i++)
    {
      for(long j = i+1; j < n; j++)
      {
        if(!(smallerPath[i,j]) answer += moveMatrix[i,j];
      }
    }

		Console.WriteLine((answer) ? answerCount : "-1");
	}
}

