        int matiCount = int.Parse(Reader.ReadLine());

        for (int i = 0; i < matiCount; i++) {
            long[] inpt = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
            this.OriginalRoad.Add(i, new Dictionary<int, Road>());
            for (int j = 0; j < inpt.Length; j++) {
                if(this.OriginalRoad.ContainsKey(j)&& this.OriginalRoad[j].ContainsKey(i)) {
                    this.OriginalRoad[i].Add(j, this.OriginalRoad[j][i]);
                } else {
                    Road r = new Road(i, j, inpt[j]);
                    this.OriginalRoad[i].Add(j, r);
                    this.OriginalRoadList.Add(r);
                }
            }
        }
        OriginalRoadList.Sort((x, y) =>
        {
            return x.Length.CompareTo(y.Length);
        });
        long ans = 0;
        Dictionary<int, Dictionary<int, long>> RealRoad = new Dictionary<int, Dictionary<int, long>>();
        foreach(Road r in OriginalRoadList) {
            if(!RealRoad.ContainsKey(r.From)) {
                RealRoad.Add(r.From, new Dictionary<int, long>());
            }
            if(RealRoad[r.From].ContainsKey(r.To)) {
                if(RealRoad[r.From][r.To]==r.Length) {
                    continue;
                }else if(RealRoad[r.From][r.To]<r.Length) {
                    Console.WriteLine(-1);
                    return;
                }
            }
            ans += r.Length;
            RealRoad[r.From][r.To] = r.Length;
            if(!RealRoad.ContainsKey(r.To)) {
                RealRoad.Add(r.To, new Dictionary<int, long>());
            }
            RealRoad[r.To][r.From] = r.Length;
            Queue<int> que = new Queue<int>();
            que.Enqueue(r.From);
            que.Enqueue(r.To);
            while(que.Count>0) {
                int curr = que.Dequeue();
                int[] keys = RealRoad[curr].Keys.ToArray();
                for (int i = 0; i < keys.Length; i++) {
                    for (int j = i+1; j < keys.Length; j++) {
                        int keyI = keys[i];
                        int keyJ = keys[j];
                        if(RealRoad[keyI].ContainsKey(keyJ)&&RealRoad[keyI][keyJ]<=RealRoad[curr][keyI]+RealRoad[curr][keyJ]) {
                            continue;
                        }
                        RealRoad[keyI][keyJ] = RealRoad[curr][keyI] + RealRoad[curr][keyJ];
                        RealRoad[keyJ][keyI] = RealRoad[keyI][keyJ];
                        que.Enqueue(keyI);
                        que.Enqueue(keyJ);
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }

