using System.Collections.Generic;

namespace ARC083_D___Restoring_Road_Network
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(solver());
        }
        static long solver()
        {
            var N = long.Parse(Console.ReadLine());
            var routes = new PriorityQueue<Route>(true);
            for (long i = 0; i < N; i++)
            {
                var read = Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
                for (long j = i + 1; j < N; j++) routes.Push(new Route(i + 1, j + 1, read[j]));
            }

            long result = 0;
            var distance = new long[N + 1, N + 1];
            for (int i = 0; i < N + 1; i++) for (int j = 0; j < N + 1; j++) distance[i, j] = long.MaxValue;
            while (routes.Count() != 0)
            {
                var currentRoute = routes.Pop();
                if (distance[currentRoute.x, currentRoute.y] == currentRoute.length) continue;
                if (distance[currentRoute.x, currentRoute.y] < currentRoute.length) return -1;

                distance[currentRoute.x, currentRoute.y] = currentRoute.length;
                distance[currentRoute.y, currentRoute.x] = currentRoute.length;
                result += currentRoute.length;

                for (int via = 1; via < N + 1; via++)
                {
                    for (int from = 1; from < N + 1; from++)
                    {
                        if (distance[from, via] == long.MaxValue) continue;
                        for (int to = 1; to < N + 1; to++)
                        {
                            if (distance[via, to] == long.MaxValue) continue;
                            if (distance[from, to] > distance[via, to] + distance[from, via])
                                distance[from, to] = distance[via, to] + distance[from, via];
                        }
                    }
                }
            }
            return result;
        }
    }
    struct Route : IComparable<Route>
    {
        public long x;
        public long y;
        public long length;

        public Route(long _x, long _y, long _length)
        {
            x = _x;
            y = _y;
            length = _length;
        }
        public int CompareTo(Route other)
        {
            return length.CompareTo(other.length);
        }
    }

    class PriorityQueue<T> where T : IComparable<T>
    {
        private List<T> nodes;
        private Boolean isAsc;

        public PriorityQueue(Boolean _isAsc)
        {
            this.nodes = new List<T>();
            this.isAsc = _isAsc;
        }

        public long Count()
        {
            return this.nodes.Count;
        }
        public T Pop()
        {
            T returnNode = this.nodes[0];
            this.nodes[0] = this.nodes[nodes.Count - 1];
            this.nodes.RemoveAt(nodes.Count - 1);
            int root = 0;
            while (root * 2 + 1 < this.nodes.Count)
            {
                int child = root * 2 + 1;
                if (child + 1 < this.nodes.Count && compare(this.nodes[child + 1], this.nodes[child]) > 0) child += 1;
                if (compare(this.nodes[child], this.nodes[root]) > 0)
                {
                    swap(child, root);
                    root = child;
                }
                else
                {
                    break;
                }
            }
            return returnNode;
        }
        public T Top()
        {
            return this.nodes[0];
        }
        public void Push(T t)
        {
            this.nodes.Add(t);
            var addPosition = nodes.Count - 1;
            while (addPosition > 0)
            {
                var parent = (int)(addPosition - 1) / 2;
                if (compare(nodes[addPosition], nodes[parent]) > 0)
                {
                    swap(addPosition, parent);
                    addPosition = parent;
                }
                else
                {
                    break;
                }
            }
        }
        private long compare(T x, T y)
        {
            return this.isAsc ? y.CompareTo(x) : x.CompareTo(y);
        }
        private void swap(int x, int y)
        {
            T temp = nodes[x];
            nodes[x] = nodes[y];
            nodes[y] = temp;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Table2D<TKey, TValue>
{
    private readonly Dictionary<TKey, Dictionary<TKey, TValue>> dict = new Dictionary<TKey, Dictionary<TKey, TValue>>();

    public Dictionary<TKey, TValue> this[TKey key]
    {
        get { return dict[key]; }
    }

    public TValue GetValue(TKey key1, TKey key2, TValue defaultValue)
    {
        if (dict.ContainsKey(key1) && dict[key1].ContainsKey(key2))
        {
            return dict[key1][key2];
        }
        return defaultValue;
    }

    public Dictionary<TKey, Dictionary<TKey, TValue>>.KeyCollection Keys
    {
        get { return dict.Keys; }
    }

    public Dictionary<TKey, Dictionary<TKey, TValue>>.ValueCollection Values
    {
        get { return dict.Values; }
    }

    public int Count
    {
        get { return dict.Count; }
    }

    public void Add(TKey key1, TKey key2, TValue value)
    {
        if (!dict.ContainsKey(key1))
        {
            dict.Add(key1, new Dictionary<TKey, TValue>());
        }
        dict[key1].Add(key2, value);
    }

    public void Set(TKey key1, TKey key2, TValue value)
    {
        if (!dict.ContainsKey(key1))
        {
            dict.Add(key1, new Dictionary<TKey, TValue>());
        }
        dict[key1][key2] = value;
    }

    public bool Remove(TKey key1, TKey key2)
    {
        return dict[key1].Remove(key2);
    }

    public bool Remove(TKey key)
    {
        return dict.Remove(key);
    }

    public void Clear()
    {
        dict.Clear();
    }

    public IEnumerator<KeyValuePair<TKey, Dictionary<TKey, TValue>>> GetEnumerator()
    {
        foreach (var n in dict)
        {
            yield return n;
        }
    }

    public IEnumerable<Tuple<TKey, TKey, TValue>> GetFlatten()
    {
        foreach (var n in dict)
        {
            foreach (var v in n.Value)
            {
                yield return new Tuple<TKey, TKey, TValue>(n.Key, v.Key, v.Value);
            }
        }
    }
}

public class Graph
{
    // [点i][点j] = 距離 の有向グラフ
    public Table2D<int, long> Edges;
    // [MinVertexIndex, MaxVertexIndex)がIndexの存在区間
    public int MinVertexIndex;
    public int MaxVertexIndex;

    public Graph(int min, int max)
    {
        Edges = new Table2D<int, long>();
        MinVertexIndex = min;
        MaxVertexIndex = max;
    }

    public void AddEdge(int i, int j, long dist)
    {
        Edges.Add(i, j, dist);
    }

    public void SetEdge(int i, int j, long dist)
    {
        Edges.Set(i, j, dist);
    }

    // n
    // A1,1 A1,2 … A1,N
    // …
    // AN,1 AN,2 … AN,N
    // の形式から読み込む
    public static Graph BuildByReadLine(int origin = 0)
    {
        var n = int.Parse(Console.ReadLine());
        var graph = new Graph(origin, n);
        for (int i = 0; i < n; i++)
        {
            var row = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
            for (int j = 0; j < row.Length; j++)
            {
                graph.AddEdge(i + origin, j + origin, row[j]);
            }
        }
        return graph;
    }

    public long Distance(int i, int j)
    {
        if (i == j)
        {
            return 0;
        }
        return Edges.GetValue(i, j, long.MaxValue);
    }

    public static long Sum(long a, long b)
    {
        if (a == long.MaxValue || b == long.MaxValue)
        {
            return long.MaxValue;
        }
        return a + b;
    }

    public Graph WarshallFloyd()
    {
        var first = MinVertexIndex;
        var last = MaxVertexIndex;
        var dist = new Graph(first, last);

        for (int i = first; i < last; i++)
        {
            for (int j = first; j < last; j++)
            {
                dist.AddEdge(i, j, Distance(i, j));
            }
        }

        for (int k = first; k < last; k++)
        {
            for (int i = first; i < last; i++)
            {
                for (int j = first; j < last; j++)
                {
                    var newDist = Sum(dist.Distance(i, k), dist.Distance(k, j));
                    if (newDist < dist.Distance(i, j))
                    {
                        dist.SetEdge(i, j, newDist);
                    }
                }
            }
        }

        return dist;
    }

    // WarshallFloydで求めた双方向グラフについて，
    // 各最短経路を維持できる辺の最小合計値を求める
    public long GetMinDistanceSum()
    {
        long sum = 0;
        var first = MinVertexIndex;
        var last = MaxVertexIndex;

        // 辺ijを自身の辺を通らずkを経由したもので代替できるかチェック
        for (int i = first; i < last; i++)
        {
            for (int j = i+1; j < last; j++)
            {
                long d = long.MaxValue;
                for (int k = first; k < last; k++)
                {
                    if (i == k || j == k)
                    {
                        continue;
                    }
                    d = Math.Min(d, Distance(i, k) + Distance(k, j));
                }
                // 代替不可であれば，必要な辺
                if (Distance(i, j) < d)
                {
                    sum += Distance(i, j);
                }
            }
        }
        return sum;
    }
}

class Solution
{
    static void Main()
    {
        var graph = Graph.BuildByReadLine();
        var minDist = graph.WarshallFloyd();
        for(int i = 0; i < graph.MaxVertexIndex;i++)
        {
            for (int j = 0; j < graph.MaxVertexIndex; j++)
            {
                if(graph.Distance(i, j) != minDist.Distance(i, j))
                {
                    Console.WriteLine(-1);
                    return;
                }
            }
        }

        var sum = graph.GetMinDistanceSum();
        Console.WriteLine(sum);
    }
}

