    bik = b[i][k]
    (0...N).each{ |j|
      next if i == j || j == k
      v = bik + b[k][j]
      next if b[i][j] < v
      if v == b[i][j]
        c[i][j] = 0
      else
        puts -1; exit
      end

    }
  }
}

