				continue
			}
			ret := 100000000000
			for k := 0; k < N; k++ {
				if i == k || j == k {
					continue
				}

				if A[i][j] > A[i][k]+A[k][j] {
					fmt.Println(-1)
					os.Exit(0)
				} else {
					ret = min(ret, A[i][k]+A[k][j])
				}
			}
			if A[i][j] < ret {
				//fmt.Println("found",i,j)
				ans += A[i][j]
			}
		}
	}
	fmt.Println(ans)
}

