func nextLine() string {
	sc.Scan()
	return sc.Text()
}

func Filter(s []string) []int {
	var p []int // == nil
	var val int
	for _, v := range s {
		val, _ = strconv.Atoi(v)
		p = append(p, val)
	}
	return p
}

func min(x, y int) int {
	if x < y {
		return x
	}
	return y
}

