package main

import "fmt"

func solve() int {
    var n int
    fmt.Scan(&n)
    table := make([][]int, n)
    for i := 0; i < n; i++ {
        table[i] = make([]int, n)
        for j := 0; j < n; j++ {
            var x int
            fmt.Scan(&x)
            table[i][j] = x
        }
    }

    not_used := make([][]bool, n)
    for i := 0; i < n; i++ {
        not_used[i] = make([]bool, n)
    }

    for k := 0; k < n; k++ {
        for i := 0; i < n; i++ {
            for j := 0; j < n; j++ {
                if i != k && j != k {
                    if table[i][j] > table[i][k] + table[j][k] {
                        return -1
                    } else if table[i][j] == table[i][k] + table[j][k] {
                        table[i][j] = table[i][k] + table[j][k]
                        not_used[i][j] = true
                    }
                }
            }
        }
    }

    ret := 0
    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            if not_used[i][j] == false {
                ret += table[i][j]
            }
        }
    }
    ret >>= 1
    return ret
}

