long INF = long.max/3;
void main() {
    int N = readln.chomp.to!int;
    long[][] mat = N.rep!(() => readln.split.to!(long[]));

    foreach(i; 0..N) foreach(j; 0..N) {
        if (N.iota.map!(k => mat[i][k]+mat[k][j]).reduce!min < mat[i][j]) {
            (-1).writeln;
            return;
        }
    }

    long[][] po = N.rep!(()=>N.rep!(()=>INF));
    foreach(i; 0..N) po[i][i] = 0;

    void update() {
        foreach(i; 0..N) foreach(j; 0..N) {
            po[i][j] = N.iota.map!(k => po[i][k]+po[k][j]).reduce!min;
        }
    }

    long ans = 0;
    struct P{size_t i, j;}
    new std.concurrency.Generator!P({
        foreach(i; 0..N) foreach(j; i+1..N) {
            P(i, j).yield;
        }
    }).array.sort!(
        (a, b) => mat[a.i][a.j] < mat[b.i][b.j]
    ).each!(
        (a) {
            assert(mat[a.i][a.j] <= po[a.i][a.j]);
            if (mat[a.i][a.j] < po[a.i][a.j]) {
                ans += mat[a.i][a.j];
                po[a.i][a.j] = mat[a.i][a.j];
                po[a.j][a.i] = mat[a.j][a.i];
                update();
            }
        }
    );

    ans.writeln;

}

