long INF = long.max/3;
void main() {
    int N = readln.chomp.to!int;
    long[][] mat = N.rep!(() => readln.split.to!(long[]));

    foreach(i; 0..N) foreach(j; 0..N) {
        if (N.iota.map!(k => mat[i][k]+mat[k][j]).reduce!min < mat[i][j]) {
            (-1).writeln;
            return;
        }
    }

