import std.typecons, std.range, std.random, std.math, std.container;
import std.numeric, std.bigint, core.bitop;

void main() {
    auto N = readln.chomp.to!int;
    auto A = N.iota.map!(_ => readln.split.map!(to!long).array).array;

    bool ok = true;
    auto unused = new int[][](N, N);

    foreach (i; 0..N)
        foreach (j; 0..N)
            foreach (k; 0..N)
                if (A[j][k] > A[j][i] + A[i][k])
                    ok = false;
                else if (i != j && i != k && A[j][k] == A[j][i] + A[i][k])
                    unused[j][k] = true;

    if (!ok) {
        writeln(-1);
    } else {
        long ans = 0;
        foreach (i; 0..N)
            foreach (j; i+1..N)
                if (!unused[i][j])
                    ans += A[i][j];
        ans.writeln;
    }
}

void main(){
  import std.stdio, std.string, std.conv, std.algorithm;
  import std.math;

  int n; rd(n);
  auto a=new long[][](n, n);
  foreach(i; 0..n) a[i]=readln.split.to!(long[]);

  auto d=new long[][](n, n);
  const inf=to!long(1e18);
  foreach(i; 0..n)foreach(j; 0..n) d[i][j]=a[i][j];
  foreach(_; 0..n)foreach(i; 0..n)foreach(j; 0..n){
    d[i][j]=min(d[i][j], d[i][_]+d[_][j]);
  }
  foreach(i; 0..n)foreach(j; 0..n){
    if(d[i][j]<a[i][j]){
      writeln("-1"); return;
    }
  }
