    if(i!=k && j!=k && a[i][j]==a[i][k]+a[k][j]){
      a[i][j]=a[j][i]=inf;
    }
  }
  long sm=0;
  foreach(i; 0..n)foreach(j; 0..i){
    if(a[i][j]!=inf) sm+=a[i][j];
  }

