def II(): return int(input())
def ILI(): return list(map(int, input().split()))


def read():
    N = II()
    matrix = [ILI() for __ in range(N)]
    return N, matrix


def check_first(matrix):
    t_matrix = list(map(list, zip(*matrix)))
    for i, (row, t_row) in enumerate(zip(matrix, t_matrix)):
        if row[i] != 0:
            return False
        for ele, t_ele in zip(row, t_row):
            if ele != t_ele:
                return False
    return True


def solve(N, matrix):
    if check_first(matrix) is False:
        return -1
    ano_matrix = [[10 ** 9] * N for __ in range(N)]
    for a, b, c in itertools.product(range(N), repeat=3):
        new_length = matrix[a][b] + matrix[b][c]
        ano_matrix[a][c] = min(ano_matrix[a][c], new_length)
    for row, ano_row in zip(matrix, ano_matrix):
        for ele, ano_ele in zip(row, ano_row):
            if ele != ano_ele:
                return -1

    # Prim 法で最小全域木を求める
    ans = 0
    s_nodes = set()
    s_nodes.add(0)
    while len(s_nodes) < N:
        other_nodes = set(range(N)) - s_nodes
        len_edge = 10 * 9
        f_node = None
        t_node = None
        for from_node in s_nodes:
            for to_node in other_nodes:
                if matrix[from_node][to_node] < len_edge:
                    f_node = from_node
                    t_node = to_node
        s_nodes.add(t_node)
        ans += matrix[f_node][t_node]
    return ans


def main():
    params = read()
    print(solve(*params))


if __name__ == "__main__":
    main()

