def warshall_floyd(d):
    """Warshall Floyd method"""

    n = len(d)
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if d[i][j] > d[i][k] + d[k][j]:
                    d[i][j] = d[i][k] + d[k][j]

def solve(f):
    n = f.read_int()
    a = [f.read_int_list() for _ in xrange(n)]

    aorg = copy.deepcopy(a)
    warshall_floyd(a)

    for i in xrange(n):
        for j in xrange(n):
            if aorg[i][j] != a[i][j]: return -1

    ans = 0
    for i in xrange(n):
        for j in xrange(n):
            if i == j: continue
            for k in xrange(n):
                if i == k or j == k: continue
                if a[i][j] == a[i][k] + a[k][j]: break
            else:
                ans += a[i][j]

    return ans/2


