import heapq

def Dijkstra(numV, v_st):

    cost = [float('inf') for i in range(numV)]
    cost[v_st] = 0
    num = [0 for i in range(numV)]

    pq = []
    heapq.heappush(pq, (0, v_st))

    while pq:
        c_min, v_now = heapq.heappop(pq)

        if cost[v_now] < c_min:
            continue

        for v, c in adj[v_now].items():
            if cost[v_now] + c < cost[v]:
                cost[v] = cost[v_now] + c
                num[v] = num[v_now] + 1
                heapq.heappush(pq, (cost[v], v))
            elif cost[v_now] + c == cost[v]:
                if num[v] == 1:
                    del adj[v_st][v]
                    del adj[v][v_st]
                elif num[v_now] + 1 == 1:
                    del adj[v_now][v]
                    del adj[v][v_now]
                num[v] = max(num[v], num[v_now] + 1)

    return cost

