import itertools
import heapq


def II(): return int(input())
def ILI(): return list(map(int, input().split()))


def read():
    N = II()
    matrix = [ILI() for __ in range(N)]
    return N, matrix


def check_first(matrix):
    t_matrix = list(map(list, zip(*matrix)))
    for i, (row, t_row) in enumerate(zip(matrix, t_matrix)):
        if row[i] != 0:
            return False
        for ele, t_ele in zip(row, t_row):
            if ele != t_ele:
                return False
    return True


def solve(N, matrix):
    if check_first(matrix) is False:
        return -1
    ano_matrix = [[10 ** 9] * N for __ in range(N)]
    for a, b, c in itertools.product(range(N), repeat=3):
        new_length = matrix[a][b] + matrix[b][c]
        ano_matrix[a][c] = min(ano_matrix[a][c], new_length)
    for row, ano_row in zip(matrix, ano_matrix):
        for ele, ano_ele in zip(row, ano_row):
            if ele != ano_ele:
                return -1

    # Prim 法で最小全域木を求める
    ans = 0
    s_nodes = set()
    s_nodes.add(0)
    edges = []
    for i in range(1, N):
        edges.append((matrix[0][i], i))
    heapq.heapify(edges)
    while len(s_nodes) < N:
        while True:
            l, to = heapq.heappop(edges)
            if to in s_nodes:
                continue
            else:
                ans += l
                s_nodes.add(to)
                for i in range(N):
                    if i in s_nodes:
                        continue
                    else:
                        heapq.heappush(edges, (matrix[to][i], i))
                break
    return ans


def main():
    params = read()
    print(solve(*params))


if __name__ == "__main__":
    main()

