const INF: u64 = 1_000_000_000_000;

fn solve(a: &[Vec<u64>]) -> Option<u64> {
    let n = a[0].len();
    let mut dist = a.to_vec();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if a[i][k] + a[k][j] < a[i][j] {
                    return None;
                } else if a[i][k] + a[k][j] == a[i][j] && k != i && k != j {
                    dist[i][j] = INF;
                }
            }
        }
    }

    let mut ans = 0;
    for i in 0..n-1 {
        for j in i+1..n {
            if dist[i][j] != INF {
                ans += dist[i][j];
            }
        }
    }
    Some(ans)
}

