fn main() {
    input! {
        n: usize,
        edges: [[i64; n]; n],
    };

    let mut dp = edges;
    let mut needed = vec![vec![true; n]; n];
    let mut exists = true;

    for k in 0..n {
        for i in (0..n).filter(|&i| i != k) {
            for j in (i..n).filter(|&j| j != k) {
                let t = dp[i][k] + dp[k][j];

                match dp[i][j].cmp(&t) {
                    Ordering::Equal => {
                        needed[i][j] = false;
                    }
                    Ordering::Greater => {
                        dp[i][j] = t;
                        needed[i][j] = false;
                        exists = false;
                    }
                    _ => {}
                }
                if t <= dp[i][j] {
                    dp[i][j] = t;
                    needed[i][j] = false;
                }
            }
        }
    }

    let ans = if exists {
        (0..n)
            .map(|i| {
                (i..n)
                    .filter(|&j| needed[i][j])
                    .map(|j| dp[i][j])
                    .sum::<i64>()
            })
            .sum::<i64>()
    } else {
        -1
    };
    println!("{}", ans);
}

