    let n = readln();
    let mut xs = vec![vec![0; n]; n];
    let mut res = 0i64;

    for i in 0..n {
        let vs = reads();

        for (j, &v) in vs.iter().enumerate() {
            xs[i][j] = v;
            res += v;
        }
    }

    res /= 2;

    'outer:
    for i in 0..n {
        for j in i..n {
            for k in 0..n {
                if i == k || j == k {
                    continue;
                }

                if xs[i][j] > xs[i][k] + xs[k][j] {
                    res = -1;
                    break 'outer;
                }
                if xs[i][j] == xs[i][k] + xs[k][j] {
                    res -= xs[i][j];
                }
            }
        }
    }

    println!("{}", res);
