    let n: usize = util::get();
    let d: Vec<Vec<usize>> = (0..n).map(|_| util::gets()).collect();
    // warshall floyd
    let mut short_dist = 0;
    for a in 0..n {
        for b in a + 1..n {
            let mut need = true;
            for c in 0..n {
                if c == a || c == b {
                    continue;
                }
                let direct = d[a][b];
                let indirect = d[a][c] + d[c][b];

                match direct.cmp(&indirect) {
                    Ordering::Greater => {
                        println!("-1");
                        return;
                    }
                    Ordering::Equal => need = false,
                    Ordering::Less => (),
                }
            }
            if need {
                short_dist += d[a][b];
            }
        }
    }

    println!("{}", short_dist);
}

