fn solve(table: &Vec<Vec<i64>>) -> i64 {
    let mut ans = 0;
    for start in 0..table.len() {
        for end in start..table.len() {
            let mut needed = true;
            for relay in 0..table.len() {
                if start==relay || end==relay { continue }
                if table[start][relay] + table[relay][end] < table[start][end] {
                    return -1;
                } else if table[start][relay] + table[relay][end] == table[start][end] {
                    needed = false;
                    break
                }
            }
            ans = if needed { ans + table[start][end] } else { ans };
        }
    }
    ans
}

