    for (length, i, j) in lengths {
        let mut min_constructed_length = std::usize::MAX;
        for k in 0..n {
            if constructed_roads.contains(&(i, k)) && constructed_roads.contains(&(j, k)) {
                min_constructed_length = std::cmp::min(grid[i][k] + grid[j][k], min_constructed_length);
            }
        }
        if length > min_constructed_length {
            println!("-1");
            return;
        }
        if length < min_constructed_length {
            ans += length;
        }
        constructed_roads.insert((i, j));
        constructed_roads.insert((j, i));
    }
    println!("{:?}", ans);
}

use proconio::input;
fn main() {
    input!(n: usize, a: [[u64; n]; n]);
    let mut ans = 0;
    for i in 0..n {
        for j in i + 1..n {
            for k in 0..n {
                if a[i][k] + a[k][j] < a[i][j] {
                    println!("-1");
                    std::process::exit(0);
                }
            }
            if (0..n)
                .filter(|&k| k != i && k != j)
                .all(|k| a[i][k] + a[k][j] > a[i][j])
            {
                ans += a[i][j];
            }
        }
    }
    println!("{}", ans);
}
